const MATH_CHAPTERS = [{"num":1,"title":"Số hữu tỉ","icon":"①"},{"num":2,"title":"Số thực","icon":"②"},{"num":3,"title":"Góc và đường thẳng song song","icon":"③"},{"num":4,"title":"Tam giác bằng nhau","icon":"④"},{"num":5,"title":"Thu thập và biểu diễn dữ liệu","icon":"⑤"}];
const MATH_QUESTIONS = [{"id":"m1-1","ch":1,"topic":"Số hữu tỉ","q":"Số hữu tỉ x được viết dưới dạng nào?","options":["x = a/b ; a, b ∈ ℤ ; b ≠ 0","x = a/b ; a, b ∈ ℤ ; a ≠ 0","x = a/b ; a, b ∈ ℕ ; b ≠ 0","x = a/b ; a, b ∈ ℤ ; b = 0"],"correct":0,"answer":"x = a/b ; a, b ∈ ℤ ; b ≠ 0","explanation":"🔑 x ∈ ℚ ⇔ x = a/b với <b>a, b ∈ ℤ</b> và <b>b ≠ 0</b>: tử và mẫu đều là số NGUYÊN, mẫu KHÁC 0.<br>✗ Điều kiện a ≠ 0 là sai: tử được phép bằng 0, ví dụ 0/5 = 0 vẫn là số hữu tỉ.<br>✗ Điều kiện a, b ∈ ℕ là sai: ℕ chỉ có số tự nhiên, sẽ mất hết số hữu tỉ âm như −3/4.<br>✗ Điều kiện b = 0 là sai: chia cho 0 không có nghĩa."},{"id":"m1-2","ch":1,"topic":"Số hữu tỉ","q":"Trong cách viết x = a/b của một số hữu tỉ, mẫu số b phải thoả điều kiện nào?","options":["b > 0","b ≠ 1","b ≠ 0","b ∈ ℕ"],"correct":2,"answer":"b ≠ 0","explanation":"🔑 Mẫu chỉ cần <b>khác 0</b>, vì phép chia cho 0 không có nghĩa.<br>✗ b > 0: mẫu âm vẫn được, ví dụ 3/(−4) = −3/4 vẫn là số hữu tỉ.<br>✗ b ≠ 1: mẫu bằng 1 hoàn toàn hợp lệ, ví dụ 5 = 5/1.<br>✗ b ∈ ℕ: mẫu là số nguyên, có thể âm, không bắt buộc là số tự nhiên."},{"id":"m1-3","ch":1,"topic":"Số đối","q":"Số đối của số hữu tỉ a/b là số nào?","options":["b/a","−a/b","|a/b|","a/b"],"correct":1,"answer":"−a/b","explanation":"🔑 Số đối của a/b là <b>−a/b</b>: chỉ ĐỔI DẤU, giữ nguyên tử và mẫu.<br>✗ b/a là số NGHỊCH ĐẢO (lật ngược phân số), tích của chúng bằng 1 chứ không phải tổng bằng 0.<br>✗ |a/b| là giá trị tuyệt đối, luôn không âm.<br>✗ a/b chính là số ban đầu, chưa đổi dấu."},{"id":"m1-4","ch":1,"topic":"Số đối","q":"Số đối của −3/5 là số nào?","options":["−5/3","5/3","−3/5","3/5"],"correct":3,"answer":"3/5","explanation":"🔑 Đổi dấu là xong: số đối của −3/5 là <b>3/5</b>, vì −3/5 + 3/5 = 0.<br>✗ −5/3: đã lật tử mẫu (nghịch đảo) mà còn giữ dấu âm.<br>✗ 5/3: đó là số nghịch đảo của −3/5 sau khi đổi dấu, không phải số đối.<br>✗ −3/5: giữ nguyên số ban đầu, chưa đổi dấu."},{"id":"m1-5","ch":1,"topic":"Số đối","q":"Tổng của một số hữu tỉ và số đối của nó bằng bao nhiêu?","options":["0","1","2 · (a/b)","−1"],"correct":0,"answer":"0","explanation":"🔑 a/b + (−a/b) = <b>0</b>. Hai số đối nhau luôn triệt tiêu.<br>✗ 1: đó là kết quả khi NHÂN một số với số nghịch đảo của nó.<br>✗ 2 · (a/b): đó là kết quả khi cộng số đó với CHÍNH NÓ, không phải với số đối.<br>✗ −1: sai dấu, tổng hai số đối luôn bằng 0 chứ không âm."},{"id":"m1-6","ch":1,"topic":"Số hữu tỉ","q":"Cách viết nào sau đây KHÔNG cho ta một số hữu tỉ?","options":["0/3","3/0","−7/1","2/5"],"correct":1,"answer":"3/0","explanation":"🔑 Mẫu bắt buộc khác 0, nên <b>3/0</b> không có nghĩa và không phải số hữu tỉ.<br>✗ 0/3 = 0: tử bằng 0 vẫn hợp lệ vì mẫu khác 0.<br>✗ −7/1 = −7: mọi số nguyên đều là số hữu tỉ nhờ cách viết a/1.<br>✗ 2/5 là phân số bình thường, mẫu 5 ≠ 0."},{"id":"m1-7","ch":1,"topic":"Số hữu tỉ","q":"Vì sao mọi số nguyên a đều là số hữu tỉ?","options":["a = 1/a","a = a/0","a = a/1","a = 0/a"],"correct":2,"answer":"a = a/1","explanation":"🔑 Mọi số nguyên a viết được thành <b>a/1</b> với mẫu 1 ≠ 0, nên a ∈ ℚ.<br>✗ a = 1/a chỉ đúng khi a = 1 hoặc a = −1.<br>✗ a = a/0 sai vì mẫu bằng 0 là vô nghĩa.<br>✗ a = 0/a luôn cho giá trị 0, chỉ đúng khi a = 0 (mà lúc đó mẫu lại bằng 0)."},{"id":"m1-8","ch":1,"topic":"Số hữu tỉ","q":"Kí hiệu nào diễn tả đúng câu: x là số hữu tỉ?","options":["x ∈ ℚ","x ∈ ℤ","x ∈ ℕ","ℚ ∈ x"],"correct":0,"answer":"x ∈ ℚ","explanation":"🔑 Tập số hữu tỉ kí hiệu là <b>ℚ</b>, nên viết <b>x ∈ ℚ</b>.<br>✗ x ∈ ℤ nghĩa là x là số nguyên — hẹp hơn số hữu tỉ.<br>✗ x ∈ ℕ nghĩa là x là số tự nhiên — hẹp hơn nữa.<br>✗ ℚ ∈ x viết ngược: phần tử đứng trước, tập hợp đứng sau."},{"id":"m1-9","ch":1,"topic":"Số đối","q":"Số đối của số hữu tỉ x được kí hiệu là gì?","options":["1/x","|x|","x⁻¹","−x"],"correct":3,"answer":"−x","explanation":"🔑 Số đối của x kí hiệu là <b>−x</b>, vì x + (−x) = 0.<br>✗ 1/x là số nghịch đảo, tích bằng 1 chứ không phải tổng bằng 0.<br>✗ |x| là giá trị tuyệt đối, luôn ≥ 0.<br>✗ x⁻¹ chính là 1/x — vẫn là nghịch đảo, không phải số đối."},{"id":"m1-10","ch":1,"topic":"Số hữu tỉ","q":"Phân số nào dưới đây biểu diễn CÙNG một số hữu tỉ với 2/3?","options":["3/2","4/6","2/6","4/3"],"correct":1,"answer":"4/6","explanation":"🔑 Nhân cả tử VÀ mẫu với cùng một số khác 0 thì giá trị không đổi: 2/3 = (2·2)/(3·2) = <b>4/6</b>.<br>✗ 3/2 là phân số nghịch đảo, giá trị khác hẳn.<br>✗ 2/6: chỉ nhân mẫu với 2, quên nhân tử, kết quả thành 1/3.<br>✗ 4/3: chỉ nhân tử với 2, quên nhân mẫu."},{"id":"m1-11","ch":1,"topic":"Số đối","q":"Cho x = 7/(−4). Số đối của x là số nào?","options":["−7/4","−4/7","7/4","4/7"],"correct":2,"answer":"7/4","explanation":"🔑 Đưa dấu âm lên tử: 7/(−4) = −7/4, nên số đối của nó là <b>7/4</b>.<br>✗ −7/4 chính là x, chưa đổi dấu.<br>✗ −4/7: lật tử mẫu (nghịch đảo) và giữ dấu âm.<br>✗ 4/7: lật tử mẫu, đó là nghịch đảo chứ không phải số đối."},{"id":"m1-12","ch":1,"topic":"Số hữu tỉ","q":"Điều kiện nào KHÔNG bắt buộc trong định nghĩa số hữu tỉ x = a/b?","options":["a ≠ 0","b ≠ 0","a ∈ ℤ","b ∈ ℤ"],"correct":0,"answer":"a ≠ 0","explanation":"🔑 Định nghĩa chỉ đòi hỏi a, b ∈ ℤ và b ≠ 0. Tử được phép bằng 0 (0/7 = 0 vẫn là số hữu tỉ) nên <b>a ≠ 0 KHÔNG bắt buộc</b>.<br>✗ b ≠ 0 là điều kiện bắt buộc, bỏ đi thì phép chia vô nghĩa.<br>✗ a ∈ ℤ bắt buộc: tử phải là số nguyên.<br>✗ b ∈ ℤ bắt buộc: mẫu phải là số nguyên."},{"id":"m1-13","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A + B = C, quy tắc chuyển vế cho ta điều gì?","options":["A = C + B","A = C − B","A = B − C","A = B + C"],"correct":1,"answer":"A = C − B","explanation":"🔑 Chuyển B sang vế phải thì phải ĐỔI DẤU: A + B = C ⇒ <b>A = C − B</b>.<br>✗ A = C + B: chuyển vế mà giữ nguyên dấu — lỗi phổ biến nhất.<br>✗ A = B − C: đảo ngược thứ tự nên kết quả trái dấu.<br>✗ A = B + C: sai cả dấu lẫn vị trí."},{"id":"m1-14","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A − B = C, quy tắc chuyển vế cho ta điều gì?","options":["A = C − B","A = B − C","A = −C − B","A = C + B"],"correct":3,"answer":"A = C + B","explanation":"🔑 A − B = C ⇒ <b>A = C + B</b>: dấu trừ khi qua vế kia thì thành dấu cộng.<br>✗ A = C − B: giữ nguyên dấu trừ, tức là quên đổi dấu.<br>✗ A = B − C: đảo ngược thứ tự nên trái dấu với đáp án đúng.<br>✗ A = −C − B: đổi dấu tuỳ tiện cả hai số hạng."},{"id":"m1-15","ch":1,"topic":"Chuyển vế","q":"Khi chuyển một số hạng từ vế này sang vế kia của một đẳng thức, ta phải làm gì với số hạng đó?","options":["Giữ nguyên dấu","Đổi dấu","Lấy nghịch đảo","Bình phương lên"],"correct":1,"answer":"Đổi dấu","explanation":"🔑 Quy tắc chuyển vế: chuyển một số hạng sang vế kia thì <b>ĐỔI DẤU</b> số hạng đó (dấu + thành −, dấu − thành +).<br>✗ Giữ nguyên dấu: đẳng thức sẽ sai ngay, ví dụ 2 + x = 9 mà viết x = 9 + 2.<br>✗ Lấy nghịch đảo: đó là thao tác liên quan tới phép nhân/chia, không phải chuyển vế.<br>✗ Bình phương lên: không có quy tắc nào như vậy khi chuyển vế."},{"id":"m1-16","ch":1,"topic":"Chuyển vế","q":"Tìm x biết x + 3/4 = 5/4. Bước chuyển vế đúng là gì?","options":["x = 5/4 − 3/4","x = 5/4 + 3/4","x = 3/4 − 5/4","x = 5/4 · 3/4"],"correct":0,"answer":"x = 5/4 − 3/4","explanation":"🔑 Chuyển 3/4 sang vế phải và đổi dấu: <b>x = 5/4 − 3/4</b> = 2/4 = 1/2.<br>✗ x = 5/4 + 3/4: quên đổi dấu khi chuyển vế.<br>✗ x = 3/4 − 5/4: đảo ngược thứ tự, cho kết quả trái dấu.<br>✗ x = 5/4 · 3/4: chuyển vế chỉ dùng phép cộng - trừ, không dùng phép nhân."},{"id":"m1-17","ch":1,"topic":"Chuyển vế","q":"Tìm x biết x − 2/5 = 1/5. Bước chuyển vế đúng là gì?","options":["x = 1/5 − 2/5","x = 2/5 − 1/5","x = 1/5 + 2/5","x = 1/5 : 2/5"],"correct":2,"answer":"x = 1/5 + 2/5","explanation":"🔑 A − B = C ⇒ A = C + B, nên <b>x = 1/5 + 2/5</b> = 3/5.<br>✗ x = 1/5 − 2/5: giữ nguyên dấu trừ, quên đổi dấu khi chuyển vế.<br>✗ x = 2/5 − 1/5: đảo vị trí hai số hạng.<br>✗ x = 1/5 : 2/5: chuyển vế không dùng phép chia."},{"id":"m1-18","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức x + a = b, giá trị của x là gì?","options":["x = b + a","x = a − b","x = a + b","x = b − a"],"correct":3,"answer":"x = b − a","explanation":"🔑 Chuyển a sang vế phải và đổi dấu: <b>x = b − a</b>.<br>✗ x = b + a: quên đổi dấu của a.<br>✗ x = a − b: đảo ngược thứ tự nên trái dấu với đáp án đúng.<br>✗ x = a + b: sai cả dấu lẫn vị trí."},{"id":"m1-19","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A + B = C, biểu thức đúng của B là gì?","options":["B = C − A","B = C + A","B = A − C","B = A + C"],"correct":0,"answer":"B = C − A","explanation":"🔑 Chuyển A sang vế phải và đổi dấu: <b>B = C − A</b>.<br>✗ B = C + A: quên đổi dấu của A khi chuyển vế.<br>✗ B = A − C: đảo ngược thứ tự nên trái dấu.<br>✗ B = A + C: sai hoàn toàn quy tắc chuyển vế."},{"id":"m1-20","ch":1,"topic":"Chuyển vế","q":"Từ đẳng thức A − B = C, biểu thức đúng của B là gì?","options":["B = C − A","B = C + A","B = A − C","B = A + C"],"correct":2,"answer":"B = A − C","explanation":"🔑 A − B = C ⇒ A = C + B ⇒ <b>B = A − C</b>: chuyển B sang phải thành +B, rồi chuyển C sang trái thành −C.<br>✗ B = C − A: đảo ngược thứ tự nên kết quả trái dấu.<br>✗ B = C + A: sai dấu của A.<br>✗ B = A + C: quên đổi dấu của C khi chuyển vế."},{"id":"m1-21","ch":1,"topic":"Chuyển vế","q":"Tìm x biết x + (−1/3) = 2/3. Giá trị của x là bao nhiêu?","options":["1/3","−1/3","−1","1"],"correct":3,"answer":"1","explanation":"🔑 Số hạng đang mang dấu âm, chuyển sang vế phải thì thành dấu cộng: x = 2/3 + 1/3 = <b>1</b>.<br>✗ 1/3: đã trừ 1/3 thay vì cộng — quên rằng số hạng vốn mang dấu âm.<br>✗ −1/3: sai dấu ở kết quả cuối cùng.<br>✗ −1: đổi dấu tuỳ tiện cả hai số hạng, thành −2/3 − 1/3."},{"id":"m1-22","ch":1,"topic":"Chuyển vế","q":"Tìm x biết 5 − x = 2. Giá trị của x là bao nhiêu?","options":["−3","3","7","−7"],"correct":1,"answer":"3","explanation":"🔑 5 − x = 2 ⇒ 5 − 2 = x ⇒ x = <b>3</b>. Thử lại: 5 − 3 = 2 đúng.<br>✗ −3: đổi dấu thừa một lần vì quên rằng x đang mang dấu trừ.<br>✗ 7: lấy 5 + 2 thay vì 5 − 2.<br>✗ −7: vừa cộng sai vừa gắn thêm dấu âm."},{"id":"m1-23","ch":1,"topic":"Chuyển vế","q":"Đẳng thức nào là kết quả chuyển vế ĐÚNG của x − 3 = 7?","options":["x = 7 − 3","x = 3 − 7","x = −7 − 3","x = 7 + 3"],"correct":3,"answer":"x = 7 + 3","explanation":"🔑 Số hạng −3 chuyển sang vế phải thì thành +3: <b>x = 7 + 3</b> = 10. Thử lại: 10 − 3 = 7 đúng.<br>✗ x = 7 − 3: giữ nguyên dấu trừ, quên đổi dấu.<br>✗ x = 3 − 7: đảo vị trí nên ra kết quả âm.<br>✗ x = −7 − 3: đổi dấu nhầm cả vế phải."},{"id":"m1-24","ch":1,"topic":"Chuyển vế","q":"Bạn An giải: từ 2 + x = 9 suy ra x = 9 + 2. Bạn ấy sai ở chỗ nào?","options":["Chuyển số 2 sang vế phải mà không đổi dấu","Chuyển số 2 sang vế phải và đã đổi dấu","Cộng hai vế với 2","Nhân hai vế với 2"],"correct":0,"answer":"Chuyển số 2 sang vế phải mà không đổi dấu","explanation":"🔑 Chuyển vế phải đổi dấu: 2 + x = 9 ⇒ x = 9 − 2 = 7. An giữ nguyên dấu cộng nên sai.<br>✗ Nói An đã đổi dấu là không đúng: nếu đổi dấu thì phải viết 9 − 2 chứ không phải 9 + 2.<br>✗ Cộng hai vế với 2: nếu làm vậy vế trái thành 4 + x, càng không tách được x.<br>✗ Nhân hai vế với 2: An không hề nhân, và phép nhân cũng không giúp tách x ra khỏi số 2."},{"id":"m1-25","ch":1,"topic":"Lũy thừa","q":"Với x ≠ 0, giá trị của x⁰ là bao nhiêu?","options":["0","1","x","1/x"],"correct":1,"answer":"1","explanation":"🔑 Mọi số khác 0 nâng lên mũ 0 đều bằng 1: <b>x⁰ = 1</b> (x ≠ 0).<br>✗ 0: nhầm SỐ MŨ 0 với giá trị 0 của cả luỹ thừa.<br>✗ x: đó là giá trị của x¹.<br>✗ 1/x: đó là giá trị của x⁻¹."},{"id":"m1-26","ch":1,"topic":"Lũy thừa","q":"Giá trị của x¹ là bao nhiêu?","options":["x","1","0","x²"],"correct":0,"answer":"x","explanation":"🔑 Số mũ 1 giữ nguyên cơ số: <b>x¹ = x</b>.<br>✗ 1: đó là x⁰ (với x ≠ 0), không phải x¹.<br>✗ 0: không có công thức luỹ thừa nào cho kết quả này.<br>✗ x²: nhầm số mũ 1 thành số mũ 2."},{"id":"m1-27","ch":1,"topic":"Lũy thừa","q":"Công thức nào đúng khi nhân hai lũy thừa cùng cơ số?","options":["xᵐ · xⁿ = xᵐⁿ","xᵐ · xⁿ = xᵐ⁻ⁿ","xᵐ · xⁿ = xᵐ⁺ⁿ","xᵐ · xⁿ = (x·x)ᵐ⁺ⁿ"],"correct":2,"answer":"xᵐ · xⁿ = xᵐ⁺ⁿ","explanation":"🔑 Nhân lũy thừa cùng cơ số thì GIỮ cơ số, CỘNG số mũ: <b>xᵐ · xⁿ = xᵐ⁺ⁿ</b>.<br>✗ xᵐⁿ là NHÂN số mũ — đó là công thức (xᵐ)ⁿ.<br>✗ xᵐ⁻ⁿ là TRỪ số mũ — đó là công thức của phép CHIA.<br>✗ (x·x)ᵐ⁺ⁿ: cơ số không được nhân với nhau, phải giữ nguyên là x."},{"id":"m1-28","ch":1,"topic":"Lũy thừa","q":"Công thức nào đúng khi chia hai lũy thừa cùng cơ số (x ≠ 0)?","options":["xᵐ : xⁿ = xᵐ⁺ⁿ","xᵐ : xⁿ = xᵐⁿ","xᵐ : xⁿ = xⁿ⁻ᵐ","xᵐ : xⁿ = xᵐ⁻ⁿ"],"correct":3,"answer":"xᵐ : xⁿ = xᵐ⁻ⁿ","explanation":"🔑 Chia lũy thừa cùng cơ số thì GIỮ cơ số, TRỪ số mũ (mũ của số bị chia trừ mũ của số chia): <b>xᵐ : xⁿ = xᵐ⁻ⁿ</b>.<br>✗ xᵐ⁺ⁿ là cộng số mũ — đó là quy tắc của phép NHÂN.<br>✗ xᵐⁿ là nhân số mũ — đó là công thức (xᵐ)ⁿ.<br>✗ xⁿ⁻ᵐ: trừ ngược thứ tự, cho số mũ trái dấu."},{"id":"m1-29","ch":1,"topic":"Lũy thừa","q":"Công thức lũy thừa của một lũy thừa là công thức nào?","options":["(xᵐ)ⁿ = xᵐ⁺ⁿ","(xᵐ)ⁿ = xᵐⁿ","(xᵐ)ⁿ = xᵐ⁻ⁿ","(xᵐ)ⁿ = mⁿ · x"],"correct":1,"answer":"(xᵐ)ⁿ = xᵐⁿ","explanation":"🔑 Lũy thừa của lũy thừa thì giữ cơ số và NHÂN hai số mũ: <b>(xᵐ)ⁿ = xᵐⁿ</b>.<br>✗ xᵐ⁺ⁿ là cộng số mũ — đó là công thức xᵐ · xⁿ.<br>✗ xᵐ⁻ⁿ là trừ số mũ — đó là công thức xᵐ : xⁿ.<br>✗ mⁿ · x: số mũ không được kéo xuống làm cơ số."},{"id":"m1-30","ch":1,"topic":"Lũy thừa","q":"Công thức lũy thừa của một tích là công thức nào?","options":["(xy)ⁿ = xⁿyⁿ","(xy)ⁿ = xⁿ + yⁿ","(xy)ⁿ = (xy) · n","(xy)ⁿ = xⁿy"],"correct":0,"answer":"(xy)ⁿ = xⁿyⁿ","explanation":"🔑 Số mũ được chia đều cho TỪNG thừa số: <b>(xy)ⁿ = xⁿyⁿ</b>.<br>✗ xⁿ + yⁿ: tự ý đổi phép nhân thành phép cộng.<br>✗ (xy) · n: nhân với n chứ không nâng lên lũy thừa n.<br>✗ xⁿy: quên nâng lũy thừa cho thừa số y."},{"id":"m1-31","ch":1,"topic":"Lũy thừa","q":"Công thức lũy thừa của một thương (y ≠ 0) là công thức nào?","options":["(x/y)ⁿ = xⁿ/y","(x/y)ⁿ = x/yⁿ","(x/y)ⁿ = xⁿ/yⁿ","(x/y)ⁿ = xⁿ − yⁿ"],"correct":2,"answer":"(x/y)ⁿ = xⁿ/yⁿ","explanation":"🔑 Cả tử lẫn mẫu đều được nâng lên lũy thừa n: <b>(x/y)ⁿ = xⁿ/yⁿ</b> với y ≠ 0.<br>✗ xⁿ/y: quên nâng lũy thừa cho mẫu.<br>✗ x/yⁿ: quên nâng lũy thừa cho tử.<br>✗ xⁿ − yⁿ: phép chia không thể biến thành phép trừ."},{"id":"m1-32","ch":1,"topic":"Lũy thừa","q":"Công thức của lũy thừa với số mũ nguyên âm (x ≠ 0) là công thức nào?","options":["x⁻ⁿ = −xⁿ","x⁻ⁿ = 1/xⁿ","x⁻ⁿ = −1/xⁿ","x⁻ⁿ = xⁿ"],"correct":1,"answer":"x⁻ⁿ = 1/xⁿ","explanation":"🔑 Dấu trừ ở SỐ MŨ biến lũy thừa thành phân số nghịch đảo: <b>x⁻ⁿ = 1/xⁿ</b> (x ≠ 0). Nó KHÔNG làm kết quả âm.<br>✗ −xⁿ: nhầm dấu trừ ở số mũ thành dấu trừ của giá trị.<br>✗ −1/xⁿ: thừa một dấu âm, ví dụ 2⁻² = 1/4 chứ không phải −1/4.<br>✗ xⁿ: bỏ mất dấu trừ ở số mũ."},{"id":"m1-33","ch":1,"topic":"Lũy thừa","q":"Công thức x⁰ = 1 đúng với điều kiện nào?","options":["x > 0","x ∈ ℤ","Mọi giá trị của x","x ≠ 0"],"correct":3,"answer":"x ≠ 0","explanation":"🔑 x⁰ = 1 chỉ đúng khi <b>x ≠ 0</b>; riêng 0⁰ không xác định.<br>✗ x > 0: cơ số âm vẫn dùng được, ví dụ (−3)⁰ = 1.<br>✗ x ∈ ℤ: x có thể là số hữu tỉ bất kì khác 0, ví dụ (2/5)⁰ = 1.<br>✗ Mọi giá trị của x: bỏ sót trường hợp x = 0, mà 0⁰ thì không có nghĩa."},{"id":"m1-34","ch":1,"topic":"Lũy thừa","q":"Công thức (x/y)ⁿ = xⁿ/yⁿ cần thêm điều kiện nào?","options":["x ≠ 0","n > 0","y ≠ 0","x > y"],"correct":2,"answer":"y ≠ 0","explanation":"🔑 Mẫu của phân số luôn phải khác 0, nên điều kiện là <b>y ≠ 0</b>.<br>✗ x ≠ 0: tử được phép bằng 0, ví dụ (0/5)³ = 0.<br>✗ n > 0: công thức vẫn dùng được với số mũ âm (khi cơ số khác 0).<br>✗ x > y: so sánh lớn nhỏ không liên quan gì tới công thức này."},{"id":"m1-35","ch":1,"topic":"Lũy thừa","q":"Công thức x⁻ⁿ = 1/xⁿ đòi hỏi điều kiện nào?","options":["x ≠ 0","n ≠ 0","x > 0","n là số chẵn"],"correct":0,"answer":"x ≠ 0","explanation":"🔑 Vì xⁿ nằm dưới mẫu nên bắt buộc <b>x ≠ 0</b>.<br>✗ n ≠ 0: điều kiện nằm ở CƠ SỐ x, không phải ở số mũ n.<br>✗ x > 0: cơ số âm vẫn dùng được, ví dụ (−2)⁻² = 1/4.<br>✗ n là số chẵn: số mũ lẻ vẫn đúng, ví dụ 2⁻³ = 1/8."},{"id":"m1-36","ch":1,"topic":"Lũy thừa","q":"Công thức nào dưới đây SAI?","options":["xᵐ · xⁿ = xᵐ⁺ⁿ","xᵐ + xⁿ = xᵐ⁺ⁿ","(xᵐ)ⁿ = xᵐⁿ","xᵐ : xⁿ = xᵐ⁻ⁿ"],"correct":1,"answer":"xᵐ + xⁿ = xᵐ⁺ⁿ","explanation":"🔑 Không có công thức nào biến TỔNG hai lũy thừa thành một lũy thừa. Chỉ khi NHÂN cùng cơ số ta mới cộng số mũ. Ví dụ 2² + 2³ = 4 + 8 = 12, còn 2⁵ = 32 — khác hẳn nhau.<br>✗ xᵐ · xⁿ = xᵐ⁺ⁿ là công thức ĐÚNG: nhân thì cộng số mũ.<br>✗ (xᵐ)ⁿ = xᵐⁿ là công thức ĐÚNG: lũy thừa của lũy thừa thì nhân số mũ.<br>✗ xᵐ : xⁿ = xᵐ⁻ⁿ là công thức ĐÚNG: chia thì trừ số mũ."},{"id":"m1-37","ch":1,"topic":"Lũy thừa","q":"Viết 1/x⁵ dưới dạng một lũy thừa (x ≠ 0) thì được kết quả nào?","options":["x⁵","−x⁵","(1/x)⁻⁵","x⁻⁵"],"correct":3,"answer":"x⁻⁵","explanation":"🔑 Áp dụng x⁻ⁿ = 1/xⁿ theo chiều ngược lại: 1/x⁵ = <b>x⁻⁵</b>.<br>✗ x⁵: quên dấu trừ ở số mũ, đây lại chính là nghịch đảo của đáp án.<br>✗ −x⁵: đặt dấu trừ sai chỗ — dấu trừ phải nằm ở SỐ MŨ, không phải trước cơ số.<br>✗ (1/x)⁻⁵: rút gọn ra đúng bằng x⁵, tức là đã đảo dấu số mũ hai lần."},{"id":"m1-38","ch":1,"topic":"Lũy thừa","q":"Biểu thức (x · y)³ bằng bao nhiêu?","options":["3xy","x³ + y³","x³y³","xy³"],"correct":2,"answer":"x³y³","explanation":"🔑 Áp dụng (xy)ⁿ = xⁿyⁿ: (xy)³ = <b>x³y³</b>.<br>✗ 3xy: nhân với 3 chứ không nâng lên lũy thừa 3.<br>✗ x³ + y³: lũy thừa của một TÍCH không tách thành tổng.<br>✗ xy³: chỉ nâng lũy thừa cho y, bỏ quên x."},{"id":"m1-39","ch":1,"topic":"Lũy thừa","q":"Biểu thức (x⁴)³ bằng bao nhiêu?","options":["x¹²","x⁷","x⁶⁴","x⁴"],"correct":0,"answer":"x¹²","explanation":"🔑 Áp dụng (xᵐ)ⁿ = xᵐⁿ: lấy 4 · 3 = 12, vậy (x⁴)³ = <b>x¹²</b>.<br>✗ x⁷: cộng số mũ 4 + 3 — đó là quy tắc của phép NHÂN cùng cơ số.<br>✗ x⁶⁴: lấy 4³ = 64 rồi đặt làm số mũ, tức là nhầm vai trò của cơ số và số mũ.<br>✗ x⁴: bỏ quên số mũ 3 ở ngoài ngoặc."},{"id":"m1-40","ch":1,"topic":"Lũy thừa","q":"Biểu thức x⁵ : x² bằng bao nhiêu (x ≠ 0)?","options":["x⁷","x³","x¹⁰","x⁻³"],"correct":1,"answer":"x³","explanation":"🔑 Chia cùng cơ số thì trừ số mũ: x⁵ : x² = x⁵⁻² = <b>x³</b>.<br>✗ x⁷: cộng số mũ — đó là quy tắc của phép nhân.<br>✗ x¹⁰: nhân số mũ — đó là quy tắc (xᵐ)ⁿ.<br>✗ x⁻³: trừ ngược thứ tự (2 − 5); phải lấy mũ của số bị chia trừ mũ của số chia."},{"id":"m1-41","ch":1,"topic":"Lũy thừa","q":"Biểu thức x⁻³ · x⁵ bằng bao nhiêu (x ≠ 0)?","options":["x⁻⁸","x⁸","x⁻¹⁵","x²"],"correct":3,"answer":"x²","explanation":"🔑 Nhân cùng cơ số thì cộng số mũ, kể cả số mũ âm: (−3) + 5 = 2, vậy kết quả là <b>x²</b>.<br>✗ x⁻⁸: lấy −3 − 5 tức là trừ hai số mũ thay vì cộng.<br>✗ x⁸: bỏ mất dấu âm rồi cộng 3 + 5.<br>✗ x⁻¹⁵: nhân hai số mũ — đó là quy tắc của (xᵐ)ⁿ."},{"id":"m1-42","ch":1,"topic":"Lũy thừa","q":"Biểu thức (2/3)⁴ bằng bao nhiêu?","options":["2/3⁴","2⁴/3","2⁴/3⁴","(2·4)/(3·4)"],"correct":2,"answer":"2⁴/3⁴","explanation":"🔑 Áp dụng (x/y)ⁿ = xⁿ/yⁿ: (2/3)⁴ = <b>2⁴/3⁴</b> = 16/81.<br>✗ 2/3⁴: quên nâng lũy thừa cho tử.<br>✗ 2⁴/3: quên nâng lũy thừa cho mẫu.<br>✗ (2·4)/(3·4) = 8/12 = 2/3: đó là nhân cả tử và mẫu với 4, khác hẳn việc nâng lũy thừa."},{"id":"m1-43","ch":1,"topic":"Áp dụng lũy thừa","q":"Kết quả của 2³ · 2⁴ là gì?","options":["2⁷","2¹²","4⁷","2⁻¹"],"correct":0,"answer":"2⁷","explanation":"🔑 Cùng cơ số 2, nhân thì cộng số mũ: 2³ · 2⁴ = 2³⁺⁴ = <b>2⁷</b> = 128.<br>✗ 2¹²: nhân số mũ 3 · 4 — đó là quy tắc của (xᵐ)ⁿ.<br>✗ 4⁷: nhân luôn cả cơ số 2 · 2 = 4, trong khi cơ số phải GIỮ nguyên.<br>✗ 2⁻¹: trừ số mũ 3 − 4 — đó là quy tắc của phép chia."},{"id":"m1-44","ch":1,"topic":"Áp dụng lũy thừa","q":"Kết quả của 5⁶ : 5⁴ là gì?","options":["5¹⁰","5²","5²⁴","5⁻²"],"correct":1,"answer":"5²","explanation":"🔑 Chia cùng cơ số thì trừ số mũ: 5⁶ : 5⁴ = 5⁶⁻⁴ = <b>5²</b> = 25.<br>✗ 5¹⁰: cộng số mũ — đó là quy tắc của phép nhân.<br>✗ 5²⁴: nhân số mũ 6 · 4 — đó là quy tắc của (xᵐ)ⁿ.<br>✗ 5⁻²: trừ ngược thứ tự (4 − 6)."},{"id":"m1-45","ch":1,"topic":"Áp dụng lũy thừa","q":"Giá trị của (−1/2)³ là bao nhiêu?","options":["1/8","−3/8","−1/6","−1/8"],"correct":3,"answer":"−1/8","explanation":"🔑 Áp dụng (x/y)ⁿ = xⁿ/yⁿ: (−1/2)³ = (−1)³/2³ = <b>−1/8</b>. Số mũ LẺ giữ nguyên dấu âm.<br>✗ 1/8: quên dấu âm; chỉ khi số mũ CHẴN kết quả mới dương.<br>✗ −3/8: nhân tử với 3 thay vì tính lũy thừa bậc 3.<br>✗ −1/6: nhân mẫu với 3 (2 · 3 = 6) thay vì tính 2³ = 8."},{"id":"m1-46","ch":1,"topic":"Áp dụng lũy thừa","q":"Giá trị của 3⁻² là bao nhiêu?","options":["−9","−1/9","1/9","1/6"],"correct":2,"answer":"1/9","explanation":"🔑 Áp dụng x⁻ⁿ = 1/xⁿ: 3⁻² = 1/3² = <b>1/9</b>.<br>✗ −9: hiểu nhầm dấu trừ ở số mũ thành dấu trừ của giá trị.<br>✗ −1/9: thêm dấu âm thừa; số mũ âm không làm kết quả âm.<br>✗ 1/6: nhân 3 · 2 = 6 thay vì tính 3² = 9."},{"id":"m1-47","ch":1,"topic":"Áp dụng chuyển vế","q":"Tìm x biết x + 1/2 = 3/2. Giá trị của x là bao nhiêu?","options":["1","2","−1","3/4"],"correct":0,"answer":"1","explanation":"🔑 Chuyển 1/2 sang vế phải và đổi dấu: x = 3/2 − 1/2 = 2/2 = <b>1</b>.<br>✗ 2: lấy 3/2 + 1/2 — quên đổi dấu khi chuyển vế.<br>✗ −1: lấy 1/2 − 3/2, tức đảo ngược thứ tự hai số hạng.<br>✗ 3/4: nhân 3/2 · 1/2 — chuyển vế không dùng phép nhân."},{"id":"m1-48","ch":1,"topic":"Áp dụng chuyển vế","q":"Tìm x biết x − 1/3 = 1/3. Giá trị của x là bao nhiêu?","options":["0","2/3","−2/3","1/9"],"correct":1,"answer":"2/3","explanation":"🔑 A − B = C ⇒ A = C + B, nên x = 1/3 + 1/3 = <b>2/3</b>.<br>✗ 0: lấy 1/3 − 1/3 — quên đổi dấu khi chuyển vế.<br>✗ −2/3: cộng đúng nhưng gắn nhầm dấu âm vào kết quả.<br>✗ 1/9: nhân 1/3 · 1/3 thay vì cộng."},{"id":"m1-49","ch":1,"topic":"Áp dụng lũy thừa","q":"Biểu thức (3 · 4)² bằng biểu thức nào?","options":["3² + 4²","3 · 4²","(3 + 4)²","3² · 4²"],"correct":3,"answer":"3² · 4²","explanation":"🔑 Áp dụng (xy)ⁿ = xⁿyⁿ: (3 · 4)² = <b>3² · 4²</b> = 9 · 16 = 144, đúng bằng 12² = 144.<br>✗ 3² + 4² = 9 + 16 = 25: lũy thừa của một tích không tách thành tổng.<br>✗ 3 · 4² = 3 · 16 = 48: quên nâng lũy thừa cho thừa số 3.<br>✗ (3 + 4)² = 49: tự ý đổi dấu nhân trong ngoặc thành dấu cộng."},{"id":"m1-50","ch":1,"topic":"Áp dụng lũy thừa","q":"Rút gọn (x³)² : x⁴ (với x ≠ 0) ta được kết quả nào?","options":["x¹⁰","x¹","x²","x⁻²"],"correct":2,"answer":"x²","explanation":"🔑 Làm hai bước: (x³)² = x⁶ (vì 3 · 2 = 6), rồi x⁶ : x⁴ = x⁶⁻⁴ = <b>x²</b>.<br>✗ x¹⁰: cộng số mũ 6 + 4, tức là nhân thay vì chia.<br>✗ x¹: tính nhầm (x³)² = x⁵ (cộng số mũ) rồi mới chia cho x⁴.<br>✗ x⁻²: trừ ngược thứ tự (4 − 6)."},{"id":"m2-1","ch":2,"topic":"Giá trị tuyệt đối","q":"Công thức nào đúng khi a < 0?","options":["|a| = −a","|a| = a","|a| = 0","|a| < 0"],"correct":0,"answer":"|a| = −a","explanation":"🔑 Khi a âm, giá trị tuyệt đối là SỐ ĐỐI của a, nên |a| = −a (kết quả là một số dương).<br>✗ |a| = a chỉ đúng khi a ≥ 0.<br>✗ |a| = 0 chỉ đúng khi a = 0.<br>✗ |a| &lt; 0 sai vì giá trị tuyệt đối không bao giờ âm."},{"id":"m2-2","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a ≥ 0 thì |a| bằng biểu thức nào?","options":["|a| = −a","|a| = a²","|a| = a","|a| = √a"],"correct":2,"answer":"|a| = a","explanation":"🔑 Khi a không âm (a ≥ 0), giá trị tuyệt đối giữ nguyên chính số đó: |a| = a.<br>✗ |a| = −a chỉ dùng cho nhánh a &lt; 0.<br>✗ |a| = a² sai vì |3| = 3 chứ không phải 9.<br>✗ |a| = √a sai vì |4| = 4 chứ không phải 2."},{"id":"m2-3","ch":2,"topic":"Giá trị tuyệt đối","q":"Với mọi số thực a, giá trị tuyệt đối |a| luôn thỏa mãn điều kiện nào?","options":["|a| > 0","|a| ≥ 0","|a| ≤ 0","|a| = a"],"correct":1,"answer":"|a| ≥ 0","explanation":"🔑 |a| là khoảng cách từ điểm a đến gốc 0 trên trục số, mà khoảng cách không bao giờ âm, nên |a| ≥ 0 với mọi a.<br>✗ |a| > 0 sai ở trường hợp a = 0, vì |0| = 0.<br>✗ |a| ≤ 0 sai vì |5| = 5 > 0.<br>✗ |a| = a chỉ đúng khi a ≥ 0."},{"id":"m2-4","ch":2,"topic":"Giá trị tuyệt đối","q":"Nếu |a| = 0 thì a bằng bao nhiêu?","options":["a là số dương bất kì","a là số âm bất kì","Không tồn tại số a nào","a = 0"],"correct":3,"answer":"a = 0","explanation":"🔑 Chỉ duy nhất số 0 có khoảng cách tới gốc bằng 0, nên |a| = 0 ⇔ a = 0.<br>✗ Nếu a dương thì |a| = a > 0, khác 0.<br>✗ Nếu a âm thì |a| = −a > 0, cũng khác 0.<br>✗ Có tồn tại chứ, đó chính là số a = 0."},{"id":"m2-5","ch":2,"topic":"Giá trị tuyệt đối","q":"Khẳng định nào sau đây là SAI với mọi số thực a?","options":["|a| ≥ 0","|a| = |−a|","|a| < 0","|0| = 0"],"correct":2,"answer":"|a| < 0","explanation":"🔑 |a| là khoảng cách nên luôn ≥ 0; vì vậy |a| &lt; 0 là khẳng định SAI, không bao giờ xảy ra.<br>✗ |a| ≥ 0 là tính chất luôn đúng của giá trị tuyệt đối.<br>✗ |a| = |−a| đúng vì a và −a cách gốc 0 bằng nhau.<br>✗ |0| = 0 đúng theo định nghĩa vì 0 ≥ 0."},{"id":"m2-6","ch":2,"topic":"Giá trị tuyệt đối","q":"Quan hệ nào giữa |a| và |−a| là đúng với mọi số thực a?","options":["|a| = |−a|","|a| = −|−a|","|a| > |−a| khi a > 0","|a| < |−a| khi a < 0"],"correct":0,"answer":"|a| = |−a|","explanation":"🔑 a và −a là hai số đối, nằm cách gốc 0 một khoảng bằng nhau, nên |a| = |−a| với mọi a.<br>✗ |a| = −|−a| sai vì vế phải luôn ≤ 0 còn vế trái luôn ≥ 0.<br>✗ Khi a > 0 thì |a| = a và |−a| = a, hai bên bằng nhau chứ không lớn hơn.<br>✗ Khi a &lt; 0 thì |a| = −a và |−a| = −a, vẫn bằng nhau."},{"id":"m2-7","ch":2,"topic":"Giá trị tuyệt đối","q":"Nếu |x| = 5 thì x có thể nhận giá trị nào?","options":["Chỉ x = 5","Chỉ x = −5","x = 25","x = 5 hoặc x = −5"],"correct":3,"answer":"x = 5 hoặc x = −5","explanation":"🔑 Có đúng hai số cách gốc 0 một khoảng 5 đơn vị, nên |x| = 5 ⇔ x = 5 hoặc x = −5.<br>✗ Chỉ lấy x = 5 là bỏ sót nghiệm âm.<br>✗ Chỉ lấy x = −5 là bỏ sót nghiệm dương.<br>✗ x = 25 là nhầm sang phép bình phương, vì |25| = 25 ≠ 5."},{"id":"m2-8","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a < 0, kết quả |a| là số như thế nào?","options":["Là số âm","Là số dương","Bằng 0","Bằng chính a"],"correct":1,"answer":"Là số dương","explanation":"🔑 Khi a &lt; 0 thì |a| = −a, mà số đối của một số âm là số dương, nên |a| > 0.<br>✗ |a| không bao giờ là số âm vì |a| ≥ 0.<br>✗ |a| = 0 chỉ khi a = 0, trong khi ở đây a &lt; 0.<br>✗ |a| = a chỉ đúng với nhánh a ≥ 0."},{"id":"m2-9","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a > 0, biểu thức |−a| bằng gì?","options":["|−a| = −a","|−a| = 0","|−a| = a","|−a| = a²"],"correct":2,"answer":"|−a| = a","explanation":"🔑 Vì a > 0 nên −a &lt; 0; áp dụng |x| = −x khi x &lt; 0 ta được |−a| = −(−a) = a.<br>✗ |−a| = −a sai vì −a đang là số âm, mà giá trị tuyệt đối không thể âm.<br>✗ |−a| = 0 chỉ đúng khi a = 0.<br>✗ |−a| = a² sai, ví dụ a = 3 thì |−3| = 3 chứ không phải 9."},{"id":"m2-10","ch":2,"topic":"Giá trị tuyệt đối","q":"Trên trục số, |a| biểu diễn điều gì?","options":["Khoảng cách từ điểm a đến gốc 0","Vị trí của điểm a so với điểm 1","Số đối của a trong mọi trường hợp","Bình phương của a"],"correct":0,"answer":"Khoảng cách từ điểm a đến gốc 0","explanation":"🔑 Giá trị tuyệt đối |a| chính là khoảng cách từ điểm a đến gốc 0 trên trục số, vì thế nó luôn ≥ 0.<br>✗ |a| không so với điểm 1 mà luôn so với gốc 0.<br>✗ |a| = −a chỉ khi a &lt; 0, không phải mọi trường hợp.<br>✗ Bình phương là a², khác |a|: |−3| = 3 còn (−3)² = 9."},{"id":"m2-11","ch":2,"topic":"Giá trị tuyệt đối","q":"Có bao nhiêu số x thỏa mãn |x| = −3?","options":["Một số","Hai số","Vô số","Không có số nào"],"correct":3,"answer":"Không có số nào","explanation":"🔑 Vì |x| ≥ 0 với mọi x nên |x| không thể bằng −3; bài toán vô nghiệm.<br>✗ Không có nổi một số nào thỏa mãn.<br>✗ Hai số là đáp án của dạng |x| = 3, không phải |x| = −3.<br>✗ Vô số càng sai vì tập nghiệm rỗng."},{"id":"m2-12","ch":2,"topic":"Giá trị tuyệt đối","q":"Muốn tính |−2,5| ta áp dụng công thức nào?","options":["|a| = a vì a ≥ 0","|a| = −a vì a < 0","|a| = a² vì a < 0","|a| = √a vì a < 0"],"correct":1,"answer":"|a| = −a vì a < 0","explanation":"🔑 Số −2,5 là số âm nên dùng nhánh a &lt; 0 của định nghĩa: |a| = −a, do đó |−2,5| = 2,5.<br>✗ Nhánh |a| = a chỉ dùng khi a ≥ 0, mà −2,5 &lt; 0.<br>✗ Không có công thức |a| = a²; bình phương cho 6,25 chứ không phải 2,5.<br>✗ Không có công thức |a| = √a, hơn nữa √a còn đòi hỏi a ≥ 0."},{"id":"m2-13","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a < 0, biểu thức |a| + a bằng bao nhiêu?","options":["0","2a","−2a","a"],"correct":0,"answer":"0","explanation":"🔑 Khi a &lt; 0 thì |a| = −a, nên |a| + a = (−a) + a = 0.<br>✗ 2a là kết quả khi thay nhầm |a| = a.<br>✗ −2a là kết quả của |a| − a khi a &lt; 0, không phải của |a| + a.<br>✗ a là kết quả khi bỏ quên mất một hạng tử."},{"id":"m2-14","ch":2,"topic":"Giá trị tuyệt đối","q":"Giá trị nhỏ nhất của biểu thức |a| là bao nhiêu và đạt được khi nào?","options":["Nhỏ nhất bằng 1, khi a = 1","Không có giá trị nhỏ nhất","Nhỏ nhất bằng 0, khi a = 0","Nhỏ nhất bằng −1, khi a = −1"],"correct":2,"answer":"Nhỏ nhất bằng 0, khi a = 0","explanation":"🔑 Vì |a| ≥ 0 với mọi a và dấu bằng chỉ xảy ra khi a = 0, nên giá trị nhỏ nhất của |a| là 0, đạt được tại a = 0.<br>✗ |a| có thể nhỏ hơn 1, chẳng hạn |0,5| = 0,5.<br>✗ Có giá trị nhỏ nhất chứ, vì |a| luôn bị chặn dưới bởi 0.<br>✗ |a| không bao giờ âm nên không thể bằng −1."},{"id":"m2-15","ch":2,"topic":"Giá trị tuyệt đối","q":"Với a ≠ 0, khẳng định nào về |a| là đúng?","options":["|a| luôn bằng a","|a| luôn là số dương","|a| có thể bằng 0","|a| luôn cùng dấu với a"],"correct":1,"answer":"|a| luôn là số dương","explanation":"🔑 Với a ≠ 0, khoảng cách từ a đến gốc 0 khác 0, nên |a| > 0, tức |a| luôn là số dương.<br>✗ |a| = a chỉ đúng khi a > 0; nếu a &lt; 0 thì |a| = −a.<br>✗ |a| = 0 chỉ xảy ra khi a = 0, trái với giả thiết a ≠ 0.<br>✗ |a| luôn dương nên không thể cùng dấu với a khi a âm."},{"id":"m2-16","ch":2,"topic":"Giá trị tuyệt đối","q":"Đẳng thức |a| = a xảy ra khi nào?","options":["Khi a < 0","Với mọi số thực a","Chỉ khi a = 0","Khi a ≥ 0"],"correct":3,"answer":"Khi a ≥ 0","explanation":"🔑 Theo định nghĩa, |a| = a khi a ≥ 0, tức bao gồm cả a = 0 lẫn mọi số dương.<br>✗ Khi a &lt; 0 thì |a| = −a, khác a.<br>✗ Không đúng với mọi a: lấy a = −4 thì |−4| = 4 ≠ −4.<br>✗ Không chỉ riêng a = 0, vì mọi số dương cũng thỏa mãn."},{"id":"m2-17","ch":2,"topic":"Căn bậc hai số học","q":"Định nghĩa nào đúng cho x = √a (với a ≥ 0)?","options":["x ≤ 0 và x² = a","x ≥ 0 và x² = a","x ≥ 0 và x = a²","x là số bất kì có x² = a"],"correct":1,"answer":"x ≥ 0 và x² = a","explanation":"🔑 Căn bậc hai số học của a (a ≥ 0) là số KHÔNG ÂM có bình phương bằng a: x = √a ⇔ x ≥ 0 và x² = a.<br>✗ x ≤ 0 sai vì căn bậc hai số học không bao giờ âm.<br>✗ x = a² là nhầm phép căn với phép bình phương, vì √9 = 3 chứ không phải 81.<br>✗ Nếu lấy số bất kì thì cả 3 và −3 đều thỏa x² = 9, nhưng √9 chỉ bằng 3."},{"id":"m2-18","ch":2,"topic":"Căn bậc hai số học","q":"Công thức rút gọn nào đúng với mọi số thực a?","options":["√(a²) = |a|","√(a²) = a","√(a²) = −a","√(a²) = a²"],"correct":0,"answer":"√(a²) = |a|","explanation":"🔑 Vì căn bậc hai số học luôn không âm nên √(a²) = |a|, và công thức này đúng với MỌI số thực a.<br>✗ √(a²) = a chỉ đúng khi a ≥ 0; với a = −5 thì √25 = 5 ≠ −5.<br>✗ √(a²) = −a chỉ đúng khi a ≤ 0.<br>✗ √(a²) = a² sai, ví dụ a = 3 thì √9 = 3 chứ không phải 9."},{"id":"m2-19","ch":2,"topic":"Căn bậc hai số học","q":"Biểu thức √a có nghĩa (xác định được) khi nào?","options":["Khi a > 0","Với mọi số thực a","Khi a ≥ 0","Khi a ≤ 0"],"correct":2,"answer":"Khi a ≥ 0","explanation":"🔑 Căn bậc hai số học chỉ được định nghĩa cho số không âm, nên √a có nghĩa khi a ≥ 0.<br>✗ a > 0 là thiếu trường hợp a = 0, mà √0 = 0 vẫn có nghĩa.<br>✗ Không phải mọi a, vì √(−4) không tồn tại trong tập số thực.<br>✗ a ≤ 0 sai vì với a âm thì căn hoàn toàn không xác định."},{"id":"m2-20","ch":2,"topic":"Căn bậc hai số học","q":"Với a < 0, biểu thức √(a²) rút gọn thành gì?","options":["a","a²","0","−a"],"correct":3,"answer":"−a","explanation":"🔑 √(a²) = |a|, mà a &lt; 0 nên |a| = −a; vậy √(a²) = −a và đó là một số dương.<br>✗ √(a²) = a là lỗi kinh điển: quên dấu giá trị tuyệt đối khi a âm.<br>✗ a² là nhầm giữa lấy căn và bình phương.<br>✗ Kết quả bằng 0 chỉ xảy ra khi a = 0."},{"id":"m2-21","ch":2,"topic":"Căn bậc hai số học","q":"Giá trị của √(a²) khi a ≥ 0 là gì?","options":["a","−a","a²","√a"],"correct":0,"answer":"a","explanation":"🔑 √(a²) = |a|, mà a ≥ 0 nên |a| = a; vậy √(a²) = a.<br>✗ −a sẽ là số âm (khi a > 0), không thể là kết quả của căn bậc hai số học.<br>✗ a² là nhầm phép lấy căn với phép bình phương.<br>✗ √a khác √(a²): với a = 9 thì √(9²) = 9 còn √9 = 3."},{"id":"m2-22","ch":2,"topic":"Căn bậc hai số học","q":"Trong các khẳng định sau, khẳng định nào SAI?","options":["√(a²) = |a| với mọi a","√(a²) = a với mọi a","√0 = 0","√a ≥ 0 khi a ≥ 0"],"correct":1,"answer":"√(a²) = a với mọi a","explanation":"🔑 √(a²) = a chỉ đúng khi a ≥ 0, nên nói với mọi a là SAI: lấy a = −2 thì √4 = 2 ≠ −2.<br>✗ √(a²) = |a| là công thức đúng với mọi số thực.<br>✗ √0 = 0 đúng vì 0 ≥ 0 và 0² = 0.<br>✗ √a ≥ 0 đúng vì căn bậc hai số học không bao giờ âm."},{"id":"m2-23","ch":2,"topic":"Căn bậc hai số học","q":"Số nào sau đây KHÔNG thể là kết quả của một căn bậc hai số học?","options":["0","1,5","√2","−4"],"correct":3,"answer":"−4","explanation":"🔑 Căn bậc hai số học luôn ≥ 0, nên một số âm như −4 không thể là kết quả của √a.<br>✗ 0 thì được, vì √0 = 0.<br>✗ 1,5 thì được, vì √2,25 = 1,5.<br>✗ √2 thì được, vì đó là một số dương (căn bậc hai số học của 2)."},{"id":"m2-24","ch":2,"topic":"Căn bậc hai số học","q":"Từ x = √a (với a ≥ 0), ta suy ra được đẳng thức nào?","options":["x² = −a","a² = x","x² = a","x = a²"],"correct":2,"answer":"x² = a","explanation":"🔑 Theo định nghĩa x = √a ⇔ x ≥ 0 và x² = a, nên bình phương của căn trả lại đúng số dưới căn.<br>✗ x² = −a sai vì x² ≥ 0 còn −a ≤ 0 khi a ≥ 0.<br>✗ a² = x là đảo ngược vai trò: √9 = 3 nhưng 9² = 81 ≠ 3.<br>✗ x = a² cũng là nhầm phép căn thành phép bình phương."},{"id":"m2-25","ch":2,"topic":"Căn bậc hai số học","q":"Vì sao √(−9) không có nghĩa trong tập số thực?","options":["Vì −9 không phải số nguyên","Vì không có số thực nào bình phương bằng −9","Vì −9 là số vô tỉ","Vì √(−9) = −3"],"correct":1,"answer":"Vì không có số thực nào bình phương bằng −9","explanation":"🔑 Bình phương của mọi số thực đều ≥ 0 nên không có x nào để x² = −9; điều kiện a ≥ 0 của √a đã bị vi phạm.<br>✗ −9 vẫn là số nguyên, nên đó không phải lí do.<br>✗ −9 là số hữu tỉ chứ không phải số vô tỉ.<br>✗ √(−9) = −3 sai vì (−3)² = 9 chứ không phải −9, và căn số học thì không âm."},{"id":"m2-26","ch":2,"topic":"Căn bậc hai số học","q":"Cả 6 và −6 đều có bình phương bằng 36. Vậy √36 bằng bao nhiêu?","options":["6","−6","6 hoặc −6","18"],"correct":0,"answer":"6","explanation":"🔑 Căn bậc hai số học chỉ lấy giá trị KHÔNG ÂM, nên √36 = 6 dù (−6)² cũng bằng 36.<br>✗ −6 bị loại vì kết quả của căn bậc hai số học không âm.<br>✗ 6 hoặc −6 là câu trả lời cho bài x² = 36, không phải cho √36.<br>✗ 18 là lấy 36 chia 2, chẳng liên quan gì tới phép căn."},{"id":"m2-27","ch":2,"topic":"Căn bậc hai số học","q":"Nếu a ≥ 0 thì bình phương của căn, tức (√a)², cho kết quả nào?","options":["−a","√a","a","a²"],"correct":2,"answer":"a","explanation":"🔑 √a là số có bình phương bằng a, nên (√a)² = a với mọi a ≥ 0.<br>✗ −a là số âm khi a > 0, không thể bằng (√a)² vốn luôn ≥ 0.<br>✗ √a là quên mất phép bình phương ở ngoài.<br>✗ a² là bình phương thêm một lần nữa: (√9)² = 9 chứ không phải 81."},{"id":"m2-28","ch":2,"topic":"Căn bậc hai số học","q":"Rút gọn √((−7)²) ta được kết quả nào?","options":["−7","49","−49","7"],"correct":3,"answer":"7","explanation":"🔑 Dùng √(a²) = |a| với a = −7: √((−7)²) = |−7| = 7.<br>✗ −7 là lỗi áp dụng nhầm √(a²) = a cho một số âm.<br>✗ 49 là mới bình phương mà chưa lấy căn.<br>✗ −49 vừa sai dấu vừa chưa lấy căn."},{"id":"m2-29","ch":2,"topic":"Căn bậc hai số học","q":"Bạn An viết √(a²) = a với mọi số thực a. Bạn ấy sai ở chỗ nào?","options":["Sai vì công thức đúng phải là √(a²) = a²","Sai vì công thức đúng là √(a²) = |a|, chỉ khi a ≥ 0 mới có √(a²) = a","Sai vì √(a²) luôn bằng −a","Không sai, công thức đó luôn đúng"],"correct":1,"answer":"Sai vì công thức đúng là √(a²) = |a|, chỉ khi a ≥ 0 mới có √(a²) = a","explanation":"🔑 Công thức tổng quát là √(a²) = |a|; khi a ≥ 0 thì |a| = a nên mới viết được √(a²) = a, còn khi a &lt; 0 thì √(a²) = −a.<br>✗ √(a²) = a² sai, ví dụ a = 3 cho √9 = 3 chứ không phải 9.<br>✗ √(a²) = −a chỉ đúng khi a ≤ 0, không phải lúc nào cũng vậy.<br>✗ Bạn ấy có sai thật: với a = −5 thì √25 = 5 ≠ −5."},{"id":"m2-30","ch":2,"topic":"Căn bậc hai số học","q":"Điều kiện nào phải kèm theo để viết đúng định nghĩa x = √a?","options":["a ≥ 0 và x ≥ 0","a ≤ 0 và x ≥ 0","a ≥ 0 và x ≤ 0","a và x là số bất kì"],"correct":0,"answer":"a ≥ 0 và x ≥ 0","explanation":"🔑 Định nghĩa đầy đủ: với a ≥ 0, x = √a ⇔ x ≥ 0 và x² = a — cả số dưới căn lẫn kết quả đều không âm.<br>✗ a ≤ 0 sai vì căn của số âm không tồn tại trong ℝ.<br>✗ x ≤ 0 sai vì căn bậc hai số học không âm.<br>✗ Bỏ hết điều kiện thì √(−4) hay √9 = −3 cũng bị coi là đúng, điều đó vô lí."},{"id":"m2-31","ch":2,"topic":"Số thực và số thập phân","q":"Số thập phân hữu hạn và số thập phân vô hạn tuần hoàn thuộc tập hợp số nào?","options":["Tập số vô tỉ 𝕀","Tập số nguyên ℤ","Không thuộc tập hợp nào","Tập số hữu tỉ ℚ"],"correct":3,"answer":"Tập số hữu tỉ ℚ","explanation":"🔑 Mọi số thập phân hữu hạn hoặc vô hạn tuần hoàn đều viết được thành phân số, nên chúng là số hữu tỉ, thuộc ℚ.<br>✗ 𝕀 chỉ chứa số thập phân vô hạn KHÔNG tuần hoàn.<br>✗ ℤ chỉ gồm các số nguyên, mà 0,5 không phải số nguyên.<br>✗ Chúng chắc chắn thuộc ℚ chứ không phải không thuộc tập nào."},{"id":"m2-32","ch":2,"topic":"Số thực và số thập phân","q":"Số thập phân vô hạn không tuần hoàn được gọi là gì?","options":["Số hữu tỉ","Số nguyên","Số vô tỉ","Số tự nhiên"],"correct":2,"answer":"Số vô tỉ","explanation":"🔑 Số thập phân vô hạn KHÔNG tuần hoàn thì không viết được thành phân số, nên gọi là số vô tỉ, kí hiệu 𝕀.<br>✗ Số hữu tỉ ứng với thập phân hữu hạn hoặc vô hạn TUẦN HOÀN.<br>✗ Số nguyên không hề có phần thập phân kéo dài vô hạn.<br>✗ Số tự nhiên là 0; 1; 2; ... nên cũng không phải."},{"id":"m2-33","ch":2,"topic":"Số thực và số thập phân","q":"Công thức nào mô tả đúng tập số thực ℝ?","options":["ℝ = ℚ ∪ 𝕀","ℝ = ℚ ∩ 𝕀","ℝ = ℚ ∪ ℤ","ℝ = 𝕀 ∩ ℤ"],"correct":0,"answer":"ℝ = ℚ ∪ 𝕀","explanation":"🔑 Tập số thực là HỢP của tập số hữu tỉ và tập số vô tỉ: ℝ = ℚ ∪ 𝕀.<br>✗ ℚ ∩ 𝕀 là phép giao, mà hai tập này không có phần tử chung nên giao bằng tập rỗng.<br>✗ ℚ ∪ ℤ = ℚ vì ℤ vốn đã nằm trong ℚ, cách viết này thiếu hẳn số vô tỉ.<br>✗ 𝕀 ∩ ℤ cũng rỗng vì không số nguyên nào là số vô tỉ."},{"id":"m2-34","ch":2,"topic":"Số thực và số thập phân","q":"Một số vừa là số hữu tỉ vừa là số vô tỉ. Khẳng định này đúng hay sai?","options":["Đúng, vì cả hai loại đều thuộc ℝ","Sai, vì ℚ và 𝕀 không có phần tử chung","Đúng, với các số thập phân vô hạn","Sai, vì số vô tỉ không thuộc ℝ"],"correct":1,"answer":"Sai, vì ℚ và 𝕀 không có phần tử chung","explanation":"🔑 ℚ và 𝕀 là hai tập rời nhau: một số thập phân hoặc tuần hoàn (hữu tỉ) hoặc không tuần hoàn (vô tỉ), không thể vừa nọ vừa kia.<br>✗ Cùng nằm trong ℝ không có nghĩa là trùng nhau, vì ℝ = ℚ ∪ 𝕀 là hợp của hai phần rời.<br>✗ Thập phân vô hạn vẫn phải chọn một trong hai: tuần hoàn hay không tuần hoàn.<br>✗ Số vô tỉ vẫn là số thực, nên lí do đưa ra ở đây sai."},{"id":"m2-35","ch":2,"topic":"Số thực và số thập phân","q":"Số 0,333... (chữ số 3 lặp lại mãi) thuộc những tập hợp nào?","options":["Chỉ thuộc 𝕀","Không thuộc ℝ","Thuộc ℚ và thuộc ℝ","Chỉ thuộc ℤ"],"correct":2,"answer":"Thuộc ℚ và thuộc ℝ","explanation":"🔑 0,333... là thập phân vô hạn TUẦN HOÀN (chu kì 3) nên là số hữu tỉ, bằng 1/3; mà mọi số hữu tỉ đều nằm trong ℝ = ℚ ∪ 𝕀.<br>✗ Nó không thuộc 𝕀 vì có nhóm chữ số lặp lại.<br>✗ Đã là số hữu tỉ thì chắc chắn là số thực, không thể ngoài ℝ.<br>✗ 1/3 không phải số nguyên nên không thuộc ℤ."},{"id":"m2-36","ch":2,"topic":"Số thực và số thập phân","q":"Số π = 3,141592... là loại số nào?","options":["Số hữu tỉ vì viết được thành phân số","Số thập phân hữu hạn","Số thập phân vô hạn tuần hoàn","Số vô tỉ vì thập phân vô hạn không tuần hoàn"],"correct":3,"answer":"Số vô tỉ vì thập phân vô hạn không tuần hoàn","explanation":"🔑 Phần thập phân của π kéo dài vô hạn mà không lặp theo chu kì nào, nên π là số vô tỉ, π ∈ 𝕀.<br>✗ π không viết được thành phân số nên không phải số hữu tỉ.<br>✗ π không dừng lại sau hữu hạn chữ số.<br>✗ π không có chu kì lặp nên không phải vô hạn tuần hoàn."},{"id":"m2-37","ch":2,"topic":"Số thực và số thập phân","q":"Khẳng định nào sau đây là đúng?","options":["Mọi số thực đều là số hữu tỉ","Mọi số hữu tỉ đều là số thực","Mọi số vô tỉ đều là số hữu tỉ","Mọi số thực đều là số vô tỉ"],"correct":1,"answer":"Mọi số hữu tỉ đều là số thực","explanation":"🔑 Vì ℝ = ℚ ∪ 𝕀 nên ℚ nằm trọn trong ℝ: mọi số hữu tỉ đều là số thực.<br>✗ Chiều ngược lại thì sai, vì √2 là số thực nhưng không hữu tỉ.<br>✗ Số vô tỉ và số hữu tỉ là hai loại rời nhau, không loại nào nằm trong loại nào.<br>✗ Số thực có thể là hữu tỉ, ví dụ 0,5, nên không phải số thực nào cũng vô tỉ."},{"id":"m2-38","ch":2,"topic":"Số thực và số thập phân","q":"Số 2,5 là số thập phân loại nào?","options":["Thập phân hữu hạn, là số hữu tỉ","Thập phân vô hạn tuần hoàn, là số hữu tỉ","Thập phân vô hạn không tuần hoàn, là số vô tỉ","Không phải số thập phân"],"correct":0,"answer":"Thập phân hữu hạn, là số hữu tỉ","explanation":"🔑 2,5 dừng lại sau một chữ số thập phân nên là thập phân HỮU HẠN, viết được thành 5/2, do đó là số hữu tỉ.<br>✗ Nó không kéo dài vô hạn nên không thể là vô hạn tuần hoàn.<br>✗ Nó cũng không phải số vô tỉ vì đã viết được dưới dạng phân số.<br>✗ 2,5 rõ ràng là một số thập phân."},{"id":"m2-39","ch":2,"topic":"Số thực và số thập phân","q":"Số 1,2333... có nhóm chữ số 3 lặp lại mãi. Cách gọi đúng cho số này là gì?","options":["Số thập phân hữu hạn","Số thập phân vô hạn không tuần hoàn","Số vô tỉ","Số thập phân vô hạn tuần hoàn"],"correct":3,"answer":"Số thập phân vô hạn tuần hoàn","explanation":"🔑 Phần thập phân kéo dài mãi nhưng chữ số 3 lặp đi lặp lại, nên đây là thập phân vô hạn TUẦN HOÀN, viết gọn 1,2(3).<br>✗ Nó không dừng lại nên không phải hữu hạn.<br>✗ Có chu kì lặp rõ ràng nên không phải không tuần hoàn.<br>✗ Đã tuần hoàn thì là số hữu tỉ, không phải số vô tỉ."},{"id":"m2-40","ch":2,"topic":"Số thực và số thập phân","q":"Vì sao √2 = 1,414213... là số vô tỉ?","options":["Vì nó lớn hơn 1","Vì nó có dấu căn","Vì phần thập phân vô hạn và không tuần hoàn","Vì nó là số âm"],"correct":2,"answer":"Vì phần thập phân vô hạn và không tuần hoàn","explanation":"🔑 Một số là vô tỉ khi biểu diễn thập phân của nó vô hạn và KHÔNG tuần hoàn, đúng như √2 = 1,414213...<br>✗ Lớn hơn 1 không liên quan, vì 1,5 cũng lớn hơn 1 mà vẫn là số hữu tỉ.<br>✗ Có dấu căn chưa đủ, vì √4 = 2 vẫn là số hữu tỉ.<br>✗ √2 là số dương chứ không phải số âm."},{"id":"m2-41","ch":2,"topic":"Số thực và số thập phân","q":"Tập hợp ℚ ∩ 𝕀 (giao của tập số hữu tỉ và tập số vô tỉ) là tập nào?","options":["Tập rỗng","Tập ℝ","Tập ℤ","Tập các số thập phân vô hạn"],"correct":0,"answer":"Tập rỗng","explanation":"🔑 Không có số nào vừa hữu tỉ vừa vô tỉ nên ℚ ∩ 𝕀 là tập rỗng; phải dùng phép HỢP ℚ ∪ 𝕀 mới ra ℝ.<br>✗ ℝ là kết quả của phép hợp chứ không phải phép giao.<br>✗ ℤ nằm trong ℚ nhưng không có phần nào thuộc 𝕀.<br>✗ Thập phân vô hạn tuần hoàn thuộc ℚ, không tuần hoàn thuộc 𝕀, vẫn chẳng có phần chung."},{"id":"m2-42","ch":2,"topic":"Số thực và số thập phân","q":"Số nào sau đây là số vô tỉ?","options":["0,25","√3","√9","1,5(2)"],"correct":1,"answer":"√3","explanation":"🔑 √3 = 1,7320508... có phần thập phân vô hạn và không tuần hoàn nên là số vô tỉ.<br>✗ 0,25 là thập phân hữu hạn, bằng 1/4, nên là số hữu tỉ.<br>✗ √9 = 3 là số nguyên, thuộc ℚ.<br>✗ 1,5(2) là thập phân vô hạn tuần hoàn nên vẫn là số hữu tỉ."},{"id":"m2-43","ch":2,"topic":"Áp dụng tính toán","q":"Giá trị của √25 là bao nhiêu?","options":["12,5","±5","5","625"],"correct":2,"answer":"5","explanation":"🔑 √25 = 5 vì 5 ≥ 0 và 5² = 25, đúng định nghĩa x = √a ⇔ x ≥ 0 và x² = a.<br>✗ 12,5 là lấy 25 chia 2, không phải phép căn.<br>✗ ±5 là nghiệm của x² = 25; căn bậc hai số học chỉ lấy giá trị không âm.<br>✗ 625 là 25², tức làm ngược phép toán."},{"id":"m2-44","ch":2,"topic":"Áp dụng tính toán","q":"Thay a = −7 vào định nghĩa giá trị tuyệt đối, ta được kết quả nào?","options":["−7","0","49","7"],"correct":3,"answer":"7","explanation":"🔑 Vì −7 &lt; 0 nên dùng công thức |a| = −a: |−7| = −(−7) = 7.<br>✗ −7 là giữ nguyên dấu âm, sai vì |a| ≥ 0.<br>✗ 0 chỉ đúng khi số trong dấu là 0.<br>✗ 49 là bình phương của 7, không phải giá trị tuyệt đối."},{"id":"m2-45","ch":2,"topic":"Áp dụng tính toán","q":"Tính |−3| + √16.","options":["1","7","−7","19"],"correct":1,"answer":"7","explanation":"🔑 |−3| = 3 (vì −3 &lt; 0 nên lấy số đối) và √16 = 4 (vì 4 ≥ 0 và 4² = 16), nên tổng là 3 + 4 = 7.<br>✗ 1 là kết quả khi lấy nhầm |−3| = −3 rồi cộng 4.<br>✗ −7 là giữ dấu âm cho cả hai, trong khi |a| ≥ 0 và √a ≥ 0.<br>✗ 19 là cộng 3 với 16, tức quên lấy căn."},{"id":"m2-46","ch":2,"topic":"Áp dụng tính toán","q":"Tính |5 − 8|.","options":["3","−3","13","40"],"correct":0,"answer":"3","explanation":"🔑 Tính trong dấu trước: 5 − 8 = −3; vì −3 &lt; 0 nên |−3| = −(−3) = 3.<br>✗ −3 là quên bước lấy giá trị tuyệt đối, mà |a| ≥ 0.<br>✗ 13 là cộng 5 với 8 thay vì trừ.<br>✗ 40 là nhân 5 với 8, sai hẳn phép tính."},{"id":"m2-47","ch":2,"topic":"Áp dụng tính toán","q":"Tính √0,25.","options":["0,125","0,0625","0,5","2,5"],"correct":2,"answer":"0,5","explanation":"🔑 Vì 0,5 ≥ 0 và 0,5² = 0,25 nên √0,25 = 0,5.<br>✗ 0,125 là lấy 0,25 chia 2, không phải phép căn.<br>✗ 0,0625 là 0,25², tức làm ngược phép toán.<br>✗ 2,5 là đặt sai dấu phẩy, vì 2,5² = 6,25 chứ không phải 0,25."},{"id":"m2-48","ch":2,"topic":"Áp dụng tính toán","q":"Tính |0| + |−1|.","options":["−1","0","2","1"],"correct":3,"answer":"1","explanation":"🔑 |0| = 0 theo định nghĩa và |−1| = −(−1) = 1, nên tổng bằng 0 + 1 = 1.<br>✗ −1 là quên đổi dấu khi lấy giá trị tuyệt đối của số âm.<br>✗ 0 là bỏ sót hạng tử |−1|.<br>✗ 2 là tính nhầm |0| thành 1."},{"id":"m2-49","ch":2,"topic":"Áp dụng tính toán","q":"Tính √81 − |−4|.","options":["13","5","−5","77"],"correct":1,"answer":"5","explanation":"🔑 √81 = 9 (vì 9 ≥ 0 và 9² = 81) và |−4| = 4, nên 9 − 4 = 5.<br>✗ 13 là cộng thay vì trừ.<br>✗ −5 là lấy nhầm |−4| = −4 rồi đảo ngược phép tính.<br>✗ 77 là 81 − 4, tức quên lấy căn của 81."},{"id":"m2-50","ch":2,"topic":"Áp dụng tính toán","q":"Nếu x² = 49 và x < 0 thì x bằng bao nhiêu?","options":["x = −7","x = 7","x = √49","x = −49"],"correct":0,"answer":"x = −7","explanation":"🔑 Có hai số bình phương bằng 49 là 7 và −7; điều kiện x &lt; 0 chọn ra x = −7.<br>✗ x = 7 vi phạm điều kiện x &lt; 0.<br>✗ x = √49 = 7 cũng là số dương nên bị loại, vì căn bậc hai số học luôn ≥ 0.<br>✗ x = −49 sai vì (−49)² = 2401 ≠ 49."},{"id":"m3-1","ch":3,"topic":"Hai góc kề bù","q":"Hai góc kề bù có tổng số đo bằng bao nhiêu?","options":["∠xOz + ∠zOy = 180°","∠xOz + ∠zOy = 90°","∠xOz + ∠zOy = 360°","∠xOz = ∠zOy"],"correct":0,"answer":"∠xOz + ∠zOy = 180°","explanation":"🔑 Hai góc kề bù kề nhau và hai cạnh ngoài tạo thành một góc bẹt, nên <b>∠xOz + ∠zOy = 180°</b>.<br>✗ 90° là tổng của hai góc <b>phụ nhau</b>, không phải kề bù.<br>✗ 360° là tổng các góc quanh một điểm, không phải tổng hai góc kề bù.<br>✗ ∠xOz = ∠zOy chỉ xảy ra khi mỗi góc bằng 90°, đó không phải tính chất chung."},{"id":"m3-2","ch":3,"topic":"Hai góc kề bù","q":"Cho ∠xOz và ∠zOy là hai góc kề bù, biết ∠xOz = 130°. Số đo ∠zOy bằng bao nhiêu?","options":["∠zOy = 130°","∠zOy = 50°","∠zOy = 230°","∠zOy = 65°"],"correct":1,"answer":"∠zOy = 50°","explanation":"🔑 Kề bù nên ∠zOy = 180° − ∠xOz = 180° − 130° = <b>50°</b>.<br>✗ 130° là lấy bằng chính góc kia — đó là tính chất hai góc <b>đối đỉnh</b>, không phải kề bù.<br>✗ 230° là lấy 360° − 130°, dùng nhầm tổng các góc quanh một điểm.<br>✗ 65° là một nửa của 130° — đó là công thức tia phân giác."},{"id":"m3-3","ch":3,"topic":"Hai góc đối đỉnh","q":"Tính chất của hai góc đối đỉnh được viết như thế nào?","options":["∠O₁ + ∠O₂ = 180°","∠O₁ + ∠O₂ = 90°","∠O₁ = ∠O₂","∠O₁ = ½∠O₂"],"correct":2,"answer":"∠O₁ = ∠O₂","explanation":"🔑 <b>Hai góc đối đỉnh thì bằng nhau</b>: ∠O₁ = ∠O₂.<br>✗ ∠O₁ + ∠O₂ = 180° là tính chất của hai góc <b>kề bù</b>, không phải đối đỉnh.<br>✗ Tổng 90° là quan hệ của hai góc phụ nhau.<br>✗ ½ là công thức <b>tia phân giác</b>, không liên quan gì đến hai góc đối đỉnh."},{"id":"m3-4","ch":3,"topic":"Hai góc đối đỉnh","q":"Hai đường thẳng cắt nhau tại O tạo thành bốn góc, trong đó có một góc bằng 40°. Góc đối đỉnh với góc 40° bằng bao nhiêu?","options":["140°","180°","20°","40°"],"correct":3,"answer":"40°","explanation":"🔑 Hai góc đối đỉnh thì bằng nhau, nên góc đối đỉnh với góc 40° cũng bằng <b>40°</b>.<br>✗ 140° = 180° − 40° là số đo góc <b>kề bù</b> với nó, không phải góc đối đỉnh.<br>✗ 180° là số đo góc bẹt, không thể là một trong bốn góc đó.<br>✗ 20° là một nửa của 40° — kết quả khi nhầm sang tia phân giác."},{"id":"m3-5","ch":3,"topic":"Hai góc kề bù","q":"Hai đường thẳng cắt nhau tại O, một trong bốn góc tạo thành bằng 40°. Số đo của góc kề bù với góc đó là bao nhiêu?","options":["140°","40°","50°","320°"],"correct":0,"answer":"140°","explanation":"🔑 Hai góc kề bù có tổng 180°, nên góc cần tìm bằng 180° − 40° = <b>140°</b>.<br>✗ 40° là số đo góc <b>đối đỉnh</b> (bằng chính nó), không phải góc kề bù.<br>✗ 50° = 90° − 40° là quan hệ hai góc <b>phụ nhau</b>, không phải bù nhau.<br>✗ 320° = 360° − 40°, dùng nhầm tổng các góc quanh một điểm."},{"id":"m3-6","ch":3,"topic":"Hai góc kề bù","q":"Hai góc kề bù có số đo bằng nhau thì mỗi góc bằng bao nhiêu?","options":["45°","90°","60°","180°"],"correct":1,"answer":"90°","explanation":"🔑 Tổng hai góc kề bù bằng 180°; hai góc bằng nhau nên mỗi góc bằng 180° : 2 = <b>90°</b>.<br>✗ 45° là 90° : 2, tức đã nhầm tổng hai góc là 90° thay vì 180°.<br>✗ 60° là 180° : 3, chia cho ba trong khi chỉ có hai góc.<br>✗ 180° là tổng của cả hai góc, không phải số đo mỗi góc."},{"id":"m3-7","ch":3,"topic":"Góc tạo bởi hai đường thẳng cắt nhau","q":"Tổng số đo bốn góc tạo bởi hai đường thẳng cắt nhau tại một điểm bằng bao nhiêu?","options":["180°","90°","360°","720°"],"correct":2,"answer":"360°","explanation":"🔑 Bốn góc đó phủ kín xung quanh điểm cắt nên tổng bằng <b>360°</b> (ví dụ 40° + 140° + 40° + 140° = 360°).<br>✗ 180° chỉ là tổng của <b>hai</b> góc kề bù, tức một nửa số góc.<br>✗ 90° là tổng của hai góc phụ nhau, không liên quan ở đây.<br>✗ 720° là kết quả khi nhân đôi 360° do đếm mỗi góc hai lần."},{"id":"m3-8","ch":3,"topic":"Hai góc kề bù","q":"Điều kiện để hai góc ∠xOz và ∠zOy là hai góc kề bù là gì?","options":["Hai góc bằng nhau và có chung đỉnh O","Hai góc có chung đỉnh O và tổng bằng 90°","Hai góc đối đỉnh nhau qua điểm O","Hai góc kề nhau (chung cạnh Oz) và hai tia Ox, Oy đối nhau"],"correct":3,"answer":"Hai góc kề nhau (chung cạnh Oz) và hai tia Ox, Oy đối nhau","explanation":"🔑 Hai góc kề bù là hai góc <b>kề nhau</b> (chung cạnh Oz) và hai cạnh còn lại Ox, Oy là <b>hai tia đối nhau</b>; khi đó ∠xOz + ∠zOy = 180°.<br>✗ Bằng nhau và chung đỉnh là chưa đủ: hai góc kề bù chỉ bằng nhau khi mỗi góc bằng 90°.<br>✗ Tổng bằng 90° là hai góc <b>phụ nhau</b>, không phải kề bù.<br>✗ Hai góc đối đỉnh thì bằng nhau và không kề nhau — đó là quan hệ hoàn toàn khác."},{"id":"m3-9","ch":3,"topic":"Hai góc kề bù","q":"Một góc có số đo 90°. Góc kề bù với nó có số đo bằng bao nhiêu?","options":["90°","0°","180°","270°"],"correct":0,"answer":"90°","explanation":"🔑 180° − 90° = <b>90°</b>, nên góc kề bù với một góc vuông cũng là góc vuông.<br>✗ 0° là kết quả của 90° − 90°, tức nhầm tổng hai góc kề bù là 90°.<br>✗ 180° là tổng của hai góc chứ không phải số đo góc còn lại.<br>✗ 270° = 360° − 90°, dùng nhầm tổng các góc quanh một điểm."},{"id":"m3-10","ch":3,"topic":"Hai góc đối đỉnh","q":"Khẳng định nào sau đây đúng về hai góc đối đỉnh?","options":["Hai góc bằng nhau thì luôn đối đỉnh với nhau","Hai góc đối đỉnh thì bằng nhau, nhưng hai góc bằng nhau chưa chắc đối đỉnh","Hai góc đối đỉnh thì bù nhau","Hai góc đối đỉnh thì có chung một cạnh"],"correct":1,"answer":"Hai góc đối đỉnh thì bằng nhau, nhưng hai góc bằng nhau chưa chắc đối đỉnh","explanation":"🔑 Hai góc đối đỉnh luôn bằng nhau, nhưng chiều ngược lại không đúng: hai góc bằng nhau có thể nằm ở bất kỳ đâu.<br>✗ “Bằng nhau thì đối đỉnh” là <b>đảo ngược mệnh đề</b> — một lỗi rất hay gặp và hoàn toàn sai.<br>✗ Bù nhau (tổng 180°) là tính chất của hai góc <b>kề bù</b>, không phải đối đỉnh.<br>✗ Hai góc đối đỉnh không chung cạnh: cạnh của góc này là tia đối cạnh của góc kia."},{"id":"m3-11","ch":3,"topic":"Tia phân giác","q":"Nếu Oz là tia phân giác của ∠xOy thì công thức nào sau đây đúng?","options":["∠xOz + ∠zOy = 180°","∠xOz = ∠zOy = ½∠xOy","∠xOz = 2∠xOy","∠xOz = ∠xOy"],"correct":1,"answer":"∠xOz = ∠zOy = ½∠xOy","explanation":"🔑 Tia phân giác chia góc thành hai góc bằng nhau: <b>∠xOz = ∠zOy = ½∠xOy</b>.<br>✗ Tổng bằng 180° là công thức hai góc <b>kề bù</b>, không phải phân giác.<br>✗ ∠xOz = 2∠xOy là ngược chiều: góc con phải NHỎ hơn, bằng một nửa góc lớn.<br>✗ ∠xOz = ∠xOy nghĩa là tia Oz trùng tia Oy, khi đó không có tia phân giác nào cả."},{"id":"m3-12","ch":3,"topic":"Tia phân giác","q":"Cho ∠xOy = 80° và Oz là tia phân giác của ∠xOy. Số đo ∠xOz bằng bao nhiêu?","options":["160°","100°","40°","80°"],"correct":2,"answer":"40°","explanation":"🔑 ∠xOz = ½ · ∠xOy = ½ · 80° = <b>40°</b>.<br>✗ 160° là 80° × 2 — nhân đôi thay vì chia đôi.<br>✗ 100° = 180° − 80°, dùng nhầm công thức hai góc kề bù.<br>✗ 80° là giữ nguyên góc lớn, quên mất bước chia đôi."},{"id":"m3-13","ch":3,"topic":"Tia phân giác","q":"Tia Oz là tia phân giác của ∠xOy và ∠xOz = 35°. Số đo ∠xOy bằng bao nhiêu?","options":["35°","145°","17,5°","70°"],"correct":3,"answer":"70°","explanation":"🔑 Bài này đi ngược: ∠xOy = 2 · ∠xOz = 2 · 35° = <b>70°</b>.<br>✗ 35° mới chỉ là số đo nửa góc, chưa phải cả góc.<br>✗ 145° = 180° − 35°, dùng nhầm công thức hai góc kề bù.<br>✗ 17,5° là chia đôi thêm một lần nữa — làm ngược chiều phép tính."},{"id":"m3-14","ch":3,"topic":"Tia phân giác","q":"Tia phân giác của một góc bẹt (180°) chia góc đó thành hai góc, mỗi góc bằng bao nhiêu?","options":["90°","45°","180°","360°"],"correct":0,"answer":"90°","explanation":"🔑 ½ · 180° = <b>90°</b>, nên tia phân giác của góc bẹt vuông góc với hai cạnh của góc đó.<br>✗ 45° là một nửa của 90°, tức đã chia đôi hai lần.<br>✗ 180° là số đo góc ban đầu, quên bước chia đôi.<br>✗ 360° là nhân đôi thay vì chia đôi."},{"id":"m3-15","ch":3,"topic":"Tia phân giác","q":"Điều kiện nào sau đây khẳng định tia Oz là tia phân giác của ∠xOy?","options":["Oz nằm giữa hai tia Ox, Oy và ∠xOz = ∠zOy","Oz vuông góc với tia Ox","∠xOz + ∠zOy = 180°","Oz là tia đối của tia Ox"],"correct":0,"answer":"Oz nằm giữa hai tia Ox, Oy và ∠xOz = ∠zOy","explanation":"🔑 Tia phân giác phải <b>nằm giữa</b> hai cạnh của góc và <b>chia góc thành hai góc bằng nhau</b>.<br>✗ Vuông góc với Ox không đảm bảo chia đôi ∠xOy, trừ trường hợp riêng ∠xOy = 180°.<br>✗ Tổng bằng 180° chỉ là quan hệ kề bù, không nói gì về việc hai góc có bằng nhau hay không.<br>✗ Tia đối của Ox nằm ngoài góc ∠xOy nên không thể là tia phân giác."},{"id":"m3-16","ch":3,"topic":"Tia phân giác","q":"Cho ∠xOy = 120° và Oz là tia phân giác của ∠xOy. Số đo ∠zOy bằng bao nhiêu?","options":["120°","60°","30°","240°"],"correct":1,"answer":"60°","explanation":"🔑 ∠zOy = ½ · 120° = <b>60°</b>.<br>✗ 120° là giữ nguyên góc lớn, quên chia đôi.<br>✗ 30° là chia cho 4 (chia đôi hai lần) chứ không phải chia đôi một lần.<br>✗ 240° là nhân đôi thay vì chia đôi."},{"id":"m3-17","ch":3,"topic":"Tia phân giác và góc kề bù","q":"Hai góc ∠xOz và ∠zOy kề bù, tia Ot là tia phân giác của ∠xOz. Biết ∠xOz = 100°, số đo ∠tOz bằng bao nhiêu?","options":["80°","100°","50°","40°"],"correct":2,"answer":"50°","explanation":"🔑 Ot là tia phân giác của ∠xOz nên ∠tOz = ½ · ∠xOz = ½ · 100° = <b>50°</b>.<br>✗ 80° chính là ∠zOy = 180° − 100°, tức đã tính nhầm sang góc kề bù.<br>✗ 100° là giữ nguyên ∠xOz, quên chia đôi.<br>✗ 40° là một nửa của 80° — chia đôi nhầm góc kề bù thay vì chia đôi ∠xOz."},{"id":"m3-18","ch":3,"topic":"Tia phân giác","q":"Một góc được tia phân giác chia thành hai góc, mỗi góc bằng 25°. Góc ban đầu bằng bao nhiêu?","options":["25°","12,5°","155°","50°"],"correct":3,"answer":"50°","explanation":"🔑 Góc ban đầu gấp đôi mỗi nửa: 2 · 25° = <b>50°</b>.<br>✗ 25° chỉ là số đo một nửa góc, chưa phải cả góc.<br>✗ 12,5° là chia đôi tiếp — làm ngược chiều phép tính.<br>✗ 155° = 180° − 25°, dùng nhầm công thức hai góc kề bù."},{"id":"m3-19","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt hai đường thẳng a và b. Điều kiện nào sau đây đủ để kết luận a ∥ b?","options":["Một cặp góc so le trong bằng nhau","Một cặp góc so le trong bù nhau","Một cặp góc đồng vị bù nhau","Hai góc kề bù bằng nhau"],"correct":0,"answer":"Một cặp góc so le trong bằng nhau","explanation":"🔑 Dấu hiệu nhận biết: một cặp góc <b>so le trong bằng nhau</b> (hoặc một cặp góc <b>đồng vị bằng nhau</b>) ⇒ a ∥ b.<br>✗ So le trong BÙ nhau không phải dấu hiệu; cặp bù nhau khi song song là hai góc <b>trong cùng phía</b>.<br>✗ Đồng vị cũng phải BẰNG nhau, không phải bù nhau.<br>✗ Hai góc kề bù bằng nhau chỉ cho biết mỗi góc bằng 90°, không nói gì về quan hệ giữa a và b."},{"id":"m3-20","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt a tại A và cắt b tại B, tạo ra một cặp góc đồng vị bằng nhau. Kết luận nào đúng?","options":["a ⊥ b","a ∥ b","a ⊥ c","a trùng b"],"correct":1,"answer":"a ∥ b","explanation":"🔑 Hai góc đồng vị bằng nhau là dấu hiệu nhận biết: <b>a ∥ b</b>.<br>✗ a ⊥ b là quan hệ vuông góc, chỉ kết luận được khi biết một góc giữa a và b bằng 90°.<br>✗ a ⊥ c cũng cần góc giữa a và c bằng 90°, đề không cho dữ kiện đó.<br>✗ a trùng b là sai vì c cắt chúng tại hai điểm khác nhau A và B."},{"id":"m3-21","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b và đường thẳng c cắt cả hai đường đó. Khi đó các góc so le trong có quan hệ gì?","options":["Bù nhau (tổng bằng 180°)","Phụ nhau (tổng bằng 90°)","Bằng nhau","Không có quan hệ gì đặc biệt"],"correct":2,"answer":"Bằng nhau","explanation":"🔑 a ∥ b ⇒ các góc <b>so le trong bằng nhau</b> (và các góc đồng vị cũng bằng nhau).<br>✗ Bù nhau là quan hệ của hai góc <b>trong cùng phía</b> khi a ∥ b, không phải so le trong.<br>✗ Phụ nhau (90°) không phải quan hệ của cặp góc nào trong tình huống này.<br>✗ Chúng có quan hệ rất rõ ràng — bằng nhau — đó chính là tính chất của hai đường thẳng song song."},{"id":"m3-22","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Một góc so le trong bằng 65°. Góc so le trong còn lại của cặp đó bằng bao nhiêu?","options":["115°","25°","130°","65°"],"correct":3,"answer":"65°","explanation":"🔑 a ∥ b ⇒ hai góc so le trong bằng nhau, nên góc còn lại cũng bằng <b>65°</b>.<br>✗ 115° = 180° − 65° là số đo góc <b>trong cùng phía</b>, không phải so le trong.<br>✗ 25° = 90° − 65°, dùng nhầm quan hệ phụ nhau.<br>✗ 130° = 2 · 65°, nhân đôi hoàn toàn vô căn cứ."},{"id":"m3-23","ch":3,"topic":"Góc trong cùng phía","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Một góc trong cùng phía bằng 65°. Góc trong cùng phía kia bằng bao nhiêu?","options":["65°","115°","25°","180°"],"correct":1,"answer":"115°","explanation":"🔑 Khi a ∥ b, hai góc trong cùng phía <b>bù nhau</b>: 180° − 65° = <b>115°</b>.<br>✗ 65° là nhầm sang góc so le trong hoặc đồng vị — chỉ những cặp đó mới bằng nhau.<br>✗ 25° = 90° − 65°, dùng nhầm quan hệ phụ nhau.<br>✗ 180° là tổng của hai góc, không phải số đo góc còn lại."},{"id":"m3-24","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c, một góc đồng vị bằng 110°. Góc đồng vị tương ứng với nó bằng bao nhiêu?","options":["70°","20°","110°","55°"],"correct":2,"answer":"110°","explanation":"🔑 a ∥ b ⇒ các góc đồng vị bằng nhau, nên góc đó cũng bằng <b>110°</b>.<br>✗ 70° = 180° − 110° là số đo góc kề bù hoặc góc trong cùng phía, không phải góc đồng vị.<br>✗ 20° = 110° − 90°, một phép trừ không có căn cứ nào.<br>✗ 55° là một nửa của 110° — dùng nhầm công thức tia phân giác."},{"id":"m3-25","ch":3,"topic":"Chiều của mệnh đề","q":"Mệnh đề “Hai góc so le trong bằng nhau ⇒ a ∥ b” được gọi là gì?","options":["Dấu hiệu nhận biết hai đường thẳng song song","Tính chất của hai đường thẳng song song","Tiên đề Euclid về đường thẳng song song","Định nghĩa hai góc kề bù"],"correct":0,"answer":"Dấu hiệu nhận biết hai đường thẳng song song","explanation":"🔑 Đi từ <b>GÓC ⇒ SONG SONG</b> là <b>dấu hiệu nhận biết</b> hai đường thẳng song song.<br>✗ Tính chất là chiều ngược lại: a ∥ b ⇒ các góc so le trong bằng nhau.<br>✗ Tiên đề Euclid nói về số đường thẳng song song kẻ được qua một điểm ngoài đường thẳng.<br>✗ Định nghĩa hai góc kề bù nói về tổng 180°, không liên quan đến hai đường a và b."},{"id":"m3-26","ch":3,"topic":"Chiều của mệnh đề","q":"Mệnh đề “a ∥ b ⇒ các góc đồng vị bằng nhau” được gọi là gì?","options":["Dấu hiệu nhận biết hai đường thẳng song song","Định nghĩa hai đường thẳng song song","Tính chất của hai đường thẳng song song","Tiên đề Euclid về đường thẳng song song"],"correct":2,"answer":"Tính chất của hai đường thẳng song song","explanation":"🔑 Đi từ <b>SONG SONG ⇒ GÓC bằng nhau</b> là <b>tính chất</b> của hai đường thẳng song song.<br>✗ Dấu hiệu nhận biết là chiều ngược lại: góc bằng nhau ⇒ a ∥ b.<br>✗ Định nghĩa hai đường thẳng song song là hai đường không có điểm chung, không nhắc đến góc.<br>✗ Tiên đề Euclid nói về tính duy nhất của đường thẳng song song kẻ qua một điểm."},{"id":"m3-27","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Khẳng định nào sau đây SAI?","options":["Các góc so le trong bằng nhau","Các góc đồng vị bằng nhau","Hai góc trong cùng phía bù nhau","Hai góc trong cùng phía bằng nhau"],"correct":3,"answer":"Hai góc trong cùng phía bằng nhau","explanation":"🔑 Khi a ∥ b, hai góc trong cùng phía <b>bù nhau</b> (tổng 180°) chứ không bằng nhau — nên đây là khẳng định SAI.<br>✗ “So le trong bằng nhau” là ĐÚNG, đó là tính chất cơ bản của hai đường song song.<br>✗ “Đồng vị bằng nhau” cũng ĐÚNG, luôn đi kèm với so le trong.<br>✗ “Trong cùng phía bù nhau” là ĐÚNG: tổng của chúng bằng 180°."},{"id":"m3-28","ch":3,"topic":"Góc so le trong","q":"Hai góc so le trong nằm ở vị trí nào so với đường thẳng cắt c?","options":["Cùng một phía của c, ở phần trong giữa a và b","Ở hai phía khác nhau của c, ở phần trong giữa a và b","Cùng một phía của c, ở phần ngoài","Cùng phía của c và ở cùng vị trí so với a, b"],"correct":1,"answer":"Ở hai phía khác nhau của c, ở phần trong giữa a và b","explanation":"🔑 Hai góc so le trong nằm ở <b>phần trong</b> (giữa a và b) và ở <b>hai phía khác nhau</b> của đường cắt c — “so le” chính là ý nằm chéo nhau.<br>✗ Cùng phía của c, phần trong là mô tả hai góc <b>trong cùng phía</b>.<br>✗ Cùng phía của c, phần ngoài là mô tả hai góc ngoài cùng phía.<br>✗ Cùng phía và cùng vị trí so với a, b là mô tả hai góc <b>đồng vị</b>."},{"id":"m3-29","ch":3,"topic":"Góc đồng vị","q":"Hai góc đồng vị được mô tả như thế nào?","options":["Nằm ở hai phía khác nhau của đường cắt, ở phần trong","Nằm cùng phía của đường cắt và ở cùng vị trí so với hai đường bị cắt","Nằm cùng phía của đường cắt và cả hai đều ở phần trong","Nằm đối đỉnh nhau qua cùng một giao điểm"],"correct":1,"answer":"Nằm cùng phía của đường cắt và ở cùng vị trí so với hai đường bị cắt","explanation":"🔑 Hai góc đồng vị nằm <b>cùng phía</b> đường cắt và ở <b>cùng vị trí</b> (cùng trên hoặc cùng dưới) so với hai đường bị cắt.<br>✗ “Hai phía khác nhau, phần trong” là mô tả hai góc <b>so le trong</b>.<br>✗ “Cùng phía, cả hai ở phần trong” là mô tả hai góc <b>trong cùng phía</b>.<br>✗ Hai góc đối đỉnh có chung một đỉnh, còn hai góc đồng vị nằm ở hai đỉnh khác nhau."},{"id":"m3-30","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt a và b, tạo ra một cặp góc so le trong lần lượt bằng 70° và 80°. Kết luận nào đúng?","options":["a ∥ b vì hai góc đều là góc nhọn","a ∥ b vì 70° + 80° nhỏ hơn 180°","a không song song với b vì hai góc so le trong không bằng nhau","a ⊥ b"],"correct":2,"answer":"a không song song với b vì hai góc so le trong không bằng nhau","explanation":"🔑 Muốn a ∥ b thì cặp góc so le trong phải <b>bằng nhau</b>; ở đây 70° ≠ 80° nên a không song song với b.<br>✗ Cả hai cùng là góc nhọn là chưa đủ — điều kiện bắt buộc là hai góc phải bằng nhau.<br>✗ Tổng nhỏ hơn 180° không phải dấu hiệu nào cả; cặp có tổng đúng 180° mới là hai góc trong cùng phía.<br>✗ a ⊥ b cần một góc giữa a và b bằng 90°, đề không hề cho dữ kiện đó."},{"id":"m3-31","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c, một trong các góc tạo thành bằng 90°. Các góc còn lại bằng bao nhiêu?","options":["Tất cả đều bằng 90°","Một nửa số góc bằng 90°, nửa còn lại bằng 45°","Không xác định được","Tất cả đều bằng 180°"],"correct":0,"answer":"Tất cả đều bằng 90°","explanation":"🔑 Góc đối đỉnh bằng 90°, góc kề bù bằng 180° − 90° = 90°, và vì a ∥ b nên các góc đồng vị cũng bằng 90°: <b>cả tám góc đều vuông</b> (đây chính là trường hợp c ⊥ a và c ⊥ b).<br>✗ 45° chỉ xuất hiện khi chia đôi 90°, mà ở đây không có phép chia đôi nào.<br>✗ Hoàn toàn xác định được nhờ tính chất góc kề bù, góc đối đỉnh và hai đường thẳng song song.<br>✗ 180° là số đo góc bẹt, không thể là góc tạo bởi hai đường thẳng cắt nhau."},{"id":"m3-32","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b bị cắt bởi đường thẳng c. Một góc tạo thành bằng 55°, hỏi góc kề bù với nó bằng bao nhiêu?","options":["55°","35°","125°","110°"],"correct":2,"answer":"125°","explanation":"🔑 Hai góc kề bù luôn có tổng 180°, nên góc cần tìm bằng 180° − 55° = <b>125°</b>.<br>✗ 55° là số đo góc đối đỉnh hoặc góc đồng vị với nó, không phải góc kề bù.<br>✗ 35° = 90° − 55°, dùng nhầm quan hệ phụ nhau.<br>✗ 110° = 2 · 55°, nhân đôi vô căn cứ."},{"id":"m3-33","ch":3,"topic":"Dấu hiệu nhận biết hai đường thẳng song song","q":"Đường thẳng c cắt a và b, hai góc trong cùng phía có số đo 120° và 60°. Kết luận nào đúng?","options":["a không song song với b vì hai góc không bằng nhau","a ∥ b vì hai góc trong cùng phía bù nhau","a ⊥ b","Không kết luận được gì"],"correct":1,"answer":"a ∥ b vì hai góc trong cùng phía bù nhau","explanation":"🔑 120° + 60° = 180° nên hai góc trong cùng phía bù nhau; điều này kéo theo một cặp góc so le trong bằng nhau, do đó <b>a ∥ b</b>.<br>✗ Hai góc trong cùng phía không cần bằng nhau — điều kiện của chúng là bù nhau.<br>✗ a ⊥ b cần một góc giữa a và b bằng 90°, đề không cho điều đó.<br>✗ Kết luận được rất rõ: tổng bằng 180° chính là dấu hiệu song song."},{"id":"m3-34","ch":3,"topic":"Tính chất hai đường thẳng song song","q":"Cho a ∥ b, đường thẳng c cắt a tại điểm A. Hỏi c có cắt b hay không?","options":["Không, vì c ∥ b","Có, c chắc chắn cắt b","Chỉ cắt khi c ⊥ a","Không xác định được"],"correct":1,"answer":"Có, c chắc chắn cắt b","explanation":"🔑 Nếu c không cắt b thì c ∥ b; khi đó qua điểm A có tới hai đường thẳng a và c cùng song song với b, trái tiên đề Euclid. Vậy <b>c phải cắt b</b>.<br>✗ c ∥ b là không thể, vì c đã cắt a mà a ∥ b.<br>✗ Điều kiện c ⊥ a là không cần thiết: mọi đường thẳng cắt a đều cắt b.<br>✗ Hoàn toàn xác định được nhờ tiên đề về đường thẳng song song."},{"id":"m3-35","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Nếu a ⊥ c và b ⊥ c (a, b phân biệt) thì hai đường thẳng a và b có quan hệ gì?","options":["a ⊥ b","a trùng b","a cắt b tại một điểm","a ∥ b"],"correct":3,"answer":"a ∥ b","explanation":"🔑 Hai đường thẳng phân biệt cùng vuông góc với một đường thẳng thứ ba thì song song với nhau: <b>a ⊥ c, b ⊥ c ⇒ a ∥ b</b>.<br>✗ a ⊥ b là lỗi kinh điển: “cùng vuông góc” cho kết quả SONG SONG chứ không phải vuông góc.<br>✗ a trùng b bị loại vì đề đã nói a, b là hai đường phân biệt.<br>✗ a cắt b là sai vì hai đường thẳng song song không có điểm chung."},{"id":"m3-36","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ∥ b và c ⊥ a. Kết luận nào sau đây đúng?","options":["c ⊥ b","c ∥ b","c ∥ a","c cắt b tạo thành góc 45°"],"correct":0,"answer":"c ⊥ b","explanation":"🔑 Đường thẳng vuông góc với một trong hai đường thẳng song song thì cũng vuông góc với đường còn lại: <b>a ∥ b, c ⊥ a ⇒ c ⊥ b</b>.<br>✗ c ∥ b là sai vì c đã cắt a, mà a ∥ b nên c bắt buộc cắt b.<br>✗ c ∥ a mâu thuẫn ngay với giả thiết c ⊥ a.<br>✗ 45° không có căn cứ: góc giữa c và b đúng bằng góc giữa c và a, tức 90°."},{"id":"m3-37","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Hai đường thẳng phân biệt a và b cùng vuông góc với đường thẳng c. Khẳng định nào sau đây SAI?","options":["a ∥ b","a và b không có điểm chung","Góc giữa a và c bằng 90°","a ⊥ b"],"correct":3,"answer":"a ⊥ b","explanation":"🔑 Từ a ⊥ c và b ⊥ c ta suy ra a ∥ b, nên “a ⊥ b” là khẳng định SAI.<br>✗ “a ∥ b” là ĐÚNG, đó chính là kết luận của quy tắc.<br>✗ “Không có điểm chung” là ĐÚNG vì hai đường song song không cắt nhau.<br>✗ “Góc giữa a và c bằng 90°” là ĐÚNG, đó là ý nghĩa của ký hiệu a ⊥ c."},{"id":"m3-38","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho ba đường thẳng phân biệt a, b, c với a ∥ b và b ∥ c. Quan hệ giữa a và c là gì?","options":["a ⊥ c","a cắt c","a ∥ c","Không xác định được"],"correct":2,"answer":"a ∥ c","explanation":"🔑 Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì song song với nhau: <b>a ∥ b, b ∥ c ⇒ a ∥ c</b>.<br>✗ a ⊥ c là nhầm ký hiệu ∥ thành ⊥; giả thiết không hề có góc vuông nào.<br>✗ a cắt c là sai: nếu chúng cắt nhau thì qua giao điểm đó có hai đường cùng song song với b, trái tiên đề.<br>✗ Hoàn toàn xác định được nhờ tính bắc cầu của quan hệ song song."},{"id":"m3-39","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ⊥ c, b ⊥ c và d ⊥ a (các đường thẳng phân biệt). Quan hệ giữa d và b là gì?","options":["d ∥ b","d cắt b tạo thành góc 45°","d trùng b","d ⊥ b"],"correct":3,"answer":"d ⊥ b","explanation":"🔑 Hai bước: từ a ⊥ c và b ⊥ c suy ra a ∥ b; lại có d ⊥ a nên theo quy tắc “vuông góc với một trong hai đường song song” ta được <b>d ⊥ b</b>.<br>✗ d ∥ b là sai: d vuông góc với a, mà a ∥ b, nên d cắt b chứ không song song.<br>✗ 45° không có căn cứ; góc giữa d và b đúng bằng góc giữa d và a, tức 90°.<br>✗ d trùng b không suy ra được — d và b là hai đường khác nhau, thậm chí vuông góc với nhau."},{"id":"m3-40","ch":3,"topic":"Ký hiệu ∥ và ⊥","q":"Hai ký hiệu “a ∥ b” và “a ⊥ b” lần lượt có nghĩa là gì?","options":["a vuông góc với b; a song song với b","a song song với b; a vuông góc với b","a bằng b; a cắt b","a cắt b; a trùng b"],"correct":1,"answer":"a song song với b; a vuông góc với b","explanation":"🔑 Ký hiệu <b>∥</b> đọc là “song song”, ký hiệu <b>⊥</b> đọc là “vuông góc”.<br>✗ Đảo hai ký hiệu cho nhau là lỗi rất hay gặp khi làm bài vội.<br>✗ ∥ không có nghĩa “bằng nhau”; hai đại lượng bằng nhau dùng dấu =.<br>✗ ⊥ không có nghĩa “trùng nhau”; nó chỉ góc 90° giữa hai đường thẳng."},{"id":"m3-41","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ∥ b. Nếu đường thẳng c cắt a tạo thành góc 90° thì góc giữa c và b bằng bao nhiêu?","options":["45°","180°","Không xác định được","90°"],"correct":3,"answer":"90°","explanation":"🔑 c ⊥ a và a ∥ b ⇒ c ⊥ b, nên góc giữa c và b cũng bằng <b>90°</b>.<br>✗ 45° là một nửa của 90°, mà ở đây không có phép chia đôi nào.<br>✗ 180° là số đo góc bẹt, không phải góc giữa hai đường thẳng cắt nhau.<br>✗ Xác định được ngay nhờ quy tắc “vuông góc với một trong hai đường thẳng song song”."},{"id":"m3-42","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Khẳng định nào sau đây là ĐÚNG?","options":["Hai đường thẳng phân biệt cùng vuông góc với một đường thẳng thứ ba thì song song với nhau","Hai đường thẳng cùng vuông góc với một đường thẳng thứ ba thì vuông góc với nhau","Hai đường thẳng cùng song song với một đường thẳng thứ ba thì vuông góc với nhau","Hai đường thẳng cắt nhau thì song song với nhau"],"correct":0,"answer":"Hai đường thẳng phân biệt cùng vuông góc với một đường thẳng thứ ba thì song song với nhau","explanation":"🔑 <b>a ⊥ c và b ⊥ c ⇒ a ∥ b</b> — cùng vuông góc với một đường thì song song với nhau.<br>✗ “Cùng vuông góc thì vuông góc với nhau” là đổi kết luận từ ∥ thành ⊥, sai hoàn toàn.<br>✗ “Cùng song song thì vuông góc” cũng sai: cùng song song với một đường thì <b>song song</b> với nhau.<br>✗ “Cắt nhau thì song song” tự mâu thuẫn, vì song song nghĩa là không có điểm chung."},{"id":"m3-43","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Bạn Nam viết: “a ⊥ c, b ⊥ c ⇒ a ⊥ b”. Bạn Nam sai ở chỗ nào?","options":["Không sai, kết luận của bạn Nam đúng","Sai ở giả thiết: phải viết là a ∥ c","Sai ở kết luận: phải là a ∥ b","Sai ở kết luận: phải là a trùng b"],"correct":2,"answer":"Sai ở kết luận: phải là a ∥ b","explanation":"🔑 Quy tắc đúng là <b>a ⊥ c, b ⊥ c ⇒ a ∥ b</b>: cùng vuông góc với một đường thứ ba thì SONG SONG với nhau, không phải vuông góc.<br>✗ Kết luận a ⊥ b là sai nên không thể nói “không sai”.<br>✗ Giả thiết a ⊥ c, b ⊥ c đã đúng và đầy đủ; không cần sửa giả thiết.<br>✗ a trùng b chỉ xảy ra trong trường hợp riêng, không phải kết luận chung của quy tắc."},{"id":"m3-44","ch":3,"topic":"Quan hệ vuông góc và song song","q":"Cho a ∥ b, b ∥ c và d ⊥ a (các đường thẳng phân biệt). Kết luận nào đúng về d và c?","options":["d ∥ c","Chỉ biết d ⊥ a, không suy ra được gì về d và c","d trùng c","d ⊥ c"],"correct":3,"answer":"d ⊥ c","explanation":"🔑 a ∥ b và b ∥ c ⇒ a ∥ c; lại có d ⊥ a nên <b>d ⊥ c</b> (vuông góc với một trong các đường song song thì vuông góc với tất cả).<br>✗ d ∥ c là sai: d cắt a mà a ∥ c nên d cũng cắt c.<br>✗ Suy ra được rất rõ, chỉ cần dùng tính bắc cầu của quan hệ song song rồi áp dụng quy tắc vuông góc.<br>✗ d trùng c không có căn cứ; hai đường này còn vuông góc với nhau."},{"id":"m3-45","ch":3,"topic":"Tiên đề Euclid","q":"Qua một điểm nằm ngoài một đường thẳng, có bao nhiêu đường thẳng song song với đường thẳng đó?","options":["Đúng một đường thẳng","Hai đường thẳng","Vô số đường thẳng","Không có đường thẳng nào"],"correct":0,"answer":"Đúng một đường thẳng","explanation":"🔑 Tiên đề Euclid: qua một điểm nằm ngoài một đường thẳng, <b>chỉ có MỘT</b> đường thẳng song song với đường thẳng đó.<br>✗ Hai đường thẳng là sai — tiên đề khẳng định tính <b>duy nhất</b>.<br>✗ Vô số là nhầm với số đường thẳng kẻ được qua điểm đó (vô số đường, nhưng chỉ một đường song song).<br>✗ “Không có đường nào” chỉ đúng khi điểm đó nằm TRÊN đường thẳng đã cho."},{"id":"m3-46","ch":3,"topic":"Tiên đề Euclid","q":"Điểm M nằm ngoài đường thẳng d. Qua M đã kẻ được đường thẳng a với a ∥ d. Nếu kẻ tiếp một đường thẳng b qua M sao cho b ∥ d thì điều gì xảy ra?","options":["b vuông góc với a","b cắt a tại M","b song song với a","b trùng với a"],"correct":3,"answer":"b trùng với a","explanation":"🔑 Theo tiên đề Euclid, qua M chỉ có <b>duy nhất một</b> đường thẳng song song với d, nên b bắt buộc <b>trùng với a</b>.<br>✗ b ⊥ a là vô lý vì cả hai cùng song song với d thì không thể vuông góc với nhau.<br>✗ b cắt a tại M nghĩa là có hai đường phân biệt qua M cùng song song với d — trái tiên đề.<br>✗ “b song song với a” nghe hợp lý nhưng hai đường cùng đi qua M mà song song thì chỉ có thể là một đường duy nhất, tức trùng nhau."},{"id":"m3-47","ch":3,"topic":"Tiên đề Euclid","q":"Cho điểm A nằm TRÊN đường thẳng d. Qua A kẻ được bao nhiêu đường thẳng song song với d?","options":["Đúng một đường thẳng","Không có đường thẳng nào","Vô số đường thẳng","Hai đường thẳng"],"correct":1,"answer":"Không có đường thẳng nào","explanation":"🔑 Mọi đường thẳng qua A đều có điểm chung A với d nên không thể song song với d. Tiên đề chỉ áp dụng cho điểm nằm <b>NGOÀI</b> đường thẳng.<br>✗ “Đúng một đường” là áp dụng tiên đề mà quên mất điều kiện điểm phải nằm ngoài d.<br>✗ Vô số là nhầm với số đường thẳng kẻ được qua A — vô số đường, nhưng không đường nào song song với d.<br>✗ Hai đường thẳng không đúng trong bất kỳ trường hợp nào."},{"id":"m3-48","ch":3,"topic":"Tiên đề Euclid","q":"Phát biểu nào sau đây chính là tiên đề về đường thẳng song song?","options":["Qua một điểm nằm ngoài một đường thẳng, chỉ có một đường thẳng song song với đường thẳng đó","Qua một điểm nằm ngoài một đường thẳng, có ít nhất hai đường thẳng song song với đường thẳng đó","Qua một điểm bất kỳ luôn có một đường thẳng song song với mọi đường thẳng cho trước","Hai đường thẳng cùng vuông góc với một đường thẳng thứ ba thì song song với nhau"],"correct":0,"answer":"Qua một điểm nằm ngoài một đường thẳng, chỉ có một đường thẳng song song với đường thẳng đó","explanation":"🔑 Tiên đề Euclid phát biểu đúng như vậy: qua điểm nằm ngoài đường thẳng có <b>duy nhất một</b> đường thẳng song song với nó.<br>✗ “Ít nhất hai” phá vỡ tính duy nhất, trái hẳn với tiên đề.<br>✗ “Qua một điểm bất kỳ” là sai vì điểm bắt buộc phải nằm NGOÀI đường thẳng đã cho.<br>✗ “Cùng vuông góc thì song song” là một quy tắc về quan hệ ⊥ và ∥, không phải tiên đề này."},{"id":"m3-49","ch":3,"topic":"Tiên đề Euclid","q":"Cho đường thẳng d và điểm M không thuộc d. Số đường thẳng đi qua M và số đường thẳng đi qua M song song với d lần lượt là bao nhiêu?","options":["Một và một","Vô số và vô số","Vô số và một","Một và vô số"],"correct":2,"answer":"Vô số và một","explanation":"🔑 Qua một điểm kẻ được <b>vô số</b> đường thẳng, nhưng trong số đó chỉ có <b>duy nhất một</b> đường song song với d (tiên đề Euclid).<br>✗ “Một và một” sai ở vế đầu: qua một điểm kẻ được vô số đường thẳng chứ không phải một.<br>✗ “Vô số và vô số” sai ở vế sau, phá vỡ tính duy nhất mà tiên đề khẳng định.<br>✗ “Một và vô số” là đảo ngược cả hai vế."},{"id":"m3-50","ch":3,"topic":"Tiên đề Euclid","q":"Từ tiên đề Euclid, có thể suy ra khẳng định nào sau đây?","options":["Qua một điểm nằm ngoài đường thẳng d, kẻ được vô số đường thẳng song song với d","Hai đường thẳng phân biệt cùng đi qua một điểm thì song song với nhau","Mọi đường thẳng đều song song với nhau","Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì song song với nhau"],"correct":3,"answer":"Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì song song với nhau","explanation":"🔑 Nếu hai đường phân biệt a, c cùng song song với b mà lại cắt nhau, thì qua giao điểm sẽ có hai đường cùng song song với b — trái tiên đề. Vậy <b>a ∥ c</b>.<br>✗ “Vô số đường song song” trái ngược hẳn với tiên đề (chỉ có duy nhất một).<br>✗ Hai đường phân biệt cùng đi qua một điểm thì <b>cắt nhau</b> tại điểm đó, không thể song song.<br>✗ “Mọi đường thẳng đều song song” là sai hiển nhiên: hai đường bất kỳ hoàn toàn có thể cắt nhau."},{"id":"m4-1","ch":4,"topic":"Tổng ba góc","q":"Tổng ba góc trong một tam giác bằng bao nhiêu?","options":["∠A + ∠B + ∠C = 180°","∠A + ∠B + ∠C = 360°","∠A + ∠B + ∠C = 90°","∠A + ∠B = ∠C"],"correct":0,"answer":"∠A + ∠B + ∠C = 180°","explanation":"🔑 Tổng ba góc trong bất kỳ tam giác nào cũng bằng 180°.<br>✗ 360° là tổng bốn góc của tứ giác.<br>✗ 90° chỉ là tổng hai góc nhọn của tam giác vuông.<br>✗ ∠A + ∠B = ∠C không phải một định lý — chỉ đúng tình cờ khi ∠C = 90°."},{"id":"m4-2","ch":4,"topic":"Tổng ba góc","q":"Tam giác ABC có ∠A = 60°, ∠B = 70°. Số đo của ∠C là bao nhiêu?","options":["∠C = 130°","∠C = 50°","∠C = 60°","∠C = 70°"],"correct":1,"answer":"∠C = 50°","explanation":"🔑 ∠C = 180° − (∠A + ∠B) = 180° − 130° = 50°.<br>✗ 130° mới chỉ là tổng hai góc đã cho, còn thiếu bước lấy 180° trừ đi.<br>✗ 60° là số đo của ∠A, không phải ∠C.<br>✗ 70° là số đo của ∠B, chép nhầm sang ∠C."},{"id":"m4-3","ch":4,"topic":"Tam giác vuông","q":"Tam giác ABC vuông tại A. Hệ thức nào sau đây đúng?","options":["∠B + ∠C = 180°","∠B + ∠C = 45°","∠B + ∠C = 90°","∠B = ∠C = 90°"],"correct":2,"answer":"∠B + ∠C = 90°","explanation":"🔑 Vì ∠A = 90° nên ∠B + ∠C = 180° − 90° = 90°: hai góc nhọn của tam giác vuông luôn phụ nhau.<br>✗ 180° là tổng CẢ BA góc, không phải tổng hai góc nhọn.<br>✗ 45° là số đo của MỖI góc nhọn khi tam giác vuông cân, không phải tổng của chúng.<br>✗ Một tam giác không thể có hai góc 90°, vì khi đó riêng hai góc ấy đã đủ 180° mà vẫn còn thừa ∠A."},{"id":"m4-4","ch":4,"topic":"Góc ngoài","q":"Góc ngoài tại một đỉnh của tam giác bằng gì?","options":["Bằng góc trong kề với nó","Bằng 180°","Bằng tổng ba góc trong của tam giác","Bằng tổng hai góc trong không kề với nó"],"correct":3,"answer":"Bằng tổng hai góc trong không kề với nó","explanation":"🔑 Góc ngoài tại một đỉnh bằng TỔNG hai góc trong không kề với nó.<br>✗ Góc ngoài và góc trong kề nó là hai góc kề bù, cộng lại bằng 180° chứ không bằng nhau.<br>✗ 180° là tổng của góc ngoài với góc trong kề nó, không phải riêng góc ngoài.<br>✗ Tổng ba góc trong luôn là 180°, nếu góc ngoài bằng 180° thì nó là góc bẹt — vô lí."},{"id":"m4-5","ch":4,"topic":"Góc ngoài","q":"Tam giác ABC có ∠A = 50°, ∠B = 65°. Số đo góc ngoài tại đỉnh C là bao nhiêu?","options":["65°","115°","130°","50°"],"correct":1,"answer":"115°","explanation":"🔑 Góc ngoài tại C bằng tổng hai góc trong không kề: ∠A + ∠B = 50° + 65° = 115°.<br>✗ 65° là góc trong ∠B, không phải góc ngoài tại C.<br>✗ 130° là 65° × 2, nhân đôi một góc là hiểu sai công thức.<br>✗ 50° là góc trong ∠A."},{"id":"m4-6","ch":4,"topic":"Góc ngoài","q":"Góc ngoài tại đỉnh A và góc trong ∠A của tam giác ABC có quan hệ gì?","options":["Chúng kề bù, tổng bằng 180°","Chúng luôn bằng nhau","Chúng phụ nhau, tổng bằng 90°","Góc ngoài luôn gấp đôi góc trong ∠A"],"correct":0,"answer":"Chúng kề bù, tổng bằng 180°","explanation":"🔑 Góc ngoài tại A và góc trong ∠A là hai góc kề bù nên tổng của chúng bằng 180°.<br>✗ Chúng chỉ bằng nhau trong trường hợp đặc biệt cùng bằng 90°, không phải luôn luôn.<br>✗ Phụ nhau (tổng 90°) là quan hệ của hai góc nhọn trong tam giác vuông, không phải quan hệ này.<br>✗ Góc ngoài gấp đôi góc trong chỉ xảy ra khi ∠A = 60°, đó là trường hợp riêng chứ không phải quy luật."},{"id":"m4-7","ch":4,"topic":"Tổng ba góc","q":"Một tam giác có thể có nhiều nhất bao nhiêu góc tù (góc lớn hơn 90°)?","options":["Ba góc tù","Hai góc tù","Không có góc tù nào","Một góc tù"],"correct":3,"answer":"Một góc tù","explanation":"🔑 Vì tổng ba góc chỉ có 180° nên nhiều nhất một góc được phép lớn hơn 90°.<br>✗ Ba góc tù thì tổng đã vượt quá 270°, lớn hơn 180° rất nhiều.<br>✗ Hai góc tù thì riêng hai góc đó đã hơn 180°, không còn chỗ cho góc thứ ba.<br>✗ Nói không có góc tù nào là sai, vì tam giác tù có thật, ví dụ 100° + 50° + 30° = 180°."},{"id":"m4-8","ch":4,"topic":"Tổng ba góc","q":"Tam giác ABC có ∠A = ∠B = ∠C. Số đo mỗi góc là bao nhiêu?","options":["90°","45°","60°","120°"],"correct":2,"answer":"60°","explanation":"🔑 Ba góc bằng nhau và có tổng 180° nên mỗi góc bằng 180° : 3 = 60°.<br>✗ Nếu mỗi góc 90° thì tổng là 270°, vượt quá 180°.<br>✗ Nếu mỗi góc 45° thì tổng chỉ 135°, còn thiếu so với 180°.<br>✗ Nếu mỗi góc 120° thì tổng là 360° — đó là tổng bốn góc của tứ giác."},{"id":"m4-9","ch":4,"topic":"Tam giác vuông","q":"Tam giác MNP vuông tại M có ∠N = 35°. Số đo ∠P là bao nhiêu?","options":["145°","35°","55°","90°"],"correct":2,"answer":"55°","explanation":"🔑 Hai góc nhọn của tam giác vuông phụ nhau nên ∠P = 90° − 35° = 55°.<br>✗ 145° là kết quả của 180° − 35°, quên rằng ∠M đã chiếm mất 90°.<br>✗ 35° là số đo ∠N; hai góc nhọn chỉ bằng nhau khi cùng bằng 45°.<br>✗ 90° là số đo ∠M, một tam giác không thể có hai góc vuông."},{"id":"m4-10","ch":4,"topic":"Tổng ba góc","q":"Bộ ba số đo nào sau đây KHÔNG thể là ba góc của một tam giác?","options":["100°; 50°; 30°","60°; 60°; 60°","90°; 45°; 45°","80°; 60°; 50°"],"correct":3,"answer":"80°; 60°; 50°","explanation":"🔑 Ba góc của một tam giác phải có tổng đúng bằng 180°, mà 80° + 60° + 50° = 190° nên bộ này không hợp lệ.<br>✗ 100° + 50° + 30° = 180°, đây là một tam giác tù bình thường.<br>✗ 60° + 60° + 60° = 180°, đó chính là tam giác đều.<br>✗ 90° + 45° + 45° = 180°, đó là tam giác vuông cân."},{"id":"m4-11","ch":4,"topic":"Trường hợp c-c-c","q":"Trường hợp bằng nhau nào của tam giác chỉ cần so sánh ba cạnh, không cần góc nào?","options":["c-c-c (cạnh - cạnh - cạnh)","c-g-c (cạnh - góc - cạnh)","g-c-g (góc - cạnh - góc)","g-g-g (góc - góc - góc)"],"correct":0,"answer":"c-c-c (cạnh - cạnh - cạnh)","explanation":"🔑 Trường hợp c-c-c: ba cạnh của tam giác này bằng ba cạnh của tam giác kia thì hai tam giác bằng nhau.<br>✗ c-g-c còn cần thêm một góc, và phải đúng là góc XEN GIỮA hai cạnh.<br>✗ g-c-g cần một cạnh cùng hai góc kề cạnh ấy, tức là vẫn phải dùng góc.<br>✗ g-g-g hoàn toàn KHÔNG phải trường hợp bằng nhau — ba góc bằng nhau chỉ cho hai tam giác cùng hình dạng, kích thước có thể khác hẳn."},{"id":"m4-12","ch":4,"topic":"Trường hợp c-g-c","q":"Trong trường hợp bằng nhau c-g-c, góc bằng nhau phải nằm ở vị trí nào?","options":["Góc đối diện với một trong hai cạnh đã cho","Góc xen giữa hai cạnh đã cho","Góc bất kì trong tam giác cũng được","Góc lớn nhất của tam giác"],"correct":1,"answer":"Góc xen giữa hai cạnh đã cho","explanation":"🔑 Trường hợp c-g-c đòi hỏi hai cạnh bằng nhau và góc XEN GIỮA đúng hai cạnh ấy bằng nhau.<br>✗ Nếu góc đối diện với một cạnh thì đó là kiểu <b>c-c-g</b> — không phải trường hợp bằng nhau, vì từ dữ kiện đó có thể vẽ ra hai tam giác khác nhau.<br>✗ Góc bất kì thì quá lỏng lẻo, bắt buộc phải là góc xen giữa.<br>✗ Góc lớn nhất hay nhỏ nhất không liên quan; chỉ vị trí xen giữa mới quan trọng."},{"id":"m4-13","ch":4,"topic":"Trường hợp g-c-g","q":"Điều kiện về vị trí của cạnh trong trường hợp bằng nhau g-c-g là gì?","options":["Cạnh dài nhất của tam giác","Cạnh đối diện với một trong hai góc đã cho","Cạnh bất kì cũng được","Cạnh kề với cả hai góc đã cho"],"correct":3,"answer":"Cạnh kề với cả hai góc đã cho","explanation":"🔑 Trường hợp g-c-g: một cạnh và HAI GÓC KỀ cạnh ấy bằng nhau thì hai tam giác bằng nhau.<br>✗ Cạnh dài nhất hay ngắn nhất không phải điều kiện; chỉ vị trí kề hai góc mới quan trọng.<br>✗ Cạnh đối diện với một góc cho ta kiểu <b>g-g-c</b>, ở lớp 7 chưa được dùng như một trường hợp bằng nhau.<br>✗ Chọn cạnh bất kì là hiểu sai — cạnh phải nằm giữa hai góc đã cho."},{"id":"m4-14","ch":4,"topic":"Trường hợp không hợp lệ","q":"Trường hợp nào sau đây KHÔNG phải là trường hợp bằng nhau của hai tam giác?","options":["c-c-c","c-g-c","g-g-g","g-c-g"],"correct":2,"answer":"g-g-g","explanation":"🔑 g-g-g không phải trường hợp bằng nhau: ba góc bằng nhau chỉ đảm bảo hai tam giác cùng hình dạng, một cái có thể to gấp nhiều lần cái kia.<br>✗ c-c-c là trường hợp bằng nhau đầu tiên được học.<br>✗ c-g-c là trường hợp bằng nhau với góc xen giữa hai cạnh.<br>✗ g-c-g là trường hợp bằng nhau với cạnh kề hai góc."},{"id":"m4-15","ch":4,"topic":"Trường hợp không hợp lệ","q":"△ABC và △MNP có AB = MN, BC = NP và ∠A = ∠M. Có kết luận được hai tam giác bằng nhau không?","options":["Có, theo trường hợp c-g-c","Không, vì ∠A không xen giữa hai cạnh AB và BC","Có, theo trường hợp c-c-c","Có, theo trường hợp g-c-g"],"correct":1,"answer":"Không, vì ∠A không xen giữa hai cạnh AB và BC","explanation":"🔑 Muốn dùng c-g-c thì góc phải XEN GIỮA hai cạnh; góc xen giữa AB và BC là ∠B chứ không phải ∠A, nên dữ kiện chưa đủ.<br>✗ Đây chính là cái bẫy <b>c-c-g</b> mà rất nhiều bạn tưởng nhầm là c-g-c.<br>✗ c-c-c đòi ba cặp cạnh bằng nhau, ở đây mới có hai cặp.<br>✗ g-c-g đòi hai cặp góc bằng nhau, ở đây mới có một cặp góc."},{"id":"m4-16","ch":4,"topic":"Trường hợp c-g-c","q":"△ABC và △DEF có AB = DE, ∠B = ∠E, BC = EF. Hai tam giác bằng nhau theo trường hợp nào?","options":["c-g-c","c-c-c","g-c-g","Chưa đủ dữ kiện để kết luận"],"correct":0,"answer":"c-g-c","explanation":"🔑 ∠B xen giữa hai cạnh AB và BC, ∠E xen giữa DE và EF, nên △ABC = △DEF theo c-g-c.<br>✗ c-c-c cần ba cặp cạnh bằng nhau, đề chỉ cho hai cặp cạnh.<br>✗ g-c-g cần hai cặp góc bằng nhau, đề chỉ cho một cặp góc.<br>✗ Dữ kiện đã hoàn toàn đủ, vì góc đã cho đúng là góc xen giữa."},{"id":"m4-17","ch":4,"topic":"Trường hợp g-c-g","q":"△ABC và △MNP có ∠B = ∠N, BC = NP, ∠C = ∠P. Hai tam giác bằng nhau theo trường hợp nào?","options":["g-c-g","c-g-c","c-c-c","g-g-g"],"correct":0,"answer":"g-c-g","explanation":"🔑 BC là cạnh kề với cả ∠B và ∠C, NP kề với cả ∠N và ∠P, nên △ABC = △MNP theo g-c-g.<br>✗ c-g-c cần hai cặp cạnh bằng nhau, đề chỉ cho một cặp cạnh.<br>✗ c-c-c cần ba cặp cạnh, đề chỉ cho một cặp.<br>✗ g-g-g không phải trường hợp bằng nhau của tam giác."},{"id":"m4-18","ch":4,"topic":"Trường hợp c-c-c","q":"△ABC và △DEF có AB = DE, AC = DF, BC = EF. Kết luận nào đúng?","options":["Hai tam giác chỉ cùng hình dạng, chưa chắc bằng nhau","Cần thêm một cặp góc bằng nhau mới kết luận được","△ABC = △DEF theo trường hợp c-c-c","△ABC = △DEF theo trường hợp c-g-c"],"correct":2,"answer":"△ABC = △DEF theo trường hợp c-c-c","explanation":"🔑 Ba cặp cạnh tương ứng bằng nhau nên △ABC = △DEF theo trường hợp c-c-c.<br>✗ Ba cạnh bằng nhau là bằng nhau hoàn toàn, không phải chỉ cùng hình dạng — chính g-g-g mới dừng ở mức cùng hình dạng.<br>✗ Không cần thêm góc nào cả, c-c-c đã là một trường hợp đầy đủ.<br>✗ c-g-c cần một cặp góc xen giữa, mà đề bài không cho góc nào."},{"id":"m4-19","ch":4,"topic":"Tam giác bằng nhau","q":"Nếu △ABC = △MNP thì cặp cạnh nào sau đây bằng nhau?","options":["AB = NP","AC = MP","BC = MN","AB = MP"],"correct":1,"answer":"AC = MP","explanation":"🔑 Khi viết △ABC = △MNP, các đỉnh tương ứng theo đúng thứ tự A↔M, B↔N, C↔P, nên AC = MP.<br>✗ AB tương ứng với MN chứ không phải NP.<br>✗ BC tương ứng với NP chứ không phải MN.<br>✗ AB tương ứng với MN, viết AB = MP là ghép sai cặp đỉnh."},{"id":"m4-20","ch":4,"topic":"Tam giác bằng nhau","q":"Biết △ABC = △DEF và ∠A = 55°. Số đo ∠D là bao nhiêu?","options":["125°","35°","Không xác định được","55°"],"correct":3,"answer":"55°","explanation":"🔑 Hai tam giác bằng nhau có các góc tương ứng bằng nhau, mà A tương ứng với D nên ∠D = ∠A = 55°.<br>✗ 125° là góc bù với 55°, chẳng liên quan gì tới hai tam giác bằng nhau.<br>✗ 35° là góc phụ với 55°, cũng không phải góc tương ứng.<br>✗ Hoàn toàn xác định được, vì bằng nhau nghĩa là mọi cạnh và mọi góc tương ứng đều bằng nhau."},{"id":"m4-21","ch":4,"topic":"Trường hợp không hợp lệ","q":"Hai tam giác có ba góc bằng nhau từng đôi một thì kết luận nào đúng?","options":["Chúng bằng nhau theo trường hợp g-g-g","Chúng bằng nhau theo trường hợp g-c-g","Chúng bằng nhau vì tam giác nào cũng có tổng ba góc là 180°","Chưa chắc bằng nhau, vì tam giác này có thể lớn hơn tam giác kia"],"correct":3,"answer":"Chưa chắc bằng nhau, vì tam giác này có thể lớn hơn tam giác kia","explanation":"🔑 Ba góc bằng nhau chỉ cho hai tam giác cùng hình dạng; kích thước có thể khác nhau nên chưa kết luận được là bằng nhau.<br>✗ g-g-g không tồn tại như một trường hợp bằng nhau.<br>✗ g-c-g còn cần một cặp CẠNH bằng nhau, mà đề không cho cạnh nào.<br>✗ Tam giác nào cũng có tổng ba góc bằng 180°, nên điều đó chẳng nói lên gì về việc bằng nhau."},{"id":"m4-22","ch":4,"topic":"Trường hợp c-g-c","q":"Hai đoạn thẳng AB và CD cắt nhau tại O là trung điểm của mỗi đoạn. Vì sao △OAC = △OBD?","options":["Vì có ba cặp cạnh bằng nhau (c-c-c)","Vì OA = OB, OC = OD và ∠AOC = ∠BOD là hai góc đối đỉnh (c-g-c)","Vì có hai cặp góc bằng nhau và một cặp cạnh (g-c-g)","Vì ba góc của hai tam giác bằng nhau (g-g-g)"],"correct":1,"answer":"Vì OA = OB, OC = OD và ∠AOC = ∠BOD là hai góc đối đỉnh (c-g-c)","explanation":"🔑 O là trung điểm nên OA = OB và OC = OD; hai góc ∠AOC, ∠BOD đối đỉnh nên bằng nhau và lại đúng là góc XEN GIỮA hai cặp cạnh ấy — chuẩn trường hợp c-g-c.<br>✗ Đề chưa cho AC = BD nên chưa đủ ba cặp cạnh để dùng c-c-c.<br>✗ g-c-g cần hai cặp góc bằng nhau, ở đây mới có một cặp góc đối đỉnh.<br>✗ g-g-g không phải trường hợp bằng nhau của tam giác."},{"id":"m4-23","ch":4,"topic":"Trường hợp c-c-c","q":"△ABC có AB = AC và M là trung điểm của BC. Vì sao △ABM = △ACM?","options":["Vì ∠B = ∠C và BM = CM nên dùng c-g-c","Vì ∠BAM = ∠CAM và AM là cạnh chung nên dùng g-c-g","Vì AB = AC, BM = CM và AM là cạnh chung nên dùng c-c-c","Vì ba góc của hai tam giác bằng nhau nên dùng g-g-g"],"correct":2,"answer":"Vì AB = AC, BM = CM và AM là cạnh chung nên dùng c-c-c","explanation":"🔑 AB = AC theo giả thiết, BM = CM vì M là trung điểm, AM là cạnh chung — đủ ba cặp cạnh nên △ABM = △ACM theo c-c-c.<br>✗ Dùng c-g-c với ∠B, ∠C là sai vị trí: các góc này không xen giữa hai cặp cạnh đang xét.<br>✗ ∠BAM = ∠CAM là điều PHẢI CHỨNG MINH, chưa được phép dùng làm giả thiết.<br>✗ g-g-g không phải trường hợp bằng nhau của tam giác."},{"id":"m4-24","ch":4,"topic":"Trường hợp không hợp lệ","q":"Nhận xét sau đúng hay sai: chỉ cần hai cặp cạnh và một cặp góc bằng nhau là suy ra được hai tam giác bằng nhau?","options":["Sai, góc đó phải là góc xen giữa hai cạnh thì mới kết luận được","Đúng, đó chính là trường hợp c-c-g","Đúng, vì đã có đủ ba yếu tố bằng nhau","Sai, phải có đủ ba cặp cạnh bằng nhau mới kết luận được"],"correct":0,"answer":"Sai, góc đó phải là góc xen giữa hai cạnh thì mới kết luận được","explanation":"🔑 Chỉ khi góc bằng nhau XEN GIỮA hai cạnh (tức trường hợp c-g-c) thì hai tam giác mới chắc chắn bằng nhau.<br>✗ Không hề có trường hợp bằng nhau nào tên là <b>c-c-g</b>; đó là cái bẫy quen thuộc nhất của chương này.<br>✗ Đủ ba yếu tố nhưng sai vị trí thì vẫn vô ích — g-g-g cũng có ba yếu tố mà không kết luận được gì.<br>✗ Không nhất thiết phải có ba cặp cạnh: c-g-c và g-c-g vẫn kết luận được với ít cạnh hơn."},{"id":"m4-25","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Hai tam giác vuông bằng nhau theo trường hợp hai cạnh góc vuông khi nào?","options":["Khi hai cạnh huyền của chúng bằng nhau","Khi hai cạnh góc vuông của tam giác này lần lượt bằng hai cạnh góc vuông của tam giác kia","Khi hai góc nhọn của chúng bằng nhau","Khi một cạnh góc vuông và cạnh huyền bằng nhau"],"correct":1,"answer":"Khi hai cạnh góc vuông của tam giác này lần lượt bằng hai cạnh góc vuông của tam giác kia","explanation":"🔑 Hai cạnh góc vuông bằng hai cạnh góc vuông thì hai tam giác vuông bằng nhau — thực chất là c-g-c với góc xen giữa bằng 90°.<br>✗ Chỉ hai cạnh huyền bằng nhau thì chưa đủ, còn phải thêm một cạnh góc vuông hoặc một góc nhọn.<br>✗ Hai góc nhọn bằng nhau mà không có cạnh nào bằng nhau thì chỉ suy ra hai tam giác cùng hình dạng.<br>✗ Cạnh huyền cùng một cạnh góc vuông là một trường hợp KHÁC, tên là cạnh huyền - cạnh góc vuông."},{"id":"m4-26","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Trường hợp bằng nhau cạnh huyền - góc nhọn của hai tam giác vuông được phát biểu thế nào?","options":["Hai cạnh huyền bằng nhau thì hai tam giác vuông bằng nhau","Hai góc nhọn bằng nhau thì hai tam giác vuông bằng nhau","Cạnh huyền bằng nhau và góc vuông bằng nhau thì hai tam giác vuông bằng nhau","Cạnh huyền và một góc nhọn của tam giác vuông này bằng cạnh huyền và một góc nhọn của tam giác vuông kia thì hai tam giác bằng nhau"],"correct":3,"answer":"Cạnh huyền và một góc nhọn của tam giác vuông này bằng cạnh huyền và một góc nhọn của tam giác vuông kia thì hai tam giác bằng nhau","explanation":"🔑 Phải có ĐỦ hai yếu tố: cạnh huyền bằng nhau và một góc nhọn bằng nhau.<br>✗ Chỉ cạnh huyền bằng nhau thì chưa đủ, hai tam giác vuông vẫn có thể béo gầy khác nhau.<br>✗ Chỉ góc nhọn bằng nhau thì chỉ suy ra cùng hình dạng, kích thước vẫn có thể khác.<br>✗ Mọi tam giác vuông đều có góc vuông 90°, nên yếu tố góc vuông bằng nhau chẳng cho thêm thông tin gì."},{"id":"m4-27","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Hai tam giác vuông có cạnh huyền bằng nhau và một cạnh góc vuông bằng nhau thì sao?","options":["Bằng nhau, theo trường hợp cạnh huyền - cạnh góc vuông","Chưa chắc bằng nhau vì còn thiếu một cạnh góc vuông nữa","Chỉ bằng nhau khi có thêm điều kiện hai góc nhọn bằng nhau","Không bao giờ bằng nhau"],"correct":0,"answer":"Bằng nhau, theo trường hợp cạnh huyền - cạnh góc vuông","explanation":"🔑 Cạnh huyền và một cạnh góc vuông bằng nhau là một trường hợp bằng nhau riêng, chỉ có ở tam giác vuông.<br>✗ Không cần cạnh góc vuông thứ hai: khi biết cạnh huyền và một cạnh góc vuông thì cạnh còn lại đã bị xác định.<br>✗ Không cần thêm điều kiện góc nhọn nào, hai yếu tố đã cho là đủ.<br>✗ Nói không bao giờ bằng nhau là hiểu ngược hoàn toàn định lí."},{"id":"m4-28","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Trường hợp cạnh góc vuông - góc nhọn kề của tam giác vuông tương ứng với trường hợp nào của tam giác thường?","options":["c-c-c","c-g-c","g-c-g","g-g-g"],"correct":2,"answer":"g-c-g","explanation":"🔑 Cạnh góc vuông vừa kề góc vuông 90° vừa kề góc nhọn đã cho, nên nó nằm giữa hai góc — đúng trường hợp g-c-g.<br>✗ c-c-c chỉ dùng cạnh, mà trường hợp này có dùng góc nhọn.<br>✗ c-g-c cần hai cạnh, mà trường hợp này chỉ cho một cạnh góc vuông.<br>✗ g-g-g không phải trường hợp bằng nhau của tam giác."},{"id":"m4-29","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Chỉ biết hai tam giác vuông có yếu tố nào sau đây thì VẪN CHƯA kết luận được chúng bằng nhau?","options":["Hai cạnh góc vuông bằng nhau","Cạnh huyền và một góc nhọn bằng nhau","Hai góc nhọn bằng nhau","Cạnh huyền và một cạnh góc vuông bằng nhau"],"correct":2,"answer":"Hai góc nhọn bằng nhau","explanation":"🔑 Chỉ hai góc nhọn bằng nhau thì chưa đủ: không có yếu tố cạnh nào nên hai tam giác vuông vẫn có thể to nhỏ khác nhau.<br>✗ Hai cạnh góc vuông bằng nhau là một trường hợp bằng nhau hợp lệ.<br>✗ Cạnh huyền và một góc nhọn bằng nhau là một trường hợp bằng nhau hợp lệ.<br>✗ Cạnh huyền và một cạnh góc vuông bằng nhau cũng là một trường hợp bằng nhau hợp lệ."},{"id":"m4-30","ch":4,"topic":"Tam giác vuông bằng nhau","q":"△MNP vuông tại M và △XYZ vuông tại X có NP = YZ, ∠N = ∠Y. Hai tam giác bằng nhau theo trường hợp nào?","options":["Cạnh huyền - góc nhọn","Hai cạnh góc vuông","Cạnh huyền - cạnh góc vuông","Chưa đủ dữ kiện để kết luận"],"correct":0,"answer":"Cạnh huyền - góc nhọn","explanation":"🔑 NP và YZ đối diện góc vuông nên là hai cạnh huyền; thêm cặp góc nhọn ∠N = ∠Y là đủ trường hợp cạnh huyền - góc nhọn.<br>✗ Trường hợp hai cạnh góc vuông cần hai cặp cạnh góc vuông, mà đề không cho cạnh góc vuông nào.<br>✗ Cạnh huyền - cạnh góc vuông cần thêm một cặp cạnh góc vuông, còn đề cho góc chứ không cho cạnh đó.<br>✗ Dữ kiện đã đủ, vì cạnh huyền cộng một góc nhọn là một trường hợp hoàn chỉnh."},{"id":"m4-31","ch":4,"topic":"Tam giác vuông bằng nhau","q":"△ABC vuông tại A và △MNP vuông tại M có AB = MN, AC = MP. Kết luận nào đúng?","options":["Chưa kết luận được vì chưa biết cạnh huyền","Bằng nhau theo trường hợp cạnh huyền - góc nhọn","Chưa kết luận được vì chưa biết góc nhọn nào","Bằng nhau theo trường hợp hai cạnh góc vuông"],"correct":3,"answer":"Bằng nhau theo trường hợp hai cạnh góc vuông","explanation":"🔑 AB, AC và MN, MP đều là cạnh góc vuông; hai cặp bằng nhau nên hai tam giác bằng nhau theo trường hợp hai cạnh góc vuông.<br>✗ Không cần biết cạnh huyền: khi hai cạnh góc vuông đã bằng nhau thì cạnh huyền tự khắc bằng nhau.<br>✗ Cạnh huyền - góc nhọn cần cạnh huyền và góc nhọn, mà đề không cho hai yếu tố đó.<br>✗ Không cần thêm góc nhọn nào, vì góc vuông 90° đã đóng vai trò góc xen giữa."},{"id":"m4-32","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Vì sao trường hợp hai cạnh góc vuông thực chất chỉ là một dạng của c-g-c?","options":["Vì hai cạnh huyền luôn bằng nhau","Vì góc vuông 90° chính là góc xen giữa hai cạnh góc vuông","Vì hai góc nhọn của tam giác vuông luôn bằng 45°","Vì mọi tam giác vuông đều bằng nhau"],"correct":1,"answer":"Vì góc vuông 90° chính là góc xen giữa hai cạnh góc vuông","explanation":"🔑 Hai cạnh góc vuông kẹp lấy góc 90°, nên ta có đủ cạnh - góc xen giữa - cạnh, tức đúng khuôn c-g-c.<br>✗ Cạnh huyền chỉ bằng nhau SAU KHI đã chứng minh hai tam giác bằng nhau, nó là kết quả chứ không phải lí do.<br>✗ Hai góc nhọn chỉ bằng 45° khi tam giác vuông cân, không phải với mọi tam giác vuông.<br>✗ Các tam giác vuông có kích thước rất khác nhau, hoàn toàn không phải cái nào cũng bằng nhau."},{"id":"m4-33","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Tam giác PQR vuông tại P, tam giác HIK vuông tại H, biết PQ = HI và ∠Q = ∠I. Chúng bằng nhau nhờ trường hợp nào?","options":["Cạnh góc vuông - góc nhọn kề","Cạnh huyền - góc nhọn","Hai cạnh góc vuông","Cạnh huyền - cạnh góc vuông"],"correct":0,"answer":"Cạnh góc vuông - góc nhọn kề","explanation":"🔑 PQ là cạnh góc vuông và ∠Q là góc nhọn KỀ với cạnh PQ, nên hai tam giác bằng nhau theo cạnh góc vuông - góc nhọn kề.<br>✗ Cạnh huyền - góc nhọn đòi cạnh huyền QR = IK, trong khi đề cho cạnh góc vuông PQ = HI.<br>✗ Hai cạnh góc vuông cần hai cặp cạnh, còn đề chỉ cho một cặp cạnh và một cặp góc.<br>✗ Cạnh huyền - cạnh góc vuông cần cạnh huyền, mà đề bài không hề cho."},{"id":"m4-34","ch":4,"topic":"Tam giác vuông bằng nhau","q":"Trong một tam giác vuông, cạnh huyền là cạnh nào?","options":["Cạnh ngắn nhất của tam giác","Cạnh đối diện với góc vuông","Cạnh cùng với một cạnh khác tạo nên góc vuông","Cạnh đối diện với góc nhọn nhỏ nhất"],"correct":1,"answer":"Cạnh đối diện với góc vuông","explanation":"🔑 Cạnh huyền là cạnh đối diện với góc vuông; hai cạnh còn lại gọi là cạnh góc vuông.<br>✗ Cạnh huyền là cạnh DÀI NHẤT chứ không phải ngắn nhất, vì nó đối diện góc lớn nhất.<br>✗ Hai cạnh tạo nên góc vuông chính là hai cạnh góc vuông, không phải cạnh huyền.<br>✗ Cạnh đối diện góc nhọn nhỏ nhất là cạnh ngắn nhất của tam giác."},{"id":"m4-35","ch":4,"topic":"Tam giác cân","q":"△ABC cân tại A (tức AB = AC) thì hai góc nào bằng nhau?","options":["∠A = ∠B","∠A = ∠C","Cả ba góc đều bằng nhau","∠B = ∠C"],"correct":3,"answer":"∠B = ∠C","explanation":"🔑 Trong tam giác cân tại A, hai góc ở ĐÁY bằng nhau: AB = AC ⇔ ∠B = ∠C.<br>✗ ∠A là góc ở đỉnh, nói chung khác ∠B.<br>✗ ∠A cũng khác ∠C, trừ trường hợp đặc biệt là tam giác đều.<br>✗ Ba góc chỉ bằng nhau khi tam giác ĐỀU; tam giác cân chỉ chắc chắn có hai góc đáy bằng nhau."},{"id":"m4-36","ch":4,"topic":"Tam giác cân","q":"△ABC cân tại A có ∠A = 40°. Số đo mỗi góc ở đáy là bao nhiêu?","options":["40°","50°","70°","140°"],"correct":2,"answer":"70°","explanation":"🔑 Hai góc đáy bằng nhau nên ∠B = ∠C = (180° − 40°) : 2 = 70°.<br>✗ 40° là góc ở đỉnh ∠A, không phải góc đáy.<br>✗ 50° là kết quả của 90° − 40°, cách tính đó chỉ dùng cho hai góc nhọn của tam giác vuông.<br>✗ 140° mới là tổng hai góc đáy, còn thiếu bước chia đôi."},{"id":"m4-37","ch":4,"topic":"Tam giác cân","q":"△ABC có ∠B = ∠C = 55°. Kết luận nào đúng?","options":["△ABC là tam giác đều","△ABC vuông tại A","△ABC cân tại A","△ABC cân tại B"],"correct":2,"answer":"△ABC cân tại A","explanation":"🔑 Hai góc bằng nhau thì hai cạnh đối diện bằng nhau: ∠B = ∠C ⇔ AB = AC, tức tam giác cân tại A.<br>✗ Tam giác đều cần ba góc cùng bằng 60°, ở đây hai góc là 55°.<br>✗ ∠A = 180° − 110° = 70°, không phải 90° nên tam giác không vuông tại A.<br>✗ Cân tại B nghĩa là BA = BC, tương ứng với ∠A = ∠C, đề bài không cho điều đó."},{"id":"m4-38","ch":4,"topic":"Tam giác đều","q":"Mỗi góc của một tam giác đều bằng bao nhiêu độ?","options":["45°","90°","180°","60°"],"correct":3,"answer":"60°","explanation":"🔑 Tam giác đều có ba góc bằng nhau nên mỗi góc bằng 180° : 3 = 60°.<br>✗ 45° là góc nhọn của tam giác vuông cân, không phải tam giác đều.<br>✗ 90° là góc vuông; một tam giác chỉ có nhiều nhất một góc vuông nên không thể có ba góc 90°.<br>✗ 180° là tổng CẢ BA góc chứ không phải số đo của một góc."},{"id":"m4-39","ch":4,"topic":"Tam giác đều","q":"Dấu hiệu nào sau đây KHÔNG đủ để kết luận một tam giác là tam giác đều?","options":["Tam giác có ba cạnh bằng nhau","Tam giác cân có hai góc ở đáy bằng nhau","Tam giác có ba góc bằng nhau","Tam giác cân có một góc bằng 60°"],"correct":1,"answer":"Tam giác cân có hai góc ở đáy bằng nhau","explanation":"🔑 MỌI tam giác cân đều có hai góc đáy bằng nhau, nên câu này không cho thêm thông tin gì và không thể suy ra tam giác đều.<br>✗ Ba cạnh bằng nhau chính là định nghĩa của tam giác đều.<br>✗ Ba góc bằng nhau thì mỗi góc bằng 60°, đó là tam giác đều.<br>✗ Tam giác cân có một góc 60° thì cả ba góc đều bằng 60°, nên nó là tam giác đều."},{"id":"m4-40","ch":4,"topic":"Tam giác cân","q":"△ABC cân tại A có ∠B = 50°. Số đo ∠A là bao nhiêu?","options":["80°","50°","65°","130°"],"correct":0,"answer":"80°","explanation":"🔑 Cân tại A nên ∠C = ∠B = 50°, do đó ∠A = 180° − 50° − 50° = 80°.<br>✗ 50° là số đo góc đáy ∠B, không phải góc ở đỉnh.<br>✗ 65° là kết quả của (180° − 50°) : 2, công thức đó chỉ dùng khi 50° là góc ở ĐỈNH.<br>✗ 130° là 180° − 50°, tức là quên trừ đi góc đáy thứ hai."},{"id":"m4-41","ch":4,"topic":"Tam giác cân","q":"Trong tam giác cân, cạnh bên và cạnh đáy được hiểu như thế nào?","options":["Hai cạnh đáy là hai cạnh bằng nhau, cạnh bên là cạnh còn lại","Hai cạnh bên là hai cạnh bằng nhau, cạnh đáy là cạnh còn lại","Cạnh đáy luôn là cạnh dài nhất của tam giác","Cạnh đáy luôn là cạnh nằm ngang ở phía dưới"],"correct":1,"answer":"Hai cạnh bên là hai cạnh bằng nhau, cạnh đáy là cạnh còn lại","explanation":"🔑 Tam giác cân có hai CẠNH BÊN bằng nhau; cạnh thứ ba là cạnh đáy, và hai góc kề cạnh đáy chính là hai góc đáy bằng nhau.<br>✗ Nói ngược rồi: hai cạnh bằng nhau là cạnh bên, tam giác chỉ có MỘT cạnh đáy.<br>✗ Cạnh đáy có thể ngắn hơn cạnh bên, ví dụ tam giác cân có cạnh bên 5 cm và cạnh đáy 2 cm.<br>✗ Nằm ngang hay không chỉ là cách vẽ hình, không phải định nghĩa toán học."},{"id":"m4-42","ch":4,"topic":"Tam giác cân","q":"Tam giác vuông cân tại A có hai góc nhọn bằng bao nhiêu?","options":["30° và 60°","60° và 60°","45° và 45°","90° và 90°"],"correct":2,"answer":"45° và 45°","explanation":"🔑 Vuông tại A nên ∠B + ∠C = 90°, lại cân tại A nên ∠B = ∠C = 90° : 2 = 45°.<br>✗ 30° và 60° tuy có tổng 90° nhưng hai góc khác nhau, tam giác đó không cân.<br>✗ 60° và 60° cho tổng 120°, vượt quá 90° nên tam giác không thể vuông.<br>✗ Không tam giác nào có hai góc 90° bên cạnh góc vuông ∠A."},{"id":"m4-43","ch":4,"topic":"Tam giác đều","q":"Một tam giác cân có góc ở đỉnh bằng 60° thì đó là tam giác gì?","options":["Tam giác đều","Tam giác vuông cân","Tam giác tù","Tam giác cân nhưng không đều"],"correct":0,"answer":"Tam giác đều","explanation":"🔑 Hai góc đáy bằng (180° − 60°) : 2 = 60°, nên cả ba góc đều là 60° — đó chính là tam giác đều.<br>✗ Vuông cân phải có một góc 90° và hai góc 45°.<br>✗ Tam giác tù cần một góc lớn hơn 90°, ở đây góc lớn nhất chỉ là 60°.<br>✗ Ba góc bằng nhau kéo theo ba cạnh bằng nhau, nên tam giác này chắc chắn ĐỀU."},{"id":"m4-44","ch":4,"topic":"Tam giác cân","q":"Hệ thức AB = AC ⇔ ∠B = ∠C trong tam giác ABC có nghĩa là gì?","options":["Chỉ đúng một chiều: có AB = AC mới suy ra được ∠B = ∠C","Chỉ đúng một chiều: có ∠B = ∠C mới suy ra được AB = AC","Chỉ đúng khi △ABC là tam giác đều","Đúng cả hai chiều: cạnh bằng nhau suy ra góc bằng nhau và ngược lại"],"correct":3,"answer":"Đúng cả hai chiều: cạnh bằng nhau suy ra góc bằng nhau và ngược lại","explanation":"🔑 Dấu ⇔ nghĩa là tương đương hai chiều: AB = AC thì ∠B = ∠C, và ∠B = ∠C thì AB = AC.<br>✗ Nếu chỉ đúng một chiều thì phải viết ⇒, nhưng ở đây đề ghi rõ là ⇔.<br>✗ Chiều ngược lại (từ góc suy ra cạnh) cũng là một định lí đã học, không bị bỏ đi.<br>✗ Tính chất này đúng với MỌI tam giác cân, không riêng gì tam giác đều."},{"id":"m4-45","ch":4,"topic":"Đường trung trực","q":"Đường trung trực của đoạn thẳng AB là đường thẳng như thế nào?","options":["Đường thẳng đi qua trung điểm của AB","Đường thẳng vuông góc với AB","Đường thẳng song song với AB và cách đều A, B","Đường thẳng vuông góc với AB tại trung điểm của AB"],"correct":3,"answer":"Đường thẳng vuông góc với AB tại trung điểm của AB","explanation":"🔑 Đường trung trực phải thoả ĐỦ hai điều kiện: vuông góc với AB và đi qua trung điểm của AB.<br>✗ Chỉ đi qua trung điểm thì chưa đủ, còn phải vuông góc nữa.<br>✗ Chỉ vuông góc thì chưa đủ, còn phải cắt AB đúng ngay tại trung điểm.<br>✗ Đường song song với AB không bao giờ cắt AB nên không thể là trung trực của AB."},{"id":"m4-46","ch":4,"topic":"Đường trung trực","q":"Cho d là đường trung trực của đoạn thẳng AB và điểm M thuộc d. Khi đó ta có điều gì?","options":["MA = MB","MA = AB","MB = AB","MA + MB = AB"],"correct":0,"answer":"MA = MB","explanation":"🔑 Tính chất đường trung trực: M ∈ d ⇔ MA = MB, mọi điểm trên trung trực đều cách đều hai đầu mút.<br>✗ MA = AB chỉ xảy ra ở một vị trí đặc biệt nào đó, không phải tính chất chung.<br>✗ MB = AB cũng vậy, không suy ra được từ việc M thuộc trung trực.<br>✗ MA + MB = AB chỉ đúng khi M nằm GIỮA A và B trên chính đoạn AB, mà điểm duy nhất như vậy trên d là trung điểm."},{"id":"m4-47","ch":4,"topic":"Đường trung trực","q":"Điểm M cách đều hai đầu mút của đoạn thẳng AB, tức MA = MB. Kết luận nào đúng?","options":["M là trung điểm của AB","M nằm trên đoạn thẳng AB","M nằm trên đường trung trực của AB","M nằm ngoài đường trung trực của AB"],"correct":2,"answer":"M nằm trên đường trung trực của AB","explanation":"🔑 Đây là chiều ngược của tính chất trung trực: MA = MB ⇔ M thuộc đường trung trực của AB.<br>✗ M chỉ là trung điểm khi M nằm trên chính đoạn AB; nói chung M có thể ở rất xa AB.<br>✗ M không nhất thiết nằm trên đoạn AB, vì trung trực còn kéo dài về cả hai phía.<br>✗ Đây là kết luận NGƯỢC hẳn với tính chất vừa nêu."},{"id":"m4-48","ch":4,"topic":"Đường trung trực","q":"Đoạn thẳng AB dài 8 cm, đường trung trực d của AB cắt AB tại điểm I. Độ dài IA bằng bao nhiêu?","options":["8 cm","4 cm","2 cm","16 cm"],"correct":1,"answer":"4 cm","explanation":"🔑 d cắt AB tại trung điểm I nên IA = IB = 8 : 2 = 4 cm.<br>✗ 8 cm là độ dài cả đoạn AB, chưa chia đôi.<br>✗ 2 cm là kết quả của phép chia cho 4, trong khi trung điểm chỉ chia đoạn thành 2 phần.<br>✗ 16 cm là 8 × 2, nhân thay vì chia."},{"id":"m4-49","ch":4,"topic":"Đường trung trực","q":"△ABC cân tại A và M là trung điểm của BC. Đường thẳng AM có tính chất gì đối với BC?","options":["AM là đường trung trực của BC","AM song song với BC","AM đi qua trung điểm nhưng không vuông góc với BC","AM là đường trung trực của AB"],"correct":0,"answer":"AM là đường trung trực của BC","explanation":"🔑 Vì AB = AC nên A cách đều B và C, do đó A thuộc trung trực của BC; M là trung điểm BC cũng thuộc đường ấy, nên AM chính là đường trung trực của BC.<br>✗ AM cắt BC tại M nên không thể song song với BC.<br>✗ AM thực sự vuông góc với BC — điều này rút ra từ △ABM = △ACM.<br>✗ AM đi qua đầu mút A của đoạn AB nên không thể là trung trực của AB."},{"id":"m4-50","ch":4,"topic":"Đường trung trực","q":"Phát biểu nào sau đây về đường trung trực d của đoạn thẳng AB là SAI?","options":["Mọi điểm thuộc d đều cách đều A và B","Mọi điểm cách đều A và B đều nằm ngoài d","d vuông góc với AB tại trung điểm của AB","Trung điểm của AB luôn thuộc d"],"correct":1,"answer":"Mọi điểm cách đều A và B đều nằm ngoài d","explanation":"🔑 Câu sai là câu nói điểm cách đều A và B thì nằm ngoài d; thực ra mọi điểm cách đều A và B đều NẰM TRÊN d.<br>✗ Mọi điểm thuộc d cách đều A và B là chiều thuận của tính chất, hoàn toàn đúng.<br>✗ d vuông góc với AB tại trung điểm chính là định nghĩa đường trung trực.<br>✗ Trung điểm của AB là giao điểm của d với AB nên chắc chắn thuộc d."},{"id":"m5-1","ch":5,"topic":"Loại dữ liệu","q":"Chiều cao (cm) của các bạn trong lớp 7A là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính (không là số)","Không phải là dữ liệu","Vừa định lượng vừa định tính"],"correct":0,"answer":"Định lượng (là số)","explanation":"🔑 Chiều cao đo được bằng SỐ (150 cm, 152 cm…) nên là dữ liệu định lượng.<br>✗ Định tính là dữ liệu KHÔNG phải số, ví dụ màu mắt.<br>✗ Đây vẫn là dữ liệu thống kê hợp lệ vì thu thập được từ lớp học.<br>✗ Một dãy dữ liệu chỉ thuộc một loại, không thể vừa là số vừa không là số."},{"id":"m5-2","ch":5,"topic":"Loại dữ liệu","q":"Màu mắt (đen, nâu, xanh) của các bạn trong tổ 1 là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính (không là số)","Định lượng vì đếm được số bạn mỗi màu","Không phải dữ liệu thống kê"],"correct":1,"answer":"Định tính (không là số)","explanation":"🔑 Màu mắt được ghi bằng TỪ (đen, nâu, xanh), không phải số, nên là dữ liệu định tính.<br>✗ Định lượng phải là số đo hoặc số đếm của chính đối tượng.<br>✗ Đếm số bạn mỗi màu là bước xử lí về sau; bản thân màu mắt vẫn không phải số.<br>✗ Đây là dữ liệu thống kê hợp lệ, chỉ là thuộc loại định tính."},{"id":"m5-3","ch":5,"topic":"Loại dữ liệu","q":"Số áo đấu của các cầu thủ đội bóng trường (7, 10, 11, …) là loại dữ liệu nào?","options":["Định lượng, vì được viết bằng chữ số","Định lượng, vì có thể cộng chúng lại","Định tính, vì số áo chỉ dùng để phân biệt cầu thủ","Không phải dữ liệu"],"correct":2,"answer":"Định tính, vì số áo chỉ dùng để phân biệt cầu thủ","explanation":"🔑 Số áo chỉ là MÃ để phân biệt cầu thủ, cộng hay lấy trung bình đều vô nghĩa, nên là dữ liệu định tính.<br>✗ Viết bằng chữ số chưa đủ; phải mang ý nghĩa đo hoặc đếm mới là định lượng.<br>✗ Cộng số áo 7 + 10 = 17 chẳng cho ta biết điều gì cả.<br>✗ Đây vẫn là dữ liệu thu thập và ghi chép được."},{"id":"m5-4","ch":5,"topic":"Loại dữ liệu","q":"Điểm kiểm tra môn Toán của 40 bạn học sinh là loại dữ liệu nào?","options":["Định tính không thể sắp thứ tự","Định tính có thể sắp thứ tự","Không phải dữ liệu thống kê","Định lượng (là số)"],"correct":3,"answer":"Định lượng (là số)","explanation":"🔑 Điểm kiểm tra là SỐ (8; 9,5; 10…), so sánh và tính trung bình đều có nghĩa, nên là dữ liệu định lượng.<br>✗ Điểm số không phải dữ liệu định tính vì bản thân nó đã là số.<br>✗ “Có thể sắp thứ tự” là cách chia của dữ liệu định tính, không dùng cho điểm số.<br>✗ Điểm kiểm tra là dữ liệu thống kê rất quen thuộc ở trường."},{"id":"m5-5","ch":5,"topic":"Loại dữ liệu","q":"Môn học yêu thích của mỗi bạn trong lớp (Toán, Ngữ văn, Tiếng Anh, Thể dục) là loại dữ liệu nào?","options":["Định lượng, vì đếm được có bao nhiêu môn","Định tính (không là số)","Định lượng, vì mỗi môn có một mã số riêng","Vừa định lượng vừa định tính"],"correct":1,"answer":"Định tính (không là số)","explanation":"🔑 Tên môn học được ghi bằng chữ, không phải số, nên là dữ liệu định tính.<br>✗ Số lượng môn học là một dữ liệu khác; dữ liệu ta thu thập ở đây là TÊN môn.<br>✗ Nếu có gán mã số cho môn học thì mã đó chỉ để phân biệt, dữ liệu vẫn là định tính.<br>✗ Một dãy dữ liệu chỉ thuộc một trong hai loại, không thuộc cả hai."},{"id":"m5-6","ch":5,"topic":"Loại dữ liệu","q":"Nhóm máu (A, B, AB, O) của các bạn trong lớp là loại dữ liệu nào?","options":["Định lượng vì đếm được số bạn mỗi nhóm","Định lượng vì A, B là kí hiệu toán học","Không phải dữ liệu","Định tính (không là số)"],"correct":3,"answer":"Định tính (không là số)","explanation":"🔑 Nhóm máu được ghi bằng kí hiệu chữ A, B, AB, O — không phải số, nên là dữ liệu định tính.<br>✗ Đếm số bạn mỗi nhóm là việc làm sau khi đã có dữ liệu, không biến nhóm máu thành số.<br>✗ A, B ở đây chỉ là tên nhóm, không mang giá trị số nào.<br>✗ Nhóm máu là dữ liệu thống kê thường gặp trong y tế và trường học."},{"id":"m5-7","ch":5,"topic":"Loại dữ liệu","q":"Nhiệt độ trung bình (°C) của Hà Nội trong 12 tháng là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính có thể sắp thứ tự","Định tính không thể sắp thứ tự","Không phải dữ liệu thống kê"],"correct":0,"answer":"Định lượng (là số)","explanation":"🔑 Nhiệt độ được đo bằng số (17 °C; 28,5 °C…) nên là dữ liệu định lượng.<br>✗ “Có thể sắp thứ tự” chỉ dùng để chia nhỏ dữ liệu ĐỊNH TÍNH.<br>✗ Nhiệt độ không phải dữ liệu định tính vì nó là một số đo.<br>✗ Đây là dữ liệu khí tượng được thống kê hằng năm."},{"id":"m5-8","ch":5,"topic":"Loại dữ liệu","q":"Số học sinh của một trường trong các năm 2020, 2021, 2022, 2023 là loại dữ liệu nào?","options":["Định tính, vì năm học không phải là số đo","Định tính có thể sắp thứ tự","Định lượng (là số)","Không phải dữ liệu"],"correct":2,"answer":"Định lượng (là số)","explanation":"🔑 Số học sinh là số ĐẾM ĐƯỢC (800; 850; 900…) nên là dữ liệu định lượng.<br>✗ Dữ liệu ta quan tâm là SỐ HỌC SINH, còn năm chỉ là mốc thời gian đi kèm.<br>✗ Cách chia “có thể sắp thứ tự” dành riêng cho dữ liệu định tính.<br>✗ Đây là dữ liệu nhà trường thống kê vào mỗi đầu năm học."},{"id":"m5-9","ch":5,"topic":"Loại dữ liệu","q":"Mã lớp ghi trên sổ đầu bài là 71, 72, 73, 74 (ứng với 7A, 7B, 7C, 7D). Đây là loại dữ liệu nào?","options":["Định lượng, vì viết bằng chữ số","Định lượng, vì so sánh lớn bé được","Định tính, vì mã lớp chỉ thay cho tên lớp","Không phải dữ liệu"],"correct":2,"answer":"Định tính, vì mã lớp chỉ thay cho tên lớp","explanation":"🔑 Mã lớp chỉ là tên lớp viết dưới dạng số, không đo cũng không đếm điều gì, nên là dữ liệu định tính.<br>✗ Viết bằng chữ số không có nghĩa dữ liệu đó là định lượng.<br>✗ Nói lớp 74 “lớn hơn” lớp 71 là một câu vô nghĩa.<br>✗ Đây vẫn là dữ liệu được thu thập và ghi chép trong sổ."},{"id":"m5-10","ch":5,"topic":"Loại dữ liệu","q":"Cân nặng (kg) của các bạn tổ 2 khi khám sức khỏe đầu năm là loại dữ liệu nào?","options":["Định lượng (là số)","Định tính (không là số)","Định tính có thể sắp thứ tự","Không xếp được vào loại nào"],"correct":0,"answer":"Định lượng (là số)","explanation":"🔑 Cân nặng là số đo (36 kg; 41,5 kg…) nên đây là dữ liệu định lượng.<br>✗ Dữ liệu định tính không phải là số, ví dụ tên người hay màu sắc.<br>✗ Cách chia “có thể sắp thứ tự” chỉ dùng cho dữ liệu định tính.<br>✗ Mọi dữ liệu đều xếp được vào định lượng hoặc định tính."},{"id":"m5-11","ch":5,"topic":"Loại dữ liệu","q":"Tên các bạn tổ trưởng của bốn tổ trong lớp là loại dữ liệu nào?","options":["Định lượng vì có 4 bạn tổ trưởng","Định lượng vì mỗi bạn có một số thứ tự trong sổ","Không phải dữ liệu","Định tính (không là số)"],"correct":3,"answer":"Định tính (không là số)","explanation":"🔑 Tên người được ghi bằng chữ, không phải số, nên là dữ liệu định tính.<br>✗ “Có 4 bạn” là một dữ liệu khác (số lượng), không phải dữ liệu về tên.<br>✗ Số thứ tự trong sổ chỉ dùng để phân biệt, dữ liệu vẫn là định tính.<br>✗ Danh sách tên là dữ liệu được thu thập hoàn toàn hợp lệ."},{"id":"m5-12","ch":5,"topic":"Loại dữ liệu","q":"Xếp loại học lực (Tốt, Khá, Đạt, Chưa đạt) của học sinh lớp 7B là loại dữ liệu nào?","options":["Định lượng, vì tương ứng với điểm số","Định tính (không là số)","Không phải dữ liệu thống kê","Định lượng, vì so sánh hơn kém được"],"correct":1,"answer":"Định tính (không là số)","explanation":"🔑 Xếp loại được ghi bằng chữ (Tốt, Khá, Đạt…) nên là dữ liệu định tính, dù nó sắp thứ tự được.<br>✗ Điểm số là dữ liệu khác; xếp loại chỉ là nhãn bằng chữ.<br>✗ Đây là dữ liệu nhà trường thống kê vào cuối mỗi học kì.<br>✗ So sánh hơn kém được không có nghĩa là số: Tốt hơn Khá, nhưng “Tốt” vẫn là chữ."},{"id":"m5-13","ch":5,"topic":"Loại dữ liệu","q":"Số điện thoại của phụ huynh ghi trong sổ liên lạc là loại dữ liệu nào?","options":["Định lượng, vì gồm toàn chữ số","Định lượng, vì tính trung bình được","Không phải dữ liệu","Định tính, vì số điện thoại chỉ để liên lạc, không đo đếm gì"],"correct":3,"answer":"Định tính, vì số điện thoại chỉ để liên lạc, không đo đếm gì","explanation":"🔑 Số điện thoại là một dãy kí hiệu dùng để liên lạc, cộng trừ đều vô nghĩa, nên là dữ liệu định tính.<br>✗ Gồm chữ số nhưng không mang ý nghĩa đo hay đếm thì không phải định lượng.<br>✗ Trung bình cộng của các số điện thoại chẳng nói lên điều gì.<br>✗ Đây vẫn là dữ liệu được ghi chép trong hồ sơ của lớp."},{"id":"m5-14","ch":5,"topic":"Loại dữ liệu","q":"Số anh chị em ruột của mỗi bạn trong lớp (0; 1; 2; 3) là loại dữ liệu nào?","options":["Định tính, vì chỉ có vài giá trị","Định tính có thể sắp thứ tự","Định lượng (là số)","Không phải dữ liệu"],"correct":2,"answer":"Định lượng (là số)","explanation":"🔑 Đây là số ĐẾM thật sự (một bạn có 2 anh chị em), cộng và tính trung bình đều có nghĩa, nên là định lượng.<br>✗ Ít giá trị không làm cho dữ liệu trở thành định tính.<br>✗ Nhóm “có thể sắp thứ tự” chỉ dùng cho dữ liệu định tính như xếp loại học lực.<br>✗ Đây là dữ liệu khảo sát rất thường gặp trong lớp."},{"id":"m5-15","ch":5,"topic":"Loại dữ liệu","q":"Dữ liệu ĐỊNH LƯỢNG là dữ liệu như thế nào?","options":["Là dữ liệu được ghi bằng chữ","Là dữ liệu ở dạng SỐ (số liệu)","Là dữ liệu sắp thứ tự được","Là dữ liệu vẽ được biểu đồ"],"correct":1,"answer":"Là dữ liệu ở dạng SỐ (số liệu)","explanation":"🔑 Dữ liệu ĐỊNH LƯỢNG là dữ liệu ở dạng SỐ, còn được gọi là số liệu.<br>✗ Dữ liệu ghi bằng chữ chính là dữ liệu định tính.<br>✗ Sắp thứ tự được là cách chia nhỏ của dữ liệu định tính.<br>✗ Loại dữ liệu nào cũng vẽ được biểu đồ nên đó không phải dấu hiệu nhận biết."},{"id":"m5-16","ch":5,"topic":"Loại dữ liệu","q":"Trong bốn dữ liệu sau, dữ liệu nào là ĐỊNH TÍNH: chiều cao, cân nặng, màu áo đồng phục, điểm Toán?","options":["Màu áo đồng phục","Chiều cao","Cân nặng","Điểm Toán"],"correct":0,"answer":"Màu áo đồng phục","explanation":"🔑 Màu áo được ghi bằng chữ (trắng, xanh…) nên là dữ liệu định tính; ba dữ liệu còn lại đều là số.<br>✗ Chiều cao đo bằng xăng-ti-mét nên là định lượng.<br>✗ Cân nặng đo bằng ki-lô-gam nên là định lượng.<br>✗ Điểm Toán là số từ 0 đến 10 nên là định lượng."},{"id":"m5-17","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Xếp loại học lực Giỏi, Khá, Trung bình, Yếu thuộc nhóm dữ liệu định tính nào?","options":["Không thể sắp thứ tự","Có thể sắp thứ tự","Vừa sắp thứ tự được vừa không","Không thuộc nhóm nào vì ghi bằng chữ"],"correct":1,"answer":"Có thể sắp thứ tự","explanation":"🔑 Giỏi cao hơn Khá, Khá cao hơn Trung bình, Trung bình cao hơn Yếu — có thứ tự rõ ràng nên đây là dữ liệu định tính CÓ THỂ sắp thứ tự.<br>✗ Nhóm “không thể sắp thứ tự” dành cho các nhãn ngang hàng như màu mắt, nhóm máu.<br>✗ Mỗi dữ liệu chỉ thuộc một trong hai nhóm, không thuộc cả hai.<br>✗ Dữ liệu ghi bằng chữ vẫn được chia thành hai nhóm này."},{"id":"m5-18","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Màu mắt của học sinh (đen, nâu, xanh) thuộc nhóm dữ liệu định tính nào?","options":["Có thể sắp thứ tự vì xếp được theo bảng chữ cái","Có thể sắp thứ tự vì các màu đậm nhạt khác nhau","Không thể sắp thứ tự","Không phải dữ liệu định tính"],"correct":2,"answer":"Không thể sắp thứ tự","explanation":"🔑 Các màu mắt là những nhãn NGANG HÀNG, không màu nào hơn màu nào, nên đây là dữ liệu không thể sắp thứ tự.<br>✗ Xếp theo bảng chữ cái chỉ là cách viết danh sách cho dễ tra, không phải thứ tự hơn kém.<br>✗ Đậm nhạt không phải tiêu chí phân loại của dữ liệu màu mắt.<br>✗ Màu mắt ghi bằng chữ nên chắc chắn là dữ liệu định tính."},{"id":"m5-19","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Nhóm máu A, B, AB, O thuộc nhóm dữ liệu định tính nào?","options":["Không thể sắp thứ tự","Có thể sắp thứ tự vì A đứng trước B","Có thể sắp thứ tự vì nhóm O hiếm nhất","Là dữ liệu định lượng"],"correct":0,"answer":"Không thể sắp thứ tự","explanation":"🔑 Bốn nhóm máu ngang hàng nhau, không nhóm nào lớn hơn nhóm nào, nên không thể sắp thứ tự.<br>✗ A đứng trước B chỉ là thói quen viết, không phải thứ hạng cao thấp.<br>✗ Độ hiếm là một thông tin khác, không tạo ra thứ tự cho dữ liệu nhóm máu.<br>✗ Nhóm máu ghi bằng kí hiệu chữ nên là dữ liệu định tính."},{"id":"m5-20","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Mức độ hài lòng với bữa ăn bán trú: Rất hài lòng, Hài lòng, Bình thường, Không hài lòng. Đây là dữ liệu gì?","options":["Định lượng vì có đúng 4 mức","Định tính không thể sắp thứ tự","Định lượng vì chấm điểm được","Định tính có thể sắp thứ tự"],"correct":3,"answer":"Định tính có thể sắp thứ tự","explanation":"🔑 Bốn mức này giảm dần từ Rất hài lòng đến Không hài lòng nên là dữ liệu định tính CÓ THỂ sắp thứ tự.<br>✗ Có 4 mức chỉ là số lựa chọn của phiếu hỏi, câu trả lời vẫn là chữ.<br>✗ Chúng có thứ tự rất rõ nên không thuộc nhóm “không thể sắp thứ tự”.<br>✗ Nếu ta tự gán điểm 1 đến 4 thì đó là mã do ta đặt, dữ liệu gốc vẫn là chữ."},{"id":"m5-21","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Môn thể thao yêu thích (bóng đá, cầu lông, bơi, cờ vua) thuộc nhóm nào?","options":["Định tính có thể sắp thứ tự","Định lượng","Định tính không thể sắp thứ tự","Không phải dữ liệu"],"correct":2,"answer":"Định tính không thể sắp thứ tự","explanation":"🔑 Bốn môn thể thao là các nhãn ngang hàng, không môn nào xếp trên môn nào, nên không thể sắp thứ tự.<br>✗ Muốn sắp thứ tự thì các giá trị phải hơn kém nhau như Giỏi – Khá – Trung bình.<br>✗ Tên môn thể thao là chữ nên không phải dữ liệu định lượng.<br>✗ Đây là dữ liệu khảo sát sở thích rất phổ biến trong lớp."},{"id":"m5-22","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Cỡ áo đồng phục S, M, L, XL thuộc nhóm dữ liệu định tính nào?","options":["Không thể sắp thứ tự","Có thể sắp thứ tự","Là dữ liệu định lượng vì đo bằng xăng-ti-mét","Không phải dữ liệu"],"correct":1,"answer":"Có thể sắp thứ tự","explanation":"🔑 S nhỏ hơn M, M nhỏ hơn L, L nhỏ hơn XL — tăng dần theo độ rộng nên đây là dữ liệu định tính CÓ THỂ sắp thứ tự.<br>✗ Chúng hơn kém nhau rõ ràng nên không thuộc nhóm “không thể sắp thứ tự”.<br>✗ Số đo áo bằng xăng-ti-mét là dữ liệu khác; ở đây ta chỉ ghi chữ S, M, L, XL.<br>✗ Cỡ áo là dữ liệu nhà trường thu thập để đặt may đồng phục."},{"id":"m5-23","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Quê quán của các bạn trong lớp (Hà Nội, Nam Định, Nghệ An, …) thuộc nhóm nào?","options":["Định lượng","Định tính có thể sắp thứ tự theo dân số","Định tính có thể sắp thứ tự theo bảng chữ cái","Định tính không thể sắp thứ tự"],"correct":3,"answer":"Định tính không thể sắp thứ tự","explanation":"🔑 Tên các tỉnh là những nhãn ngang hàng, không tỉnh nào hơn tỉnh nào, nên không thể sắp thứ tự.<br>✗ Tên tỉnh ghi bằng chữ nên không phải dữ liệu định lượng.<br>✗ Dân số là một dữ liệu khác, nó không tạo thứ tự cho dữ liệu quê quán.<br>✗ Sắp theo bảng chữ cái chỉ giúp dễ tra cứu, không phải thứ tự hơn kém."},{"id":"m5-24","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Loại huy chương đạt được trong Hội khỏe Phù Đổng: Vàng, Bạc, Đồng. Đây là dữ liệu gì?","options":["Định tính có thể sắp thứ tự","Định tính không thể sắp thứ tự","Định lượng vì đếm được số huy chương","Không phải dữ liệu"],"correct":0,"answer":"Định tính có thể sắp thứ tự","explanation":"🔑 Vàng cao hơn Bạc, Bạc cao hơn Đồng nên đây là dữ liệu định tính CÓ THỂ sắp thứ tự.<br>✗ Ba loại huy chương có thứ hạng rõ ràng nên không thuộc nhóm không sắp thứ tự được.<br>✗ Số huy chương là dữ liệu khác; ở đây ta ghi LOẠI huy chương bằng chữ.<br>✗ Đây là dữ liệu được nhà trường thống kê sau mỗi hội thi."},{"id":"m5-25","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Dữ liệu không phải là số (định tính) được chia thành mấy loại, là những loại nào?","options":["Hai loại: có thể sắp thứ tự và không thể sắp thứ tự","Hai loại: định lượng và định tính","Ba loại: chữ, số và kí hiệu","Không chia được thành loại nào"],"correct":0,"answer":"Hai loại: có thể sắp thứ tự và không thể sắp thứ tự","explanation":"🔑 Dữ liệu định tính được chia thành hai loại: loại CÓ THỂ sắp thứ tự và loại KHÔNG THỂ sắp thứ tự.<br>✗ Định lượng và định tính là cách chia dữ liệu nói chung, không phải chia riêng dữ liệu định tính.<br>✗ Bài học không có cách chia theo chữ – số – kí hiệu.<br>✗ Dữ liệu định tính luôn xếp được vào một trong hai loại nói trên."},{"id":"m5-26","ch":5,"topic":"Sắp thứ tự dữ liệu","q":"Dữ liệu nào sau đây CÓ THỂ sắp thứ tự: nhóm máu; màu tóc; tên món ăn yêu thích; mức độ chăm đọc sách (Hằng ngày – Hằng tuần – Hiếm khi – Không bao giờ)?","options":["Nhóm máu","Màu tóc","Tên món ăn yêu thích","Mức độ chăm đọc sách"],"correct":3,"answer":"Mức độ chăm đọc sách","explanation":"🔑 Hằng ngày nhiều hơn Hằng tuần, Hằng tuần nhiều hơn Hiếm khi, Hiếm khi nhiều hơn Không bao giờ — giảm dần theo mức độ nên sắp thứ tự được.<br>✗ Bốn nhóm máu ngang hàng nhau, không có thứ hạng.<br>✗ Các màu tóc chỉ khác nhau chứ không màu nào hơn màu nào.<br>✗ Tên các món ăn là những nhãn ngang hàng, không sắp thứ tự được."},{"id":"m5-27","ch":5,"topic":"Chọn biểu đồ","q":"Muốn biểu diễn TỈ LỆ PHẦN TRĂM học sinh lớp 7A thích từng môn học, nên dùng biểu đồ nào?","options":["Biểu đồ đoạn thẳng","Biểu đồ đoạn thẳng đi lên","Không cần biểu đồ, chỉ cần bảng số liệu","Biểu đồ hình quạt tròn"],"correct":3,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Biểu đồ hình quạt tròn dùng để biểu diễn TỈ LỆ PHẦN TRĂM của từng thành phần so với toàn thể.<br>✗ Biểu đồ đoạn thẳng dùng cho sự thay đổi theo thời gian, không dùng cho tỉ lệ.<br>✗ Hình dạng đi lên hay đi xuống chỉ có ý nghĩa với dữ liệu theo thời gian.<br>✗ Đề yêu cầu biểu diễn bằng biểu đồ để nhìn tỉ lệ cho trực quan."},{"id":"m5-28","ch":5,"topic":"Chọn biểu đồ","q":"Muốn biểu diễn nhiệt độ trung bình của Đà Nẵng trong 12 tháng của năm, nên dùng biểu đồ nào?","options":["Biểu đồ đoạn thẳng","Biểu đồ hình quạt tròn","Biểu đồ hình quạt tròn chia 12 phần bằng nhau","Không biểu diễn được bằng biểu đồ"],"correct":0,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Nhiệt độ thay đổi THEO THỜI GIAN (qua 12 tháng) nên phải dùng biểu đồ đoạn thẳng.<br>✗ Biểu đồ quạt tròn chỉ dùng cho tỉ lệ phần trăm các phần của một tổng thể.<br>✗ Cộng nhiệt độ 12 tháng lại rồi chia phần trăm là việc vô nghĩa.<br>✗ Đây là dữ liệu theo thời gian, rất thích hợp để vẽ biểu đồ."},{"id":"m5-29","ch":5,"topic":"Chọn biểu đồ","q":"Số học sinh của trường qua các năm 2019, 2020, 2021, 2022, 2023 nên được biểu diễn bằng biểu đồ nào?","options":["Biểu đồ hình quạt tròn","Biểu đồ đoạn thẳng","Biểu đồ hình quạt tròn chia 5 phần","Không dùng biểu đồ nào cả"],"correct":1,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Dữ liệu gắn với các mốc THỜI GIAN (năm) và ta muốn thấy sự thay đổi nên dùng biểu đồ đoạn thẳng.<br>✗ Quạt tròn dùng để so sánh tỉ lệ các phần trong cùng một tổng thể, không dùng cho các năm.<br>✗ Số học sinh của các năm không phải là các phần của một tổng thể 100%.<br>✗ Biểu đồ giúp nhìn ngay ra xu hướng tăng hay giảm nên rất cần thiết."},{"id":"m5-30","ch":5,"topic":"Chọn biểu đồ","q":"Rác thải của trường gồm: rác hữu cơ 50%, giấy 30%, nhựa 20%. Nên dùng biểu đồ nào để biểu diễn?","options":["Biểu đồ đoạn thẳng","Biểu đồ đoạn thẳng gồm 3 điểm","Biểu đồ hình quạt tròn","Không loại biểu đồ nào phù hợp"],"correct":2,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Số liệu đã cho ở dạng phần trăm các phần của một tổng thể (50% + 30% + 20% = 100%) nên dùng biểu đồ quạt tròn.<br>✗ Biểu đồ đoạn thẳng dành cho dữ liệu thay đổi theo thời gian.<br>✗ Ba loại rác không phải ba mốc thời gian nên nối chúng bằng đoạn thẳng là vô nghĩa.<br>✗ Đây chính là trường hợp điển hình của biểu đồ hình quạt tròn."},{"id":"m5-31","ch":5,"topic":"Chọn biểu đồ","q":"Biểu đồ hình quạt tròn dùng để biểu diễn điều gì?","options":["Tỉ lệ phần trăm của từng thành phần so với toàn thể","Sự thay đổi của một đại lượng theo thời gian","Số lớn nhất trong dãy số liệu","Thứ tự xuất hiện của các dữ liệu"],"correct":0,"answer":"Tỉ lệ phần trăm của từng thành phần so với toàn thể","explanation":"🔑 Biểu đồ hình quạt tròn biểu diễn TỈ LỆ PHẦN TRĂM của từng thành phần so với toàn thể, tổng luôn là 100%.<br>✗ Biểu diễn sự thay đổi theo thời gian là nhiệm vụ của biểu đồ đoạn thẳng.<br>✗ Tìm số lớn nhất chỉ là một việc đọc dữ liệu, không phải mục đích của biểu đồ này.<br>✗ Biểu đồ quạt tròn không thể hiện thứ tự xuất hiện của dữ liệu."},{"id":"m5-32","ch":5,"topic":"Chọn biểu đồ","q":"Biểu đồ đoạn thẳng dùng để biểu diễn điều gì?","options":["Tỉ lệ phần trăm các phần của một tổng thể","Số lượng học sinh thuộc mỗi nhóm máu","Sự thay đổi của một đại lượng theo thời gian","Loại của dữ liệu là định tính hay định lượng"],"correct":2,"answer":"Sự thay đổi của một đại lượng theo thời gian","explanation":"🔑 Biểu đồ đoạn thẳng biểu diễn SỰ THAY ĐỔI của một đại lượng THEO THỜI GIAN.<br>✗ Biểu diễn tỉ lệ phần trăm các phần là việc của biểu đồ hình quạt tròn.<br>✗ Nhóm máu không phải mốc thời gian nên không hợp với biểu đồ đoạn thẳng.<br>✗ Biểu đồ không dùng để phân loại dữ liệu là định tính hay định lượng."},{"id":"m5-33","ch":5,"topic":"Chọn biểu đồ","q":"Bạn Mai ghi lại cân nặng của mình vào ngày đầu mỗi tháng trong suốt một năm. Nên vẽ biểu đồ nào?","options":["Biểu đồ quạt tròn với 12 phần","Biểu đồ quạt tròn chia theo phần trăm cân nặng","Không cần biểu đồ vì chỉ theo dõi một người","Biểu đồ đoạn thẳng"],"correct":3,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Cân nặng của Mai thay đổi qua các tháng, đây là đại lượng theo thời gian nên dùng biểu đồ đoạn thẳng.<br>✗ Mười hai lần cân không phải là 12 phần của một tổng thể.<br>✗ Lấy cân nặng một tháng chia cho tổng cả năm rồi tính phần trăm là vô nghĩa.<br>✗ Dù chỉ theo dõi một người, biểu đồ vẫn giúp thấy rõ tăng hay giảm."},{"id":"m5-34","ch":5,"topic":"Chọn biểu đồ","q":"Khảo sát 200 học sinh về phương tiện đi học và muốn thấy mỗi phương tiện chiếm bao nhiêu phần trăm. Nên dùng biểu đồ nào?","options":["Biểu đồ đoạn thẳng","Biểu đồ hình quạt tròn","Biểu đồ đoạn thẳng vẽ theo từng lớp","Không dùng biểu đồ vì dữ liệu là định tính"],"correct":1,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Ta cần thấy PHẦN TRĂM của từng phương tiện trong tổng số 200 học sinh nên dùng biểu đồ hình quạt tròn.<br>✗ Biểu đồ đoạn thẳng chỉ hợp khi dữ liệu thay đổi theo thời gian.<br>✗ Các lớp không phải mốc thời gian nên nối bằng đoạn thẳng là không hợp lí.<br>✗ Dữ liệu định tính vẫn vẽ được biểu đồ sau khi đếm và tính phần trăm."},{"id":"m5-35","ch":5,"topic":"Chọn biểu đồ","q":"Bạn Nam vẽ biểu đồ hình quạt tròn để biểu diễn nhiệt độ trung bình 12 tháng ở Huế. Nhận xét nào đúng?","options":["Nam làm đúng vì đã có đủ 12 số liệu","Nam làm sai vì quạt tròn chỉ dùng cho tỉ lệ phần trăm của một tổng thể","Nam làm đúng vì hình tròn đẹp và dễ nhìn","Nam làm sai vì biểu đồ quạt tròn nhiều nhất chỉ vẽ được 4 phần"],"correct":1,"answer":"Nam làm sai vì quạt tròn chỉ dùng cho tỉ lệ phần trăm của một tổng thể","explanation":"🔑 Nhiệt độ 12 tháng là đại lượng thay đổi theo thời gian nên phải dùng biểu đồ đoạn thẳng, không dùng quạt tròn.<br>✗ Có đủ số liệu vẫn chưa đủ, còn phải chọn đúng loại biểu đồ theo mục đích.<br>✗ Đẹp và dễ nhìn không phải căn cứ để chọn loại biểu đồ.<br>✗ Biểu đồ quạt tròn không bị giới hạn 4 phần; chỗ sai là ở mục đích sử dụng."},{"id":"m5-36","ch":5,"topic":"Chọn biểu đồ","q":"Bạn Lan dùng biểu đồ đoạn thẳng để biểu diễn tỉ lệ các loại sách trong thư viện (Truyện 45%, Khoa học 35%, Từ điển 20%). Nhận xét nào đúng?","options":["Lan làm đúng vì đã có đủ ba số liệu","Lan làm đúng vì tổng ba tỉ lệ bằng 100%","Lan làm sai vì tổng ba tỉ lệ chưa bằng 100%","Lan làm sai vì đây là tỉ lệ các phần của một tổng thể, phải dùng biểu đồ quạt tròn"],"correct":3,"answer":"Lan làm sai vì đây là tỉ lệ các phần của một tổng thể, phải dùng biểu đồ quạt tròn","explanation":"🔑 Ba loại sách là ba THÀNH PHẦN của một tổng thể chứ không phải các mốc thời gian, nên phải dùng biểu đồ hình quạt tròn.<br>✗ Có đủ số liệu không có nghĩa là đã chọn đúng loại biểu đồ.<br>✗ Tổng đúng bằng 100% thật, nhưng loại biểu đồ vẫn chọn sai.<br>✗ 45% + 35% + 20% = 100% nên số liệu không hề thiếu."},{"id":"m5-37","ch":5,"topic":"Chọn biểu đồ","q":"Số lượt khách đến tham quan bảo tàng trong các tháng 1, 2, 3, 4, 5 nên biểu diễn bằng biểu đồ nào?","options":["Biểu đồ quạt tròn vì có 5 phần","Biểu đồ quạt tròn để biết tháng nào đông nhất","Biểu đồ đoạn thẳng","Không biểu diễn được vì số lượt khách quá lớn"],"correct":2,"answer":"Biểu đồ đoạn thẳng","explanation":"🔑 Dữ liệu gắn với các THÁNG liên tiếp và ta muốn thấy lượng khách tăng hay giảm nên dùng biểu đồ đoạn thẳng.<br>✗ Năm tháng không phải là năm phần của cùng một tổng thể.<br>✗ Muốn so sánh theo thời gian thì biểu đồ đoạn thẳng cho thấy rõ hơn nhiều.<br>✗ Số lớn đến đâu vẫn vẽ được bằng cách chọn đơn vị thích hợp trên trục."},{"id":"m5-38","ch":5,"topic":"Chọn biểu đồ","q":"Ở lớp 7C, nhóm máu O chiếm 40%, nhóm A 30%, nhóm B 20%, nhóm AB 10%. Loại biểu đồ nào phù hợp nhất?","options":["Biểu đồ hình quạt tròn","Biểu đồ đoạn thẳng nối bốn nhóm máu","Biểu đồ đoạn thẳng theo thời gian","Cả hai loại biểu đồ đều không phù hợp"],"correct":0,"answer":"Biểu đồ hình quạt tròn","explanation":"🔑 Bốn nhóm máu là bốn thành phần của tổng thể cả lớp và số liệu đã ở dạng phần trăm nên dùng biểu đồ hình quạt tròn.<br>✗ Nối bốn nhóm máu bằng đoạn thẳng là vô nghĩa vì chúng không thay đổi theo thời gian.<br>✗ Trong bài toán này không hề có mốc thời gian nào.<br>✗ Biểu đồ quạt tròn hoàn toàn phù hợp với dữ liệu đã cho."},{"id":"m5-39","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Biểu đồ quạt tròn về môn học yêu thích của lớp 7A cho biết: Toán 40%, Ngữ văn 25%, Tiếng Anh 20%, phần còn lại là Thể dục. Thể dục chiếm bao nhiêu phần trăm?","options":["10%","15%","20%","85%"],"correct":1,"answer":"15%","explanation":"🔑 Tổng các phần của biểu đồ quạt tròn luôn là 100%, nên Thể dục = 100% − (40% + 25% + 20%) = 15%.<br>✗ Nếu là 10% thì tổng chỉ được 95%, còn thiếu 5%.<br>✗ Nếu là 20% thì tổng thành 105%, vượt quá toàn thể.<br>✗ 85% là tổng của ba môn đã cho, không phải phần còn lại."},{"id":"m5-40","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Tổng các tỉ lệ phần trăm trong một biểu đồ hình quạt tròn luôn bằng bao nhiêu?","options":["100%","Bằng số phần của biểu đồ","Bằng 360% vì hình tròn có 360°","Tùy từng biểu đồ, không cố định"],"correct":0,"answer":"100%","explanation":"🔑 Các phần của biểu đồ quạt tròn hợp lại thành toàn thể nên tổng của chúng luôn bằng 100%.<br>✗ Số phần chỉ cho biết biểu đồ chia làm mấy miếng, không liên quan đến tổng phần trăm.<br>✗ Hình tròn có 360° nhưng tỉ lệ vẫn luôn được tính theo 100%.<br>✗ Đây là quy tắc cố định, không thay đổi theo từng biểu đồ."},{"id":"m5-41","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Lớp 7B có 40 học sinh. Biểu đồ quạt tròn cho biết 25% số học sinh đi học bằng xe buýt. Có bao nhiêu bạn đi xe buýt?","options":["4 bạn","25 bạn","10 bạn","15 bạn"],"correct":2,"answer":"10 bạn","explanation":"🔑 Lấy tổng số nhân với tỉ lệ: 40 × 25 : 100 = 10 (bạn).<br>✗ 4 bạn là kết quả của phép chia 40 : 10, không phải phép tính phần trăm.<br>✗ 25 là con số phần trăm chứ không phải số học sinh.<br>✗ 15 bạn ứng với 37,5%, không khớp với số liệu của đề."},{"id":"m5-42","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Một biểu đồ quạt tròn ghi ba phần lần lượt là 30%, 40% và 20%. Vì sao biểu đồ này chắc chắn có sai sót?","options":["Vì biểu đồ quạt tròn phải có ít nhất 4 phần","Vì tổng mới được 90%, còn thiếu 10% mới đủ toàn thể","Vì các phần phải có tỉ lệ bằng nhau","Vì biểu đồ không ghi rõ số học sinh"],"correct":1,"answer":"Vì tổng mới được 90%, còn thiếu 10% mới đủ toàn thể","explanation":"🔑 Tổng các phần của biểu đồ quạt tròn phải bằng 100%, mà 30% + 40% + 20% = 90% nên còn thiếu 10%.<br>✗ Biểu đồ quạt tròn có thể chỉ gồm 2 hoặc 3 phần, không bắt buộc phải có 4 phần.<br>✗ Các phần được phép to nhỏ khác nhau, đó chính là điều biểu đồ muốn cho thấy.<br>✗ Biểu đồ quạt tròn có thể chỉ ghi phần trăm mà không ghi số lượng."},{"id":"m5-43","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Biểu đồ đoạn thẳng về nhiệt độ trung bình (°C) cho biết: tháng 1: 17; tháng 2: 19; tháng 3: 22; tháng 4: 27. Tháng nào có nhiệt độ cao nhất?","options":["Tháng 1","Tháng 2","Tháng 3","Tháng 4"],"correct":3,"answer":"Tháng 4","explanation":"🔑 So sánh bốn số liệu: 17 &lt; 19 &lt; 22 &lt; 27, số lớn nhất là 27 nên tháng 4 có nhiệt độ cao nhất.<br>✗ Tháng 1 chỉ có 17 °C, đây là điểm thấp nhất của biểu đồ.<br>✗ Tháng 2 có 19 °C, vẫn thấp hơn tháng 3 và tháng 4.<br>✗ Tháng 3 có 22 °C, chưa phải là cao nhất."},{"id":"m5-44","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Trên biểu đồ đoạn thẳng, đoạn nối hai điểm liên tiếp đi XUỐNG cho ta biết điều gì?","options":["Đại lượng đó tăng lên","Đại lượng đó không thay đổi","Đại lượng đó giảm đi so với thời điểm trước","Số liệu đã bị ghi sai"],"correct":2,"answer":"Đại lượng đó giảm đi so với thời điểm trước","explanation":"🔑 Đoạn thẳng đi xuống nghĩa là giá trị ở thời điểm sau NHỎ HƠN thời điểm trước, tức là đại lượng giảm.<br>✗ Đoạn đi lên mới thể hiện đại lượng tăng.<br>✗ Đại lượng không đổi thì đoạn thẳng nằm ngang.<br>✗ Đi xuống là chuyện hoàn toàn bình thường, không phải lỗi ghi số liệu."},{"id":"m5-45","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Số học sinh giỏi của một lớp: năm 2020 là 20; năm 2021 là 25; năm 2022 là 35; năm 2023 là 30. Năm nào số học sinh giỏi GIẢM so với năm liền trước?","options":["Năm 2023","Năm 2021","Năm 2022","Không năm nào giảm"],"correct":0,"answer":"Năm 2023","explanation":"🔑 Năm 2023 có 30 bạn, ít hơn 35 bạn của năm 2022, nên 2023 là năm giảm (giảm 5 bạn).<br>✗ Năm 2021 có 25 bạn, nhiều hơn 20 bạn của năm 2020 nên là tăng.<br>✗ Năm 2022 có 35 bạn, nhiều hơn 25 bạn của năm 2021 nên cũng tăng.<br>✗ Có một năm giảm, đó chính là năm 2023."},{"id":"m5-46","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Biểu đồ quạt tròn về cách đi học của lớp 7D: xe đạp 45%, đi bộ 30%, xe buýt 15%, bố mẹ đưa 10%. Phần lớn nhất của biểu đồ ứng với cách đi học nào?","options":["Đi bộ","Xe đạp","Xe buýt","Bố mẹ đưa"],"correct":1,"answer":"Xe đạp","explanation":"🔑 Phần lớn nhất của biểu đồ ứng với tỉ lệ lớn nhất, mà 45% là của xe đạp.<br>✗ Đi bộ chiếm 30%, chỉ đứng thứ hai.<br>✗ Xe buýt chiếm 15%, là phần nhỏ thứ ba.<br>✗ Bố mẹ đưa chiếm 10%, là phần nhỏ nhất."},{"id":"m5-47","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Trong một biểu đồ hình quạt tròn, một phần chiếm đúng NỬA hình tròn. Phần đó ứng với bao nhiêu phần trăm?","options":["25%","40%","50%","100%"],"correct":2,"answer":"50%","explanation":"🔑 Cả hình tròn ứng với 100%, nên một nửa hình tròn ứng với 100% : 2 = 50%.<br>✗ 25% ứng với một phần tư hình tròn.<br>✗ 40% nhỏ hơn một nửa nên không phải nửa hình tròn.<br>✗ 100% là toàn bộ hình tròn chứ không phải một nửa."},{"id":"m5-48","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Biểu đồ đoạn thẳng cho biết số cây trường trồng được: năm 2021 là 120 cây; năm 2022 là 150 cây. Số cây năm 2022 thay đổi thế nào so với năm 2021?","options":["Giảm 30 cây","Tăng 150 cây","Tăng 120 cây","Tăng 30 cây"],"correct":3,"answer":"Tăng 30 cây","explanation":"🔑 Lấy số sau trừ số trước: 150 − 120 = 30, và vì 150 > 120 nên đây là tăng 30 cây.<br>✗ Đoạn thẳng đi lên nên là tăng chứ không phải giảm.<br>✗ 150 là số cây của năm 2022, không phải mức tăng.<br>✗ 120 là số cây của năm 2021, cũng không phải mức tăng."},{"id":"m5-49","ch":5,"topic":"Đọc biểu đồ quạt tròn","q":"Biểu đồ quạt tròn của lớp 7A cho biết 20% học sinh thích môn Tin học nhưng không ghi sĩ số lớp. Từ biểu đồ này ta kết luận được gì?","options":["Có đúng 20 bạn thích môn Tin học","Cứ 100 bạn thì có 20 bạn thích Tin học; muốn biết số bạn cụ thể phải biết sĩ số lớp","Không kết luận được điều gì từ biểu đồ này","Tin học là môn được thích nhất lớp"],"correct":1,"answer":"Cứ 100 bạn thì có 20 bạn thích Tin học; muốn biết số bạn cụ thể phải biết sĩ số lớp","explanation":"🔑 Biểu đồ quạt tròn chỉ cho biết TỈ LỆ; muốn ra số học sinh cụ thể phải nhân tỉ lệ đó với sĩ số lớp.<br>✗ 20% không có nghĩa là 20 bạn: nếu lớp có 40 bạn thì chỉ là 8 bạn.<br>✗ Ta vẫn kết luận được về tỉ lệ, chỉ là chưa biết số lượng cụ thể.<br>✗ Muốn biết môn nào được thích nhất còn phải so với tỉ lệ của các môn khác."},{"id":"m5-50","ch":5,"topic":"Đọc biểu đồ đoạn thẳng","q":"Số lượt bạn đọc mượn sách ở thư viện: tháng 9: 120; tháng 10: 150; tháng 11: 180; tháng 12: 210. Nhận xét nào đúng về biểu đồ đoạn thẳng của dãy số liệu này?","options":["Đường biểu diễn đi lên đều, số lượt mượn tăng dần qua các tháng","Đường biểu diễn đi xuống, số lượt mượn giảm dần","Đường biểu diễn nằm ngang vì tháng nào cũng có bạn mượn sách","Phải dùng biểu đồ quạt tròn mới thấy được xu hướng"],"correct":0,"answer":"Đường biểu diễn đi lên đều, số lượt mượn tăng dần qua các tháng","explanation":"🔑 120 &lt; 150 &lt; 180 &lt; 210, số liệu tăng dần nên đường gấp khúc đi lên đều (mỗi tháng tăng 30 lượt).<br>✗ Đường đi xuống chỉ xảy ra khi số liệu giảm dần qua các tháng.<br>✗ Đường nằm ngang chỉ khi các tháng có số liệu bằng nhau.<br>✗ Biểu đồ quạt tròn không cho thấy sự thay đổi theo thời gian."}];

if (typeof module !== 'undefined' && module.exports) { module.exports = { MATH_CHAPTERS, MATH_QUESTIONS }; }
